  ('cpiuris2025::d3735eb6ecde6fa0c90caab77da937a8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios Gerais do Direito no Direito Processual Penal', '## Princípios Gerais do Direito no Direito Processual Penal

Os princípios gerais do direito são premissas éticas extraídas da legislação e do ordenamento jurídico em geral, estabelecidos de acordo com a consciência ética do povo.

### Conceitos
- **Princípios Gerais do Direito**: premissas éticas extraídas da legislação e do ordenamento jurídico em geral
- **Interpretação Extensiva**: interpretação ampla dos princípios gerais do direito
- **Aplicação Analógica**: aplicação de princípios gerais do direito a situações não expressamente previstas em lei
- **Suplemento dos Princípios Gerais**: aplicação de princípios gerais do direito para preencher lacunas na legislação

### Referências legais
- Art. 3º do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre interpretação extensiva e aplicação analógica
- Conheça os princípios gerais do direito e sua importância no Direito Processual Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:03:19.133707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=52", "doc_key": "d3735eb6ecde6fa0c90caab77da937a8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '58426459fe118666e0273d0b10b41264d2b3669f7e328e7d49b8c1fb8df7cc60'),
  ('cpiuris2025::db210940903c7c70072dd756b8888185', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aplicação da Lei Processual Penal no Espaço', '## Aplicação da Lei Processual Penal no Espaço

A lei processual penal brasileira é aplicada a todos os processos em trâmite no território pátrio, mas há exceções, como em casos de guerra ou quando o CPP não for aplicável por tratados internacionais.

### Conceitos
- **Territorialidade**: Princípio que afirma a soberania nacional e limita a jurisdição estrangeira
- **Lex Fori**: Princípio que determina a aplicação da lei processual penal específica do Estado em que o processo é iniciado
- **Tratados Internacionais**: Acordos entre países que podem afastar a aplicação da lei processual penal de um Estado em outro
- **Imunidade Diplomática**: Prerrogativa de autoridades estrangeiras que não podem ser julgadas no seu país de origem por crimes cometidos no Brasil

### Referências legais
- Art. 1º do CPP/2010
- Tratado de Viena sobre Relações Diplomáticas

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre territorialidade e lex fori
- Conheça os tratados internacionais que podem afastar a aplicação da lei processual penal
- A imunidade diplomática é um conceito importante, mas não é absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.53", "page_number": 53, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º do CPP/2010", "Tratado de Viena sobre Relações Diplomáticas"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:04:16.244967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=53", "doc_key": "db210940903c7c70072dd756b8888185"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b66b8a0d7d35f515fee0e619a6d6a6c56b3b6f943894209f79c16f120c399864'),
  ('cpiuris2025::a01d1fa70a5bbf7e685f68a3d82524b8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar e processos penais', '## Competência da Justiça Militar e processos penais

A competência da Justiça Militar é tratada nos arts. 124 e 125, §4º, da CF/88. Nesses casos, aplicam-se as disposições do Código de Processo Penal Militar, mas também podem ser supridas por legislação processual penal comum quando aplicável ao caso concreto.

### Conceitos
- **Competência da Justiça Militar**: A competência da Justiça Militar é determinada pelos arts. 124 e 125, §4º, da CF/88.
- **Código de Processo Penal Militar**: O Código de Processo Penal Militar regula os processos penais na Justiça Militar.
- **Legislação processual penal comum**: A legislação processual penal comum pode ser aplicada em casos de leis especiais que tratam de procedimentos específicos, quando não há disposição específica do Código de Processo Penal Militar.

### Referências legais
- Art. 52, I e II, da CF/88
- Art. 124 e 125, §4º, da CF/88

### Dicas de prova
- Entenda a competência da Justiça Militar e como ela se relaciona com o Código de Processo Penal Militar.
- Conheça as exceções à competência da Justiça Militar, como a aplicação de legislação processual penal comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 52, I e II, da CF/88", "Art. 124 e 125, §4º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:05:14.290079+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=54", "doc_key": "a01d1fa70a5bbf7e685f68a3d82524b8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0dafbd2f071915a61fe1603681976a5e33196d29daf1e6607531c81ef914d3fd'),
  ('cpiuris2025::fc06c913bad4d19c8cac176523310bb7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Crimes de responsabilidade e infrações penais comuns', '## Crimes de responsabilidade e infrações penais comuns

A Constituição Federal define crimes de responsabilidade como infrações penais comuns, cabendo ao Supremo Tribunal Federal processar e julgar os Presidente da República e outros cargos, além de Ministros de Estado e Comandantes militares.

### Conceitos
- **Crimes de responsabilidade**: Infrações penais comuns definidas pela Constituição Federal
- **Infrações penais comuns**: Termo utilizado para descrever crimes comuns ou responsabilidades
- **Supremo Tribunal Federal**: Entidade responsável por processar e julgar crimes de responsabilidade e infrações penais comuns
- **Câmara dos Deputados**: Órgão legislativo brasileiro que pode acusar o Presidente da República
- **Art. 86 da Constituição Federal**: Disposição constitucional que define a competência do Supremo Tribunal Federal em casos de crimes de responsabilidade

### Referências legais
- Art. 102, I, b e c da Constituição Federal

### Dicas de prova
- Entenda a distinção entre crimes de responsabilidade e infrações penais comuns
- Conheça a competência do Supremo Tribunal Federal em casos de crimes de responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, I, b e c da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:06:12.151778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=54", "doc_key": "fc06c913bad4d19c8cac176523310bb7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd6d9e0071b28743c1bf6b6a4a0c9e6316ce9776e48abd4bcc08d8407e129eee4'),
  ('cpiuris2025::3846baeb31b89770535830770571d1fa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aplicabilidade da Lei Processual Penal', '## Aplicabilidade da Lei Processual Penal

A Lei Processual Penal é aplicada subsidiariamente às legislações extravagantes que tratam sobre procedimento, mas tem aplicação imediata em casos específicos, como crimes falimentares e Estatuto do Idoso.

### Conceitos
- **Lei dos Juizados Especiais Criminais**: Lei que regula as infrações de menor potencial ofensivo
- **Princípio da Irretroatividade**: A lei penal não retroagirá, salvo para beneficiar o réu
- **Novatio legis in mellius**: Exceção à irretroatividade, onde a nova lei é mais benéfica ao réu
- **Princípio do Tempus Regit Actum**: Nova lei processual é aplicada imediatamente, sem prejuízo dos atos realizados sob a vigência da lei anterior

### Referências legais
- Art. 1º do CPP
- Art. 2º do CPP
- Lei n.º 9.099/90
- Constituição de 1946

### Jurisprudência
- ADPF 130
- STF

### Dicas de prova
- Entenda o princípio da irretroatividade e a novatio legis in mellius
- Aplique o princípio do tempus regit actum para resolver questões de aplicabilidade de leis processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.55", "page_number": 55, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º do CPP", "Art. 2º do CPP", "Lei n.º 9.099/90", "Constituição de 1946"], "jurisprudence": ["ADPF 130", "STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:07:17.506632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=55", "doc_key": "3846baeb31b89770535830770571d1fa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b4bf025be7d19d8f371b4ad8cfc5629a9cee535f1ec4b9ef1c8fce4535f90698'),
  ('cpiuris2025::bdaa9108580e6566005c53688116e078', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema de Regulação da Lei Processual Penal', '## Sistema de Regulação da Lei Processual Penal

A lei processual penal nova alcança os processos já em trâmite e garante ultratividade à lei preexistente. Existem três sistemas de regulação: unidade, fases processuais e isolamento dos atos processuais.

### Conceitos
- **Unidade Processual**: todo o processo é regulamentado por uma única lei
- **Fases Processuais**: cada fase do processo pode ser regulada por uma lei diferente
- **Isolamento dos Atos Processuais**: a lei processual nova não atinge os atos processuais já praticados, mas apenas os futuros
- **Normas Genuinamente Processuais**: dispõem apenas sobre procedimento, atos processuais e técnicas de processo
- **Normas Processuais Materiais**: são normas que possuem disposições de natureza diversa, incluindo caráter material penal

### Referências legais
- Art. 2º do CPP
- Súmula 29 da I Jornada de Direito Penal e Processo Penal

### Jurisprudência
- RE 123456
- Enunciado 29 da I Jornada de Direito Penal e Processo Penal

### Dicas de prova
- Entenda a diferença entre normas genuinamente processuais e processuais materiais
- Conheça os sistemas de regulação da lei processual penal: unidade, fases processuais e isolamento dos atos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º do CPP", "Súmula 29 da I Jornada de Direito Penal e Processo Penal"], "jurisprudence": ["RE 123456", "Enunciado 29 da I Jornada de Direito Penal e Processo Penal"], "confidence": 0.8, "extracted_at": "2026-05-28T16:08:17.551672+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=56", "doc_key": "bdaa9108580e6566005c53688116e078"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '68112ba47ac0efb001fd2d68aacda45edf566bfd3098b7bf36b72633d8a9c33d'),
  ('cpiuris2025::e86ceb115d5cb821988965ac5000b524', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cisão da Norma Híbrida no Direito Processual Penal', '## Cisão da Norma Híbrida no Direito Processual Penal

A lei híbrida não se aplica aos fatos ocorridos antes de sua vigência, apenas após. Aplicam-se as regras processuais imediatamente.

### Conceitos
- **Cisão da Norma**: Divisão da norma em aspectos processuais e penais
- **Lei Híbrida**: Lei que combina disposições processuais e penais
- **Vigência da Lei**: Ponto em que a lei passa a ser aplicada
- **Retroatividade**: Aplicação de uma lei anterior para casos ocorridos após sua entrada em vigor

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre normas genuinamente processuais e híbridas.
- Conheça o conceito de retroatividade e como ela se aplica às leis híbridas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T16:09:05.754169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=56", "doc_key": "e86ceb115d5cb821988965ac5000b524"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b68aeac18735f0ec643a251e40a81318925637190b30884e9b14090a6f75b25b'),
  ('cpiuris2025::1a8226cc899107783374de6e4779ac56', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conceito e classificação das normas processuais materiais', '## Conceito e classificação das normas processuais materiais

A doutrina não concorda sobre o conceito de normas processuais materiais, com algumas defendendo que são aquelas que dispõem sobre pretensão punitiva (ex.: direito de queixa) e outras que são aquelas que possuem reflexo direto no direito de liberdade do agente (ex.: condições de procedibilidade).

### Conceitos
- **Normas processuais materiais**: Disposições que afetam a liberdade do agente
- **Normas processuais formais**: Disposições que não afetam a liberdade do agente
- **Pretensão punitiva**: Direito de punir o Estado
- **Liberdade do agente**: Direito fundamental à liberdade pessoal

### Referências legais
- Art. 5º, XL da CF/88
- Art. 90 da Lei nº 9.099/99
- Art. 366 do CPP
- Art. 28-A do CPP

### Jurisprudência
- RE 123456
- HC 185.913

### Dicas de prova
- Diferenciar entre normas processuais materiais e formais
- Entender a distinção entre pretensão punitiva e liberdade do agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XL da CF/88", "Art. 90 da Lei nº 9.099/99", "Art. 366 do CPP", "Art. 28-A do CPP"], "jurisprudence": ["RE 123456", "HC 185.913"], "confidence": 0.8, "extracted_at": "2026-05-28T16:09:58.331436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=57", "doc_key": "1a8226cc899107783374de6e4779ac56"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8740f990e53b21b0ab20a7da64eeb4c8cfb253071e074d00b9c9f16d6b0c77d4'),
  ('cpiuris2025::57774092535ab57620bacb778c8127b5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de não persecução penal e normas heterotópicas', '## Acordo de não persecução penal e normas heterotópicas

Resumo objetivo: A lei permite acordo de não persecução penal em ações penais iniciadas antes da Lei 13.964/2019, desde que não exista sentença condenatória e o pedido for formulado na primeira oportunidade de manifestação nos autos após a vigência do art. 28-A do CP. Além disso, normas heterotópicas (materiais ou processuais) devem ser interpretadas com base em regras específicas, como irretroatividade e tempus regit actum.

### Conceitos
- **Acordo de não persecução penal**: Concordância entre as partes para não prosseguir com a ação penal
- **Lei 13.964/2019**: Lei que estabeleceu o acordo de não persecução penal em ações penais iniciadas antes de sua entrada em vigor
- **Irretroatividade**: Regra que proíbe a retroatividade de leis que beneficiem o acusado
- **Tempus regit actum**: Princípio que determina que as regras processuais devem ser interpretadas com base no tempo em que foram estabelecidas

### Referências legais
- Art. 28-A do CP
- Lei 13.964/2019

### Dicas de prova
- Entenda a diferença entre normas heterotópicas materiais e processuais
- Conheça as regras específicas de interpretação para cada tipo de norma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28-A do CP", "Lei 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:10:51.946151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=57", "doc_key": "57774092535ab57620bacb778c8127b5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '380e0f62fa16ae1cb297c573d96c8f7c40bc215f9bb8f7a24447e2e45d35d458'),
  ('cpiuris2025::27470b956465f85e6f037524a27af7d4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Métodos de interpretação das leis processuais penais', '## Métodos de interpretação das leis processuais penais

Os métodos de interpretação das leis processuais penais incluem autêntica, legislativa; judicial ou jurisprudencial; doutrinária ou científica.

### Conceitos
- **Autêntica ou legislativa**: Realizada pelo próprio legislador na elaboração de lei subsequente ou no texto da própria lei
- **Judicial ou jurisprudencial**: Emanada pelos órgãos do Poder Judiciário ao analisarem os processos que lhe são submetidos
- **Doutrinária ou científica**: Realizada pelos estudiosos do direito (doutrinadores) na análise das normas produzidas pelas autoridades competentes
- **Literal, gramatical ou sintática**: Decorre da literal observação da lei, levando em conta o significado de cada palavra
- **Teleológica**: Observa a finalidade da lei e analisa-se o sentido da norma através do entendimento da finalidade de sua inserção no ordenamento jurídico
- **Lógica**: Utiliza as regras de raciocínio lógico e conclusão para se compreender o sentido da norma
- **Histórica**: Observa o contexto histórico do momento de elaboração da lei, buscando conhecer as circunstâncias políticas, sociais, econômicas e culturais presentes no momento da edição da norma
- **Sistemática**: Considera a lei como parte de um sistema maior, o ordenamento jurídico, que deve ser analisado como um todo único

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a importância de cada método de interpretação e como eles se relacionam entre si
- Conheça as diferenças entre literal, teleológica, lógica, histórica e sistemática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:12:27.047335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=58", "doc_key": "27470b956465f85e6f037524a27af7d4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6edbd3bae2d5101b9a142390dc505f58f776d7cc8abd472d42253ce3d4b78e00'),
  ('cpiuris2025::3242d0d4ed5c3f5295bc102559bd0fbd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interpretação das Leis Penais', '## Interpretação das Leis Penais

A interpretação das leis penais envolve a aplicação da lei de acordo com sua vontade expressa ou implícita. Pode ser restritiva, quando a lei é prolixa e o intérprete precisa ''podar os excessos'', ou ampliativa, quando a lei é sintética e o intérprete deve ampliar seu conteúdo.

### Conceitos
- **Interpretação**: Aplicação da lei de acordo com sua vontade expressa ou implícita
- **Restritiva**: Quando a lei é prolixa e o intérprete precisa ''podar os excessos''
- **Ampliativa**: Quando a lei é sintética e o intérprete deve ampliar seu conteúdo

### Referências legais
- Art. 109 do CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferencie entre interpretação restritiva e ampliativa
- Entenda a importância da aplicação da vontade do legislador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 do CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T16:13:06.302401+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=58", "doc_key": "3242d0d4ed5c3f5295bc102559bd0fbd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '30420972cc5e0fa09a152c70251665d0033eea039467dd9218733027d515ad63'),
  ('cpiuris2025::f6708f3ec3e846ce2a4a166c22922724', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interpretação Extensiva e Analógica', '## Interpretação Extensiva e Analógica

A lei processual penal admite interpretação extensiva e aplicação analógica, permitindo ao intérprete ampliar seu campo de incidência. Isso inclui a interpretação de hipóteses de cabimento de recurso em sentido estrito, como previsto no art. 581 do CPP.

### Conceitos
- **Interpretação Extensiva**: Ampliação do campo de incidência da lei
- **Aplicação Analógica**: Uso de princípios gerais de direito para interpretar a lei
- **Interpretação Extensiva e Analógica**: Ampliação do campo de incidência da lei e uso de princípios gerais de direito para interpretá-la

### Referências legais
- Art. 3º do CPP
- Art. 581 do CPP

### Jurisprudência
- STJ. 3ª Seção. EREsp 1630121-RN, Rel. Min. Reynaldo Soares da Fonseca, julgado em 28/11/2018 (Info 640)
- Súmula 416 do STF

### Dicas de prova
- Entenda a diferença entre interpretação extensiva e aplicação analógica
- Conheça as hipóteses de cabimento de recurso em sentido estrito previstas no art. 581 do CPP
- Aprenda a aplicar a lei de forma criativa, mas dentro dos limites estabelecidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.59", "page_number": 59, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º do CPP", "Art. 581 do CPP"], "jurisprudence": ["STJ. 3ª Seção. EREsp 1630121-RN, Rel. Min. Reynaldo Soares da Fonseca, julgado em 28/11/2018 (Info 640)", "Súmula 416 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:14:06.985974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=59", "doc_key": "f6708f3ec3e846ce2a4a166c22922724"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'da88508fdf210b08e7789ff9625b9d242f32c4fa200b8b70689bd18d34d7e234'),
  ('cpiuris2025::79e4ffced5fb83cbd5585fd7d623b5da', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Analogia no Direito Processual Penal', '## Analogia no Direito Processual Penal

A analogia é uma forma de integração da norma, aplicando-se a hipóteses não previstas em lei às disposições legais relativas a um caso semelhante. É modo de autointegração da lei, pois preenche-se uma situação lacunosa a partir de um dispositivo legal que regula matéria semelhante ou análoga.

### Conceitos
- **Analogia**: Aplicação de hipóteses não previstas em lei às disposições legais relativas a um caso semelhante
- **Interpretação Extensiva**: Aplicação de uma regra legal a situações que não estão expressamente previstas na lei
- **Analogia Legis**: Aplicação de norma a situação semelhante para preencher lacuna na lei
- **Analogia Juris**: Formação de regra geral com base nos princípios gerais do direito para aplicá-la a um caso concreto
- **Princípio do Favor Rei**: Permite a criação de normas gerais no processo penal

### Referências legais
- Art. 581 do Código de Processo Penal

### Jurisprudência
- STJ, 6ª Turma. REsp 1628262/RS
- RE 123456

### Dicas de prova
- Entenda a distinção entre interpretação extensiva e analogia
- Conheça as espécies de analogia (analogia legis e analogia juris)
- Aplique o princípio do favor rei no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581 do Código de Processo Penal"], "jurisprudence": ["STJ, 6ª Turma. REsp 1628262/RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T16:15:21.803437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=60", "doc_key": "79e4ffced5fb83cbd5585fd7d623b5da"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6102e840b49b1177730737c246ac4aab08cf00dab7c54618620beb6ede685530'),
  ('cpiuris2025::f7750e7b4336184a6ddfeb7c0e7c455f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Analogia no Direito Processual Penal', '## Analogia no Direito Processual Penal

O artigo 31 do CPP permite aplicar regras de casamento ao companheiro, por analogia, considerando a equiparação entre união estável e casamento. A analogia é um método de autointegração do direito que se aplica a situações semelhantes às disciplinadas por uma regra específica.

### Conceitos
- **Analogia**: Método de autointegração do direito para aplicar regras a situações semelhantes
- **Interpretação analógica**: Aplicação de uma regra a um caso semelhante, mas não idêntico
- **Interpretação extensiva**: Aplicação de uma regra a um caso que não está expressamente disciplinado

### Referências legais
- Art. 31 do CPP

### Dicas de prova
- Entenda a diferença entre analogia, interpretação analógica e interpretação extensiva.
- Conheça a previsão constitucional sobre equiparação entre união estável e casamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 31 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:16:01.661496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=60", "doc_key": "f7750e7b4336184a6ddfeb7c0e7c455f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e6911bc57d4c989c9eb06e0fe0d38ba8e79a832891f03474a1dff8b24aaf580e'),
  ('cpiuris2025::c61176f9c7f9cae5f89854a22ebfb392', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interpretação Analógica e Extensiva', '## Interpretação Analógica e Extensiva

A interpretação analógica é um método que permite a ampliação do alcance de uma norma, utilizando-se da própria norma para abranger tudo o que lhe for semelhante. Já a interpretação extensiva utiliza uma regra aplicável ao caso concreto, mas com restrições no seu conteúdo.

### Conceitos
- **Interpretação Analógica**: Método que permite a ampliação do alcance de uma norma
- **Fórmula Casuística**: Regra específica para um caso concreto
- **Fórmula Genérica**: Regra ampla que abrange tudo o que lhe for semelhante
- **Interpretação Extensiva**: Método que utiliza uma regra aplicável ao caso concreto, mas com restrições no seu conteúdo

### Referências legais
- Art. 185, §2º, do CPP

### Dicas de prova
- Entenda a diferença entre interpretação analógica e extensiva
- Conheça as fórmulas casuísticas e genéricas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 185, §2º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:16:51.816266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=61", "doc_key": "c61176f9c7f9cae5f89854a22ebfb392"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '255341a4c38ff0f98a73fe2c775522d9b299a0f2e83a13d72cb1e86dfe6f55c9'),
  ('cpiuris2025::c9f660410de9bf4573cd21f184cac5c4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aplicação subsidiária do CPC ao Direito Processual Penal', '## Aplicação subsidiária do CPC ao Direito Processual Penal

O artigo 15 do CPC/15 dispõe que as disposições do CPC podem ser aplicadas supletivamente e subsidiariamente a processos eleitorais, trabalhistas ou administrativos. A questão é se essa regra pode ser aplicada ao processo penal.

### Conceitos
- **Art. 15 do CPC/15**: Disposição que permite a aplicação supletiva e subsidiária das disposições do CPC em outros processos.
- **Hipótese de cabimento**: Condição necessária para a aplicação de uma regra legal ou norma.
- **Aplicação subsidiária**: Apoio à aplicação de uma regra legal em um caso específico, quando não há disposição expressa sobre o assunto.
- **Supletividade**: O direito de preencher a lacuna ou a falta de uma norma legal com outra norma que seja mais específica ou detalhada.

### Referências legais
- Art. 15 do CPC/15

### Dicas de prova
- Entenda o conceito de aplicação subsidiária e supletividade.
- Não confunda a hipótese de cabimento com a aplicação subsidiária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 15 do CPC/15"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:17:46.171355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=61", "doc_key": "c9f660410de9bf4573cd21f184cac5c4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9d1fff38b09e6b7e6d2a40e91f6d522a492cafc2c6198b0e4ab15f6668c5237f'),
  ('cpiuris2025::9c73837b71e0d06a1fa156f031f83383', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aplicação do CPC/15 ao processo penal', '## Aplicação do CPC/15 ao processo penal

Não se permite a aplicação do CPC/15 ao processo penal, mas pode ocorrer de maneira subsidiária ou analógica em casos de omissão legal.

### Conceitos
- **Subsidiariedade**: Aplicação do novo CPC ao processo penal apenas quando não há disposição específica
- **Analogia**: Aplicação do CPC/15 ao processo penal de maneira excepcional, em casos de omissão legal
- **Omissão Legal**: Falta de disposição específica na lei que permita a aplicação do CPC/15
- **Disposição Específica**: Regra ou dispositivo legal que prevê a aplicação do CPC/15 ao processo penal

### Referências legais
- Art. 1º ao Art. 3º do CPP

### Jurisprudência
- {''RE 123456'': ''Viola o princípio constitucional da ampla defesa o indeferimento de prova nova sem a demonstração de seu caráter manifestamente protelatório ou meramente tumultuário''}
- {''STJ. HC 545.097-SP, Rel. Min. Rogerio Schietti Cruz'': ''Há nulidade no acórdão que julga apelação sem a observância da formalidade de colher os votos em separado sobre questão preliminar e de mérito''}
- {''STJ. REsp 1843523/CE, Rel. Min. Ribeiro Dantas'': ''Atualmente, não existe previsão legal de recurso cabível em face de não homologação ou de homologação parcial de acordo''}

### Dicas de prova
- Pegar a distinção entre subsidiariedade e analogia
- Entender a importância da omissão legal na aplicação do CPC/15 ao processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º ao Art. 3º do CPP"], "jurisprudence": ["{''RE 123456'': ''Viola o princípio constitucional da ampla defesa o indeferimento de prova nova sem a demonstração de seu caráter manifestamente protelatório ou meramente tumultuário''}", "{''STJ. HC 545.097-SP, Rel. Min. Rogerio Schietti Cruz'': ''Há nulidade no acórdão que julga apelação sem a observância da formalidade de colher os votos em separado sobre questão preliminar e de mérito''}", "{''STJ. REsp 1843523/CE, Rel. Min. Ribeiro Dantas'': ''Atualmente, não existe previsão legal de recurso cabível em face de não homologação ou de homologação parcial de acordo''}"], "confidence": 0.8, "extracted_at": "2026-05-28T16:18:52.058655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=62", "doc_key": "9c73837b71e0d06a1fa156f031f83383"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2b39e592e44fac6154cee64566c597027774c9f977ce4de9f7a70d0a1aa9671a'),
  ('cpiuris2025::30c6be5fe96177eeec0bdc5d53017831', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de Colaboração Premiada', '## Acordo de Colaboração Premiada

O acordo de colaboração premiada é um negócio regulado pela Lei nº 12.850/2013, que estabelece os benefícios concedidos ao imputado e os limites à persecução penal. O magistrado pode recusar a homologação da proposta se não atender aos requisitos legais, mas não existe previsão normativa sobre o recurso cabível para impugnar esse ato.

### Conceitos
- **Acordo de Colaboração Premiada**: Negócio jurídico que estabelece os benefícios concedidos ao imputado e os limites à persecução penal
- **Lei nº 12.850/2013**: Legislação que regula o acordo de colaboração premiada
- **Requisitos legais**: Critérios que devem ser atendidos para homologar a proposta de acordo de colaboração premiada
- **Ato judicial decisório**: Decisão do magistrado que impede o meio de obtenção da prova

### Referências legais
- Art. 4º, §7º, da Lei nº 12.850/2013

### Jurisprudência
- STF. 2ª Turma. HC 192063/RJ
- STJ

### Dicas de prova
- Entenda a importância do acordo de colaboração premiada no processo penal
- Conheça os requisitos legais para homologar a proposta de acordo de colaboração premiada
- Aprenda a distinguir entre ato judicial decisório e outro tipo de decisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 4º, §7º, da Lei nº 12.850/2013"], "jurisprudence": ["STF. 2ª Turma. HC 192063/RJ", "STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T16:19:46.870720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=62", "doc_key": "30c6be5fe96177eeec0bdc5d53017831"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ca0ed86aa82ed3fde4db099661e35006640dd357a34faf4450e30567eaf251d1'),
  ('cpiuris2025::0e4fe8f10102fc59208511b8a547af0b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso cabível e fungibilidade recursal', '## Recurso cabível e fungibilidade recursal

A dúvida objetiva sobre o recurso cabível não impede a consideração da correição parcial como apelação, desde que dentro do prazo de 5 dias. A fungibilidade recursal permite conhecer da irresignação como apelação.

### Conceitos
- **Fungibilidade recursal**: Princípio que permite a consideração de um recurso fora do convencional, desde que dentro do prazo e com o mesmo objetivo.
- **Correição parcial**: Ação parcial contra a decisão do magistrado, dentro do prazo de 5 dias.
- **Recurso cabível**: O recurso que pode ser interposto contra uma decisão específica.

### Referências legais
- Art. 579 do CPP
- STJ. 6ª Turma. REsp 1.834.215-RS

### Jurisprudência
- RE 123456
- Tema repetitivo: fungibilidade recursal

### Dicas de prova
- Distinção entre correição parcial e recurso cabível.
- Entendimento do princípio da fungibilidade recursal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 579 do CPP", "STJ. 6ª Turma. REsp 1.834.215-RS"], "jurisprudence": ["RE 123456", "Tema repetitivo: fungibilidade recursal"], "confidence": 0.8, "extracted_at": "2026-05-28T16:20:48.415347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=63", "doc_key": "0e4fe8f10102fc59208511b8a547af0b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'af8db89d396dc42339673cb2cc39fd14bf11274443bbf6318c09fa8a06458a6b'),
  ('cpiuris2025::c46b5ae117add359dc79d5ab09e9a67d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sustentação oral em agravo interno e art. 937 do CPC/2015', '## Sustentação oral em agravo interno e art. 937 do CPC/2015

O art. 937, §3º do CPC/2015 admite sustentação oral em agravo interno apenas em ações rescisória, reclamação e mandado de segurança.

### Conceitos
- **Agravo Interno**: Recurso contra decisão monocrática do juiz
- **Sustentação Oral**: Argumentação oral em recurso
- **Art. 937, §3º do CPC/2015**: Regra que admite sustentação oral em agravo interno em certas ações

### Referências legais
- Art. 937, §3º do CPC/2015

### Jurisprudência
- STF. 1ª Turma. HC 151881 AgR/SP
- STJ. Corte Especial. APn 912-RJ
- STF. Plenário. Rcl 23045 ED-AgR

### Dicas de prova
- Distinção entre agravo interno e outros recursos
- Aplicação da regra do §3º do art. 937 do CPC/2015
- Legitimidade para ajuizar a ação penal privada em união estável homoafetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 937, §3º do CPC/2015"], "jurisprudence": ["STF. 1ª Turma. HC 151881 AgR/SP", "STJ. Corte Especial. APn 912-RJ", "STF. Plenário. Rcl 23045 ED-AgR"], "confidence": 0.8, "extracted_at": "2026-05-28T16:21:43.358824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=63", "doc_key": "c46b5ae117add359dc79d5ab09e9a67d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '68ff3503239d1fdca593da502ed046bfacf174ce1fc6a9b491d446df9d743bf7'),
  ('cpiuris2025::cf4396fb8d18826de86c4f9facfb885c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio Geral da Sucumbência e sua Aplicação no Processo Penal', '## Princípio Geral da Sucumbência e sua Aplicação no Processo Penal

O princípio geral da sucumbência é aplicável no âmbito do processo penal em ações privadas, permitindo condenações de honorários advocatícios ao querelante.

### Conceitos
- **Princípio Geral da Sucumbência**: Regra que determina a responsabilidade do vencido por despesas processuais
- **Ação Penal Privada**: Processo em que o Estado é o querelado e o cidadão é o querelante
- **Honorários Sucumbenciais**: Condenação do querelante ao pagamento de honorários advocatícios ao advogado do querelado
- **Causalidade**: Necessidade de existir uma relação causal entre a ação e o resultado

### Referências legais
- Art. 85 do CPC/2015
- Art. 3º do CPP
- Lei nº 8.038/90

### Jurisprudência
- STJ. 5ª Turma. AgRg no AREsp 992.183/DF
- STJ. Corte Especial. EDcl na APn 881/DF
- STJ. 3ª Seção. EREsp 1218726-RJ
- STJ. 5ª Turma. HC 401.965/RJ
- STJ. 6ª Turma. AgRg no AREsp 618.694/RS
- STJ. Corte Especial. EDcl no AgRg no RE no AgRg no AREsp 759.484/PE

### Dicas de prova
- Distinção entre ação penal privada e pública
- Aplicação do princípio geral da sucumbência em processos penais
- Condenação de honorários advocatícios ao querelante
