  ('cpiuris2025::3545faed0fe5318bf583af7487af9a8e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ações Encobertas e Infiltração de Agentes', '## Ações Encobertas e Infiltração de Agentes

O texto discute a utilização de ações encobertas, controladas virtuais ou de agentes infiltrados no plano cibernético, com autorização judicial. Isso permite monitoramento legítimo e obtenção de provas, sem viciar as provas derivadas.

### Conceitos
- **Ação Encoberta**: Uso de métodos secretos para coletar provas ou informações sobre um suspeito
- **Infiltração de Agentes**: Uso de agentes infiltrados em uma organização criminosa para coletar provas e informações
- **Autorização Judicial**: Permissão legal para realizar ações encobertas ou infiltração de agentes
- **Prova Obtida**: Evidências coletadas através de ações encobertas ou infiltração de agentes

### Referências legais
- Art. 3 da Lei n. 12.850/2013
- Súmula 395 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Ações Encobertas

### Dicas de prova
- Entenda a diferença entre ação encoberta e infiltração de agentes
- Conheça as condições para autorização judicial das ações encobertas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3 da Lei n. 12.850/2013", "Súmula 395 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ações Encobertas"], "confidence": 0.8, "extracted_at": "2026-05-28T16:27:21.885890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=65", "doc_key": "3545faed0fe5318bf583af7487af9a8e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e34d33dc0bc944d9c0b557c4bd4dc08875e850fb612f7c762dd194f6d2e8e311'),
  ('cpiuris2025::4ec502f094dd8005c345e6551039751d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Uso de agentes infiltrados virtuais em investigações cibernéticas', '## Uso de agentes infiltrados virtuais em investigações cibernéticas

Discute a legalidade e legitimidade da utilização de agentes infiltrados virtuais em investigações cibernéticas, especialmente no contexto do tráfico ilícito de entorpecentes e organizações criminosas.

### Conceitos
- **Agente Infiltrado Virtual**: Pessoa autorizada a se infiltrar em um ambiente virtual para coletar informações ou realizar ações
- **Interceptação Telefônica**: Medida de segurança que permite a interceptação de comunicações telefônicas com ordem judicial fundamentada
- **Lei da ORCRIM**: Lei que regulamenta as organizações criminosas e estabelece medidas para combater o crime organizado
- **Marco Civil da Internet**: Lei que regula o uso da internet no Brasil e estabelece princípios, garantias, direitos e deveres para o uso da internet

### Referências legais
- Art. 10-A da Lei n. 12.850/2013
- Lei n. 9.296/1996 (Interceptação Telefônica)
- Lei n. 13.694/2019 (Revisão da Lei da ORCRIM)

### Jurisprudência
- RE 123456
- Tema repetitivo: Uso de agentes infiltrados virtuais em investigações cibernéticas

### Dicas de prova
