  ('cpiuris2025::a68a1c894610fee23e2d0b931129c77c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Controlada e Infiltrada Virtual', '## Ação Controlada e Infiltrada Virtual

A ação controlada e infiltrada virtual é permitida desde que observadas a cláusula de reserva de jurisdição e a finalidade para investigação criminal, considerando-se o equilíbrio dos valores constitucionais em jogo.

### Conceitos
- **Ação Controlada**: ação processual que visa controlar ou influenciar um processo judicial existente
- **Ação Infiltrada**: ação processual que visa infiltrar-se em um processo judicial existente para obter vantagens indevidas
- **Cláusula de Reserva de Jurisdição**: previsão legal que estabelece limites à competência do juiz ou tribunal
- **Finalidade para Investigação Criminal**: motivo legítimo para a realização de investigações criminais

### Referências legais
- Art. 319 do Código de Processo Penal

### Dicas de prova
- Entenda o conceito de ação controlada e infiltrada virtual
