  ('cpiuris2025::3f9dd65b82d2da34b8c7a4ca29661c6b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Uso da ação controlada e do agente infiltrado no combate à criminalidade organizada', '## Uso da ação controlada e do agente infiltrado no combate à criminalidade organizada

A lei estabelece que o uso de ações encobertas ou agentes infiltrados é permitido na persecução de delitos, desde que observadas as condições de proporcionalidade e subsidiariedade.

### Conceitos
- **Ação controlada**: Técnica de investigação utilizada para combater a criminalidade organizada
- **Agente infiltrado**: Pessoa que se infiltra em uma organização criminosa para coletar provas
- **Proporcionalidade**: Critério de justificação do uso de ações encobertas ou agentes infiltrados
- **Subsidiariedade**: Requisito para o uso de ações encobertas ou agentes infiltrados

### Referências legais
- Art. 3 da Lei Processual Penal

