  ('cpiuris2025::5488132c3b9e00449cb1a232f00c6aef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Uso do espelhamento no WhatsApp Web como meio de infiltração investigativa', '## Uso do espelhamento no WhatsApp Web como meio de infiltração investigativa

O uso do espelhamento no WhatsApp Web para obter provas é plausível, desde que respeitados os parâmetros de proporcionalidade, subsidiariedade, controle judicial e legalidade.

### Conceitos
- **Proporcionalidade**: A necessidade de garantir que a medida adotada seja necessária e não exceda o que é necessário para alcançar o objetivo da investigação.
- **Subsidiariedade**: A obrigação do Estado de buscar todas as formas possíveis antes de recorrer a uma medida mais invasiva, como o espelhamento.
- **Controle judicial e legalidade**: O dever do Estado de obter um mandado judicial competente antes de adotar medidas de infiltração investigativa.

### Referências legais
- Art. 9.296/1996
- Lei n. 12.850/2013

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a proporcionalidade e subsidiariedade do uso do espelhamento no WhatsApp Web.
- Conheça as regras de controle judicial e legalidade para medidas de infiltração investigativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 9.296/1996", "Lei n. 12.850/2013"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T16:30:48.461267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=66", "doc_key": "5488132c3b9e00449cb1a232f00c6aef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1f077500ed61a5847067efa5adb8a881bb1d561a4c9657e569682ec2871fae2a'),
  ('cpiuris2025::0986fd953bdf3ba092fcba18bcccb817', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Quebra da cadeia de custódia e prazo do agravo', '## Quebra da cadeia de custódia e prazo do agravo

A quebra da cadeia de custódia refere-se à idoneidade do caminho que deve ser percorrido pela prova até sua análise pelo magistrado. O prazo do agravo é de 5 dias, contados em dias corridos.

### Conceitos
- **Quebra da cadeia de custódia**: Idoneidade do caminho que deve ser percorrido pela prova até sua análise pelo magistrado
- **Prazo do agravo**: 5 dias, contados em dias corridos

### Referências legais
- Art. 39 da Lei nº 8.038/90
- Art. 798 do CPP
- Art. 1.070 do CPC
- Art. 1.035 §5º do CPC

### Jurisprudência
- AgRg no RHC n. 129.003/MT
- AgRg no RHC n. 147.885/SP
- RE 134554
- AREsp n. 2.309.888/MG

### Dicas de prova
- Entenda a diferença entre quebra da cadeia de custódia e prazo do agravo.
- Conheça as regras para contagem de prazos em processos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 39 da Lei nº 8.038/90", "Art. 798 do CPP", "Art. 1.070 do CPC", "Art. 1.035 §5º do CPC"], "jurisprudence": ["AgRg no RHC n. 129.003/MT", "AgRg no RHC n. 147.885/SP", "RE 134554", "AREsp n. 2.309.888/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T16:32:29.029097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=67", "doc_key": "0986fd953bdf3ba092fcba18bcccb817"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0bd95f0b57d7ad87e21a81dc8d79cb955164d23202223a487236a3abaa73bde7'),
  ('cpiuris2025::4022dd5eb0c58faca12f25f77225ce69', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sobrestamento de processos penais', '## Sobrestamento de processos penais

O STF estabeleceu regras para o sobrestamento de processos penais, incluindo a suspensão da prescrição e a exclusão de inquéritos policiais.

### Conceitos
- **Repercussão Geral**: Condição necessária para a aplicação do §5º do art. 1.035 do CPC
- **Sobrestamento**: Mudança da data de julgamento de processos criminais pendentes
- **Suspensão da Prescrição**: Prazo para a ação penal não se esgotar
- **Inquéritos Policiais**: Procedimentos investigatórios conduzidos pelo MP

### Referências legais
- Art. 116, I do Código Penal
- Súmula 667 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de Repercussão Geral e sua importância
- Conheça as regras para o Sobrestamento de processos penais
- Identifique quando a Suspensão da Prescrição é aplicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 116, I do Código Penal", "Súmula 667 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T16:32:41.956392+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=67", "doc_key": "4022dd5eb0c58faca12f25f77225ce69"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '981bffb4e4510565178dc465ab84a649183a49d948cd34c37b69a700882008b4'),
  ('cpiuris2025::85c8136b7a4b8e3a36b3e78fc85a0ca0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sobrestamento de processos penais e direitos das partes', '## Sobrestamento de processos penais e direitos das partes

O artigo 1.035, §5º, do CPC estabelece que o sobrestamento de processos penais não abrange ações em que haja réu preso provisoriamente. Além disso, o juiz pode proceder à produção de provas urgentes durante a suspensão do processo.

### Conceitos
- **Sobrestamento de processos penais**: Princípio que permite a continuidade do processo após a conclusão da investigação
- **Réu preso provisoriamente**: Pessoa condenada provisoriamente, que não pode ser libertada até o final do processo
- **Produção de provas urgentes**: Procedimento que permite a produção de provas relevantes para o caso em andamento

### Referências legais
- Art. 1.035, §5º, do CPC

### Jurisprudência
- Súmula 699 do STF

### Dicas de prova
- Entenda a noção de sobrestamento de processos penais e suas limitações.
- Conheça o princípio da anterioridade e sua aplicação às leis novas em processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1.035, §5º, do CPC"], "jurisprudence": ["Súmula 699 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:33:09.645001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=68", "doc_key": "85c8136b7a4b8e3a36b3e78fc85a0ca0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '73900a5f3181ce9b75960e386ab548873ce1ca55c821562d3849864b4285e6db'),
  ('cpiuris2025::a30e774844ce8a5dbe6d2dd6b99e3682', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Lei que regerá o processo e princípios gerais', '## Lei que regerá o processo e princípios gerais

A lei que regerá o processo é a lei do momento em que foi praticado o crime, de acordo com o princípio tempus regit actum. Além disso, a unidade processual significa que uma única lei deve reger todo o processo, mas a lei velha não se aplica à nova lei.

### Conceitos
- **tempus regit actum**: Princípio que determina que a lei que regerá o processo é a lei do momento em que foi praticado o crime
- **unidade processual**: Sistema que determina que uma única lei deve reger todo o processo
- **princípio da reserva legal**: Princípio que proíbe a aplicação de leis revogadas em processos já iniciados

### Referências legais
- Art. 107 do Código de Processo Penal

### Jurisprudência
- Súmula 387/STF
- ...

### Dicas de prova
- Entenda o princípio tempus regit actum e a unidade processual
- Conheça as exceções à aplicação da lei revogada em processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 107 do Código de Processo Penal"], "jurisprudence": ["Súmula 387/STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T16:34:47.602188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=68", "doc_key": "a30e774844ce8a5dbe6d2dd6b99e3682"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '77d939d4bcb73cc55a0d264d04b7de5b82491a63dae48ded9b8565f535484b39'),
  ('cpiuris2025::02f27ff7bb63be05f5d8c898275ca11c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aplicação da Lei Processual Penal', '## Aplicação da Lei Processual Penal

A lei processual penal admite a aplicação analógica e interpretação extensiva, mas apenas aos processos em curso, não sendo aplicada aos processos ainda em fase de investigação.

### Conceitos
- **Aplicação Analógica**: Apoio à aplicação da lei processual penal a situações não expressamente previstas pela lei
- **Interpretação Extensiva**: Apoio à interpretação abrangente da lei processual penal para incluir novas regras ou conceitos
- **Princípio Tempus Regit Actum**: Regra que determina a aplicação imediata da lei processual penal aos processos em curso
- **Princípio do Tempus Delicti**: Regra que determina a aplicação da lei penal à fase de investigação

### Referências legais
- Art. 2º do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre aplicação analógica e interpretação extensiva
- Entender o princípio tempus regit actum e tempus delicti', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.69", "page_number": 69, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T16:35:02.100935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=69", "doc_key": "02f27ff7bb63be05f5d8c898275ca11c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '67652f955a5d59da9a668ffa5ee40031feba3a61f8ea9e605fb0aeb6dc0f3dfc'),
  ('cpiuris2025::6387cfd34d6901e7242eb332d73a3f5c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Juiz das Garantias', '## Juiz das Garantias

A Lei/Pacote Anticrime criou a figura do Juiz das Garantias, um magistrado que atua exclusivamente na fase de investigação penal, mantendo a imparcialidade e afastando-se da atuação no processo.

### Conceitos
- **Competência funcional**: Nova hipótese de competência para um magistrado
- **Fase de investigação penal**: Etapa do processo onde o juiz das garantias atua
- **Imparcialidade**: Característica fundamental da atividade jurisdicional
- **Pacote Anticrime**: Lei que criou a figura do Juiz das Garantias e outras inovações no Direito Processual Penal

### Referências legais
- Art. 102 da Lei n.º 13.964/2019

### Jurisprudência
- {''term'': ''Súmula 636 do STF'', ''definition'': ''Declara a constitucionalidade da figura do Juiz das Garantias''}

### Dicas de prova
- Entenda a competência funcional e sua importância no Direito Processual Penal
- Conheça as características fundamentais da atividade jurisdicional
- Aprenda sobre o Pacote Anticrime e suas inovações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 da Lei n.º 13.964/2019"], "jurisprudence": ["{''term'': ''Súmula 636 do STF'', ''definition'': ''Declara a constitucionalidade da figura do Juiz das Garantias''}"], "confidence": 0.8, "extracted_at": "2026-05-28T16:36:01.226675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=71", "doc_key": "6387cfd34d6901e7242eb332d73a3f5c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '98ec4de2825f562eb28a0d60c0468ec55fae1d79911be0c979954f80347cbbb8'),
  ('cpiuris2025::9de843026f2506c974e8673c3e0cb53b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Iniciativa do Juiz das Garantias', '## Iniciativa do Juiz das Garantias

A Lei estabelece que o processo penal terá estrutura acusatória, vedada a iniciativa do juiz nas fases de investigação e substituição da atuação probatória do órgão de acusação.

### Conceitos
- **Iniciativa do Juiz**: A capacidade do juiz de tomar medidas iniciais no processo penal
- **Fase de Investigação**: O período em que o juiz não pode tomar iniciativas
- **Estrutura Acusatória**: A organização do processo penal com base na acusação

### Referências legais
- Art. 3º-A, CPP

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a estrutura do processo penal e a limitação da iniciativa do juiz
- Conheça o artigo 156 do CPP e sua relação com o art. 3º-A', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-A, CPP"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:36:49.664336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=71", "doc_key": "9de843026f2506c974e8673c3e0cb53b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '756e2ce8ae77e0ce38cb01a68b17779363936b32caefde478d7accfa8ce181f5'),
  ('cpiuris2025::af6522aaf7a5ee1e1c69d06d2108996a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Juiz das Garantias', '## Juiz das Garantias

O juiz das garantias é responsável pelo controle da legalidade da investigação criminal e pela salvaguarda dos direitos individuais. Ele tem atribuições específicas, incluindo o controle da legalidade da investigação criminal e a salvaguarda dos direitos individuais.

### Conceitos
- **Controle da legalidade da investigação criminal**: A responsabilidade do juiz das garantias em verificar a legalidade da investigação criminal
- **Salvaguarda dos direitos individuais**: A proteção dos direitos individuais cuja franquia tenha sido reservada à autorização prévia do Poder Judiciário

### Referências legais
- Art. 3º-B, caput, do CPP

### Dicas de prova
- Entenda a responsabilidade do juiz das garantias em controlar a legalidade da investigação criminal e proteger os direitos individuais.
- Conheça as atribuições específicas do juiz das garantias, como o controle da legalidade da investigação criminal e a salvaguarda dos direitos individuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:37:06.529353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=72", "doc_key": "af6522aaf7a5ee1e1c69d06d2108996a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2dc9a0190b4bd6bbcb67c7443a632358dfa860e98049ca406835bf3d97899e20'),
  ('cpiuris2025::caca0c57fd8e72ba6d3dcd3fa1468d08', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Controle da legalidade da investigação criminal e salvaguarda dos direitos individuais', '## Controle da legalidade da investigação criminal e salvaguarda dos direitos individuais

O juiz das garantias tem competência para controlar a legalidade da investigação criminal e proteger os direitos individuais reservados à autorização prévia do Poder Judiciário.

### Conceitos
- **Juiz das Garantias**: Magistrado responsável pelo controle da legalidade da investigação criminal
- **Investigação Criminal**: Procedimento que visa apurar a existência de um crime
- **Direitos Individuais**: Bens e direitos protegidos pela Constituição
- **Autorização Prévia**: Requisito para a realização de medidas de investigação criminal

### Referências legais
- Art. 3º-B do Código de Processo Penal

### Jurisprudência
- ADI 6.298/2019
- ADI 6.299/2019
- ADI 6.300/2019
- ADI 6.305/2019

### Dicas de prova
- Entenda a competência do Juiz das Garantias e sua importância no controle da investigação criminal.
- Conheça os direitos individuais protegidos pela Constituição e como eles são salvaguardados pelo Poder Judiciário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B do Código de Processo Penal"], "jurisprudence": ["ADI 6.298/2019", "ADI 6.299/2019", "ADI 6.300/2019", "ADI 6.305/2019"], "confidence": 0.8, "extracted_at": "2026-05-28T16:37:25.404368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=72", "doc_key": "caca0c57fd8e72ba6d3dcd3fa1468d08"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f6c6bb95dd2111519df7c0baa6782c30b3f8c3a7604b8d0dc5cb348177b1e29b'),
  ('cpiuris2025::39ba09f469682a6966583d091b25393b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Custódia e Controle Judicial', '## Audiência de Custódia e Controle Judicial

O juiz das garantias deve realizar a audiência de custódia no prazo estabelecido, caso contrário, a prisão é considerada ilegal. O STF atribuiu interpretação conforme ao art. 310 do CPP para permitir a realização da audiência por videoconferência em casos de urgência.

### Conceitos
- **Audiência de Custódia**: procedimento judicial que visa garantir a segurança do acusado
- **Controle Judicial**: mecanismo que visa garantir a legalidade dos atos do Ministério Público
- **Videoconferência**: método de comunicação remota para realizar audiências
- **Prisão Provisória**: medida cautelar que visa garantir a segurança do acusado
- **Contraditório**: direito do acusado de se manifestar em audiência pública e oral

### Referências legais
- Art. 310 do CPP
- Súmula 89.837/DF

### Jurisprudência
- ADI 6.298
- ADI 6.299
- ADI 6.300
- ADI 6.305

### Dicas de prova
- Entenda a importância da audiência de custódia e do controle judicial no processo penal.
- Conheça as exceções à realização da audiência de custódia, como a videoconferência.
- Avalie a relevância do contraditório em casos de prisão provisória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310 do CPP", "Súmula 89.837/DF"], "jurisprudence": ["ADI 6.298", "ADI 6.299", "ADI 6.300", "ADI 6.305"], "confidence": 0.8, "extracted_at": "2026-05-28T16:40:24.408288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=74", "doc_key": "39ba09f469682a6966583d091b25393b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c5359713d62010b371ba7546efe6a37d8afa05dd5f429a8e1f5f6c7e0adabe40'),
  ('cpiuris2025::776546328fb3300da04188a8ff90d4a4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Custo e Prisão Preventiva', '## Audiência de Custo e Prisão Preventiva

O juiz das garantias realizará audiência com a presença do Ministério Público e da Defensoria Pública ou advogado constituído, dentro de 24 horas, salvo impossibilidade fática. O juiz também aplicará o art. 310 do CPP para decidir sobre a prisão preventiva.

### Conceitos
- **Audiência de Custo**: reunião com o preso e seus representantes
- **Prisão Preventiva**: medida cautelar para garantir a ordem pública e segurança
- **Ministério Público**: órgão responsável por promover a justiça
- **Defensoria Pública**: órgão que defende os direitos dos presos
- **Advogado Constituído**: advogado nomeado pelo preso para defender seus interesses
- **Videoconferência**: método de audiência remota
- **Prisão Preventiva Relaxada**: decisão do juiz para reduzir a medida cautelar

### Referências legais
- Art. 310 do CPP
- § 4º do Art. 310 do CPP

### Dicas de prova
- Entenda o conceito de audiência de custo e sua importância na prisão preventiva.
- Conheça as regras para a realização da audiência de custo, incluindo a presença do Ministério Público e da Defensoria Pública ou advogado constituído.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310 do CPP", "§ 4º do Art. 310 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:40:34.363019+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=73", "doc_key": "776546328fb3300da04188a8ff90d4a4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a29820a1eb89caf3c012fcaa6ac753624e9138c9448a1d0928fedad3fc225c44'),
  ('cpiuris2025::66cf4f69349653a5580c47fe1380fa72', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Juiz das Garantias e Audiência de Custódia', '## Juiz das Garantias e Audiência de Custódia

O juiz das garantias é responsável pela audiência de custódia, que deve ocorrer após a prisão em flagrante ou por mandado de prisão provisória. A audiência deve ser realizada dentro de 24 horas e pode incluir o Ministério Público e a Defensoria Pública.

### Conceitos
- **Audiência de Custódia**: Ato processual que ocorre após a prisão em flagrante ou por mandado de prisão provisória
- **Juiz das Garantias**: Magistrado responsável pela audiência de custódia e pelo controle da legalidade da prisão
- **Ministério Público**: Autoridade que representa o Estado na investigação e no processo penal
- **Defensoria Pública**: Autoridade que representa o preso em flagrante ou por mandado de prisão provisória

### Referências legais
- Art. 20 da Lei 13.964/19
- Art. 5º, inciso LXII, da Constituição Federal
- Art. 310 do Código de Processo Penal

### Jurisprudência
- RE 123456
- Enunciado 30 da I Jornada de Direito Penal e Processo Penal CJF/STJ
- ADIs 6.298, 6.299, 6.300 e 6.305

### Dicas de prova
- Entenda a importância da audiência de custódia no processo penal
- Conheça as partes envolvidas na audiência de custódia (Ministério Público, Defensoria Pública e Juiz das Garantias)
- Avalie a relevância do veto do Presidente sobre o §1º do art. 3º-B', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 20 da Lei 13.964/19", "Art. 5º, inciso LXII, da Constituição Federal", "Art. 310 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Enunciado 30 da I Jornada de Direito Penal e Processo Penal CJF/STJ", "ADIs 6.298, 6.299, 6.300 e 6.305"], "confidence": 0.8, "extracted_at": "2026-05-28T16:41:08.913972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=73", "doc_key": "66cf4f69349653a5580c47fe1380fa72"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '975d35921c34e2c7921a2bcd8d34404fd23dc6ccc3a212735af1d0a996534a2b'),
  ('cpiuris2025::24fb704e7ad5669fe118a40e95c98ceb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prorrogação do inquérito policial', '## Prorrogação do inquérito policial

A prorrogação do inquérito policial pode ser feita por 15 dias, com a possibilidade de novas prorrogações, considerando-se a complexidade da investigação e os elementos concretos. A inobservância do prazo não implica automaticamente a revogação da prisão preventiva.

### Conceitos
- **Prorrogação do inquérito**: Aumento do tempo para conclusão do processo
- **Investigado preso**: Pessoa que está sendo investigada e detida pela polícia
- **Prisão preventiva**: Medida cautelar que impede a liberdade de uma pessoa acusada de crime
- **Complexidade da investigação**: Característica que dificulta o processo de investigação

### Referências legais
- Art. 3º-B do CPP
- Súmula 481/STF

### Jurisprudência
- ADI nº 6.581/DF

### Dicas de prova
- Entenda a diferença entre prorrogação e revogação da prisão preventiva
- Conheça a complexidade do artigo e suas implicações práticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B do CPP", "Súmula 481/STF"], "jurisprudence": ["ADI nº 6.581/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:43:01.840170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=75", "doc_key": "24fb704e7ad5669fe118a40e95c98ceb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1f97c05ff7d838f24a72c3a92c1eb730f7a9aef80bbc2837d79a480cb9dfe7de'),
  ('cpiuris2025::a5925339c3a227c5a6b7b948c8e381d0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atribuição do Juiz das Garantias e Medidas Cautelares', '## Atribuição do Juiz das Garantias e Medidas Cautelares

O juiz das garantias tem atribuição sobre as medidas cautelares durante a investigação. Ele pode determinar, substituir ou revogar as medidas, mas somente quando provocado. O contraditório em audiência pública e oral é previsto para a prorrogação das cautelares.

### Conceitos
- **Contraditório**: O direito do réu de se manifestar sobre as provas apresentadas pelo Estado
- **Audiência Pública e Oral**: Reunião pública onde o juiz ouvinte as partes e testemunhas
- **Medidas Cautelares**: Restrições temporárias tomadas para proteger os direitos do réu
- **Prisão**: Restrição pessoal do réu para garantir a ordem pública e segurança
- **Exercício do Direito de Requerer**: O direito do réu de solicitar medidas cautelares
- **Iniciativa do Juiz**: A iniciativa do juiz para tomar medidas cautelares

### Referências legais
- Art. 3º-B, inciso VI do Código de Processo Penal

### Jurisprudência
- ADI 6.298/STF
- ADI 6.299/STF
- ADI 6.300/STF
- ADI 6.305/STF

### Dicas de prova
- Entenda a importância do contraditório em audiência pública e oral
- Conheça as medidas cautelares e suas atribuições
- Aprenda com o STF sobre a interpretação do inciso VI do art. 3º-B', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B, inciso VI do Código de Processo Penal"], "jurisprudence": ["ADI 6.298/STF", "ADI 6.299/STF", "ADI 6.300/STF", "ADI 6.305/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:43:39.502688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=74", "doc_key": "a5925339c3a227c5a6b7b948c8e381d0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9392361616179494166bc3cef65ea1587693252a3a2caf3e07c9dc441d63b86d'),
  ('cpiuris2025::72f4ca872869a1f80b52eadd3cbc18f9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Custódia e Prisão', '## Audiência de Custódia e Prisão

Resumo objetivo: A audiência de custódia pode ser realizada fora do prazo de 24 horas se houver impossibilidade fática, mas não justifica a ilegalidade da prisão. O prazo de 10 dias previsto no art. 10 do CPP pode ser prorrogado até 15 dias na Justiça Estadual.

### Conceitos
- **Audiência de Custódia**: Reunião entre o investigado e o Poder Judiciário para avaliar a possibilidade de liberação do investigado.
- **Prisão**: Ato pelo qual o agente é detido por motivos criminais.
- **Impossibilidade Fática**: Condição que impede a realização da audiência de custódia dentro do prazo estabelecido.
- **Prorrogação da Prisão**: Aumento do tempo de detenção do investigado, autorizado em determinadas circunstâncias.
- **Trancamento do Inquérito Policial**: Decisão que impede a continuação da investigação por falta de fundamento razoável.

### Referências legais
- Art. 10, caput, do CPP

### Dicas de prova
- Entenda o conceito de audiência de custódia e suas implicações na prisão.
- Conheça a distinção entre impossibilidade fática e ilegalidade da prisão.
- Aprenda a aplicação do art. 10 do CPP em diferentes jurisdições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:44:00.348373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=75", "doc_key": "72f4ca872869a1f80b52eadd3cbc18f9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2184e17370f84b063e4c54780090d6aa69f90ea5ad31008614034e03bcc1ad27'),
  ('cpiuris2025::7406d953de6f459cdba8a3e06f4f38f5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Trancamento do Inquérito Policial', '## Trancamento do Inquérito Policial

O trancamento do inquérito policial ocorre nos autos da investigação, quando o juiz das garantias não há fundamento razoável para sua instauração ou prosseguimento. A natureza jurídica é de concessão de habeas corpus.

### Conceitos
- **Trancamento do Inquérito Policial**: Ocorre nos autos da investigação, quando o juiz das garantias não há fundamento razoável para sua instauração ou prosseguimento.
- **Encerramento Anômalo**: Outro nome para o trancamento do inquérito policial
- **Habeas Corpus**: Concessão de habeas corpus, aplicável aos arts. 574, I e 581, X do CPP.

### Referências legais
- Art. 574, I do CPP
- Art. 581, X do CPP

### Dicas de prova
- Entenda a diferença entre trancamento e arquivamento.
- Conheça a natureza jurídica do trancamento do inquérito policial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, I do CPP", "Art. 581, X do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:45:24.452128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=76", "doc_key": "7406d953de6f459cdba8a3e06f4f38f5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd9cc083265741bd6f023bfdf381f1b337247d5d01b35ee5f47b114822875e383'),
  ('cpiuris2025::80a85e11fb72ffb07310254851650545', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do juiz das garantias', '## Competência do juiz das garantias

A competência do juiz das garantias é limitada ao recebimento da denúncia, não ao seu oferecimento. A STF entendeu que a competência cessa com o oferecimento da denúncia.

### Conceitos
- **Competência do juiz das garantias**: Limitação da competência do juiz das garantias ao recebimento da denúncia
- **Investigação criminal**: Etapa de investigação criminal, sob a supervisão do juiz das garantias
- **Denúncia**: Ação formal que encerra o processo de investigação criminal

### Referências legais
- Art. 14 da Lei nº 9.039/96
- ...

### Jurisprudência
- RE 123456
- Súmula 444 STF

### Dicas de prova
- Distinção entre oferecimento e recebimento da denúncia
- Interpretação conforme a Constituição do inciso XIV', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14 da Lei nº 9.039/96", "..."], "jurisprudence": ["RE 123456", "Súmula 444 STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:45:37.645651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=76", "doc_key": "80a85e11fb72ffb07310254851650545"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '01bba615a842a236d27d2b9b1b75330e4a88d4179a16e6715a144c3d5367474a'),
  ('cpiuris2025::276974e33671975cbebe4539b76c796b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do Juiz das Garantias', '## Competência do Juiz das Garantias

O juiz das garantias tem competência para processar e julgar todos os crimes, exceto os de menor potencial ofensivo. A competência cessa com o recebimento da denúncia ou queixa.

### Conceitos
- **Competência**: A capacidade do juiz das garantias de processar e julgar um caso
- **Juiz das Garantias**: O magistrado responsável pela competência em casos criminais
- **Infrações Penais**: Todas as ações que violam a lei e podem ser punidas com pena
- **Menor Potencial Ofensivo**: Crimes que não causam danos graves ou irreversíveis à vítima

### Referências legais
- Art. 3º-C do Código de Processo Penal
- Art. 399 do Código de Processo Penal

### Jurisprudência
- Súmula Vinculante nº 14

### Dicas de prova
- Entenda a competência do juiz das garantias e como ela se aplica às diferentes infrações penais
- Conheça as exceções à competência, como os crimes de menor potencial ofensivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-C do Código de Processo Penal", "Art. 399 do Código de Processo Penal"], "jurisprudence": ["Súmula Vinculante nº 14"], "confidence": 0.8, "extracted_at": "2026-05-28T16:47:10.738830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=77", "doc_key": "276974e33671975cbebe4539b76c796b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6ad7b70ae690550d90fdba88688d85588264aec970847743783e3a170b021670'),
  ('cpiuris2025::2e17a8c3fbe5510837515cbb356ed6ee', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interpretação Conforme da Constituição', '## Interpretação Conforme da Constituição

O STF atribuiu interpretação conforme à primeira parte do artigo para esclarecer que as normas relativas ao juiz das garantias não se aplicam a certos processos, como os de competência originária dos tribunais, tribunal do júri e casos de violência doméstica e familiar.

### Conceitos
- **Interpretação Conforme**: interpretação que atribui significado maior à Constituição
- **Unanimidade**: acordo unânimo entre os membros do STF
- **Normas Relativas ao Juiz das Garantias**: regras que regulam a atuação de um juiz nas garantias

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre interpretação conforme e normas relativas ao juiz das garantias.
- Conheça as situações em que as normas relativas ao juiz das garantias não se aplicam.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:48:12.501350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=77", "doc_key": "2e17a8c3fbe5510837515cbb356ed6ee"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8fa37e9d2a827fd391e11fe0fafb519df20dccdcf61512973997dff4d895df2b'),
  ('cpiuris2025::280ab36ce06b049a1d1650bc84e83599', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acesso dos juízes ao inquérito policial e às provas', '## Acesso dos juízes ao inquérito policial e às provas

Resumo objetivo: O artigo discute a limitação do acesso dos juízes ao inquérito policial e às provas, com o objetivo de manter sua imparcialidade. A dificuldade prática é a determinação do §2º, que não permite análise sem acesso aos substratos da decretação das medidas cautelares.

### Conceitos
- **Acesso ao inquérito policial**: O direito dos juízes de acessar o inquérito policial para realizar a instrução do processo
- **Provas irrepetíveis**: Provas que não podem ser repetidas ou reprodutivas, como testemunhos ou documentos originais
- **Análise determinada**: A análise de fatores específicos do caso para decidir sobre a absolvição sumária ou a decretação das medidas cautelares

### Referências legais
- Art. 2º da Lei nº 9.099/1995
- Súmula 652 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Acesso ao inquérito policial

### Dicas de prova
- Entenda a limitação do acesso dos juízes ao inquérito policial e às provas
- Conheça as diferenças entre provas irrepetíveis e medidas de obtenção de provas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º da Lei nº 9.099/1995", "Súmula 652 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Acesso ao inquérito policial"], "confidence": 0.8, "extracted_at": "2026-05-28T16:49:59.256818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=78", "doc_key": "280ab36ce06b049a1d1650bc84e83599"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8a870aee7bd3b9eb2252aa149df7e11dd7cfccd0c29b2c65a411fe6427426f8c'),
  ('cpiuris2025::1777aceec8ac51e3ea708fdc6cbc71c9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do Juiz das Garantias', '## Competência do Juiz das Garantias

O juiz das garantias tem competência a partir do recebimento da comunicação da prisão em flagrante ou da instauração da investigação criminal, e sua competência cessa com o recebimento da denúncia ou queixa. No entanto, a Constituição declara a inconstitucionalidade de expressões específicas, atribuindo interpretação conforme.

### Conceitos
- **Competência do Juiz das Garantias**: A competência do juiz das garantias é determinada pelo recebimento da comunicação da prisão em flagrante ou da instauração da investigação criminal.
- **Recebimento da Denúncia ou Queixa**: O recebimento da denúncia ou queixa marca o término da competência do juiz das garantias.
- **Investigação Criminal**: A instauração da investigação criminal é outro ponto de partida para a competência do juiz das garantias.
- **Prisão em Flagrante**: A comunicação da prisão em flagrante é um evento que marca o início da competência do juiz das garantias.
- **Denúncia ou Queixa**: A denúncia ou queixa é um ato que encerra a competência do juiz das garantias.
- **Interpretação Conforme**: A interpretação conforme é uma técnica utilizada para dar sentido à Constituição em casos de inconstitucionalidade.
- **Competência do Juiz da Instrução e Julgamento**: O juiz da instrução e julgamento assume a competência após o recebimento da denúncia ou queixa.

### Referências legais
- Art. 3º-B, I e II; Art. 3º-B, IV; Art. 399 do CPP; Art. 3º-C

### Jurisprudência
- RE 123456; Súmula N STF

### Dicas de prova
- Entenda a competência do juiz das garantias e como ela é determinada.
- Conheça as expressões específicas que foram declaradas inconstitucionais pelo STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B, I e II; Art. 3º-B, IV; Art. 399 do CPP; Art. 3º-C"], "jurisprudence": ["RE 123456; Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:50:09.711935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=78", "doc_key": "1777aceec8ac51e3ea708fdc6cbc71c9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c0189bb1755a05eeb7c135dc24c24ee8b42979fa929aa0a7497685f91d90f604'),
  ('cpiuris2025::0d92aa9638f069def04b51484e8e7a48', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impedimento dos magistrados nas fases de investigação e julgamento', '## Impedimento dos magistrados nas fases de investigação e julgamento

O art. 3º-D estabelece o impedimento do juiz que praticar atos de competência dos arts. 4º e 5º, com a criação de um sistema de rodízio em comarcas com apenas um juiz.

### Conceitos
- **Impedimento**: obrigação do magistrado de não atuar em determinadas fases do processo
- **Rodízio**: sistema de substituição de magistrados para garantir a igualdade de trabalho
- **Prevenção**: critério de fixação de competência apenas entre os próprios juízes de garantias

### Referências legais
- Art. 3º-D do Código de Processo Penal
- Súmula 437 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Impedimento dos magistrados

### Dicas de prova
- Entenda a distinção entre prevenção e impedimento
- Conheça o sistema de rodízio e sua importância na organização judiciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-D do Código de Processo Penal", "Súmula 437 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Impedimento dos magistrados"], "confidence": 0.8, "extracted_at": "2026-05-28T16:50:33.022949+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=79", "doc_key": "0d92aa9638f069def04b51484e8e7a48"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6d673b44faf9612e308e2ed5226eb544143e1c07ba4ecb8d3cdc561092ad1e81'),
  ('cpiuris2025::7d71d842c425bd7012fba59f0bbaa878', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Anulação do processo penal e inquérito policial', '## Anulação do processo penal e inquérito policial

A anulação do processo penal não é possível por irregularidades no inquérito, mas as nulidades processuais estão relacionadas a defeitos de ordem jurídica. O inquérito policial colhe elementos de informação para formar um lastro probatório mínimo.

### Conceitos
- **Anulação do processo penal**: Ação que visa cancelar o processo penal por irregularidades
- **Inquérito policial**: Instrumento utilizado pelo Estado para coletar elementos de informação sobre autoria e materialidade do delito
- **Nulidades processuais**: Defeitos de ordem jurídica que afetam os atos praticados ao longo da ação penal condenatória
- **Contraditório**: Condição de existência e validade das provas produzidas no curso do processo judicial

### Referências legais
- Art. 5º, LVI, da CF/88

### Jurisprudência
- STF. 2ª Turma. RHC 131450/DF
- Info 824

### Dicas de prova
- Distinguir entre elementos de informação e provas
- Entender a teoria da fonte independente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LVI, da CF/88"], "jurisprudence": ["STF. 2ª Turma. RHC 131450/DF", "Info 824"], "confidence": 0.8, "extracted_at": "2026-05-28T16:52:55.475420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=82", "doc_key": "7d71d842c425bd7012fba59f0bbaa878"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6ac297b824a57e3564f35bf659d580753d9b8d6c61614000b983895fb426f0d7'),
  ('cpiuris2025::64d9fae5515799afe3b8344fbfa07704', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interpretação Conforme e Juiz das Garantias', '## Interpretação Conforme e Juiz das Garantias

O juiz das garantias é investido, não designado, para exercer a função específica criada por lei em um determinado juízo. A interpretação conforme do art. 3º-F do CPP foi atribuída pelo STF para assegurar a divulgação de informações sobre prisão e identidade do preso.

### Conceitos
- **Interpretação Conforme**: interpretação ampla e flexível da lei
- **Juiz das Garantias**: magistrado investido para exercer função específica
- **Designação vs Investimento**: diferença entre ser designado para um cargo e ser investido para exercê-lo
- **Exercício de Função Pública**: execução das funções públicas atribuídas a uma pessoa
- **Cargo Específico**: função pública criada por lei em um determinado juízo
- **Lei Específica**: leis que regulamentam aspectos específicos de um sistema jurídico
- **Divulgação de Informações**: compartilhamento de informações sobre prisão e identidade do preso
- **Direito à Informação**: direito do cidadão de saber sobre suas próprias informações

### Referências legais
- Art. 3º-A ao art. 3º-F do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre designação e investimento de magistrados
- Entender a importância da divulgação de informações sobre prisão e identidade do preso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-A ao art. 3º-F do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T16:53:03.978399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=79", "doc_key": "64d9fae5515799afe3b8344fbfa07704"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1e38c0804403e9855a9d38fe8e6f4ee4cb69c6b4754a343f4f3838ac532b2fa8'),
  ('cpiuris2025::a322456c99dc2d9d8652e87d27a6ac05', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Natureza Jurídica do Inquérito Policial', '## Natureza Jurídica do Inquérito Policial

O inquérito policial é um procedimento administrativo de natureza instrumental, destinado a esclarecer fatos delituosos e fornecer subsídios para o prosseguimento ou arquivamento da persecução penal.

### Conceitos
- **Procedimento Administrativo**: Caracteriza-se como um procedimento que não é regido por uma ordem legal rígida
- **Instrumentalidade**: Tem como finalidade esclarecer fatos delituosos e fornecer subsídios para o prosseguimento ou arquivamento da persecução penal
- **Flexibilidade**: Deve ser flexível, pois é um procedimento que não obedece a uma ordem legal rígida
- **Mera Peça Informativa**: Não contamina o processo penal que dele origina, e eventuais vícios nele constantes não são motivo de nulidade do processo
- **Autoridade Policial**: Não é motivo de suspeição para a nulidade do processo, pois o inquérito é mera peça informativa
- **Pretensão Acusatória**: Não há exercício da pretensão acusatória pelo Estado no inquérito policial
- **Partes ou Contraditório e Ampla Defesa**: Não há partes ou contraditório e ampla defesa no inquérito policial

### Referências legais
- Art. 5º da Constituição Federal
- Código de Processo Penal

### Jurisprudência
- Súmula 292 do STF

### Dicas de prova
- Entenda a natureza jurídica e finalidade do inquérito policial
- Conheça as características do procedimento administrativo em geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.81", "page_number": 81, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º da Constituição Federal", "Código de Processo Penal"], "jurisprudence": ["Súmula 292 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T16:53:08.541944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=81", "doc_key": "a322456c99dc2d9d8652e87d27a6ac05"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '35a7afe1a361d7839060f254ac2f14b257444a09f3994748e1f0f76b78186706'),
  ('cpiuris2025::14eaa97334e4d3a7b5c66ccc7770625e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Iniciativa e procedimento do inquérito policial em crimes de ação pública', '## Iniciativa e procedimento do inquérito policial em crimes de ação pública

A autoridade policial tem obrigatoriedade para agir após demonstrado o interesse dos legitimados, de acordo com o art. 5º do CPP.

### Conceitos
- **inquérito policial**: investigação realizada pela polícia
- **ação pública**: procedimento realizado pelo Estado
- **requisição**: pequena notificação para que alguém faça algo
- **discricionária**: fase de investigação com liberdade de escolha da autoridade policial

### Referências legais
- Art. 5º do CPP

### Dicas de prova
- Entenda a diferença entre inquérito policial e ação pública.
- Conheça o conceito de requisição e sua importância no procedimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:55:00.415649+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=83", "doc_key": "14eaa97334e4d3a7b5c66ccc7770625e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '530f61f62b2a26151e1e8f914a45044bdc3587788b423df8ae4c07bfe2935aa5'),
  ('cpiuris2025::e1602e36f16db8f7796f21b83b0075bc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Valor probatório do inquérito policial', '## Valor probatório do inquérito policial

O art. 155 do CPP estabelece que os elementos de informação não têm valor probatório absoluto, mas podem ser utilizados de maneira subsidiária e complementar à prova produzida em contraditório.

### Conceitos
- **Prova**: Elemento que comprova a veracidade de uma afirmação
- **Elementos informativos**: Informações coletadas sem o contraditório e ampla defesa
- **Contraditório**: Princípio que exige a participação do acusado na coleta de provas
- **Ampla defesa**: Direito do acusado de se defender adequadamente

### Referências legais
- Art. 155 do CPP
- Art. 5º, LV da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre prova e elementos informativos.
- Conheça o princípio do contraditório e sua aplicação no direito processual penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 155 do CPP", "Art. 5º, LV da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T16:55:24.723200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=82", "doc_key": "e1602e36f16db8f7796f21b83b0075bc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '34c3dc519dd510dbbe6b59ddbd54c60516b9ee43c0782ea9cdefc73e1c343790'),
  ('cpiuris2025::bc5910143b89d36dd8929cfb4c391fd0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Previsão do Art. 155 do CPP', '## Investigação Criminal e Previsão do Art. 155 do CPP

O artigo 155 do CPP estabelece que o juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, sem fundamentar exclusivamente nos elementos informativos colhidos na investigação, ressalvados as provas cautelares.

### Conceitos
- **Contraditório Judicial**: Procedimento em que as partes apresentam suas provas e argumentos para convencer o juiz.
- **Investigação Criminal**: Ação do Estado para investigar um crime e determinar a responsabilidade de uma pessoa.
- **Prova Cautelar**: Prova que é necessária para evitar danos ao réu ou à vítima, e que pode ser utilizada apenas em casos específicos.
- **Art. 155 do CPP**: Dispositivo legal que estabelece as regras para a formação da convicção do juiz na investigação criminal.

### Referências legais
- Art. 155 do Código de Processo Penal (CPP)
- Lei nº 13.964/19 (Pacote Anticrime)

### Jurisprudência
- Súmula N da STF
- RE 123456

### Dicas de prova
- Entenda a diferença entre o inquérito policial oficioso e condicionado.
- Conheça as regras para a formação da convicção do juiz na investigação criminal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 155 do Código de Processo Penal (CPP)", "Lei nº 13.964/19 (Pacote Anticrime)"], "jurisprudence": ["Súmula N da STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T16:56:12.756963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=83", "doc_key": "bc5910143b89d36dd8929cfb4c391fd0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c4d04d8f40819cc73314e4e7484df679acd8bd7a982d799e4599b7a11c8248b8'),
  ('cpiuris2025::0ae33557941ee19d6aa628948d2bf976', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento Temporário', '## Procedimento Temporário

O artigo 10 do CPP estabelece prazos para o encerramento do inquérito policial, mas permite a devolução dos autos ao juiz em casos de dificuldade de elucidação e liberdade do indiciado.

### Conceitos
- **inquérito policial**: investigação policial
- **autoridade**: pessoa que exerce poderes de investigação
- **juiz**: pessoa que decide sobre o caso
- **prazo das investigações**: período durante o qual as investigações são realizadas

### Referências legais
- Art. 10 do CPP

### Dicas de prova
- Entenda a importância dos prazos para o encerramento do inquérito policial
- Conheça a exceção que permite a devolução dos autos ao juiz em casos de dificuldade de elucidação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:57:18.667641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=84", "doc_key": "0ae33557941ee19d6aa628948d2bf976"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5ebb30352fd25b2770773819821f0f8a2d7b85bd0913113013f1c99ef8d705e7'),
  ('cpiuris2025::9f4351c7ac81605b979936d040dc79d9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Discricionariedade na investigação criminal', '## Discricionariedade na investigação criminal

A discricionariedade na investigação criminal é uma liberdade de atuação dentro dos limites traçados pela lei, não significando arbitrariedade. A autoridade policial pode determinar diligências, mas não pode ultrapassar os limites da Constituição e da legislação infraconstitucional.

### Conceitos
- **Discricionariedade**: Liberdade de atuação dentro dos limites traçados pela lei
- **Arbitrariedade**: Ato ilegal ou injusto que não está previsto em lei
- **Oficiosidade**: Obrigatoriedade de instauração de inquérito policial quando a autoridade policial toma conhecimento de infração penal

### Referências legais
- Art. 6º e Art. 7º do CPP
- Art. 14 do CPP

### Dicas de prova
- Entenda a distinção entre discricionariedade e arbitrariedade
- Conheça o conceito de oficiosidade e sua relação com a discricionariedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 6º e Art. 7º do CPP", "Art. 14 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:57:23.582275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=84", "doc_key": "9f4351c7ac81605b979936d040dc79d9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '26ea0e24603da625f429ebdea8d7294c9db60b1119977b3bf808fdf07ed36bd7'),
  ('cpiuris2025::8083cf3f0300456fba1e230c455c3a8c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Dispensabilidade do Inquérito Policial', '## Dispensabilidade do Inquérito Policial

O inquérito policial é dispensável se o Ministério Público ou o querelado tiverem acesso aos elementos de informação necessários para o oferecimento da ação penal.

### Conceitos
- **Inquérito Policial**: Investigação policial que pode ser dispensável se não for necessário para a ação penal
- **Denúncia**: Ação penal pública iniciais, apresentada pelo Ministério Público
- **Queixa**: Ação penal privada, apresentada por uma pessoa física ou jurídica
- **Elementos de Informação**: Provas e informações necessárias para a ação penal

### Referências legais
- Art. 12 do CPP
- Art. 27 do CPP
- Art. 39 do CPP
- Art. 46 do CPP

### Jurisprudência
- HC 653.299-SC
- 6ª Turma do STJ

### Dicas de prova
- Entenda a noção de inquérito policial e sua dispensabilidade
- Conheça os dispositivos do Código de Processo Penal que tratam da dispensabilidade do inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 12 do CPP", "Art. 27 do CPP", "Art. 39 do CPP", "Art. 46 do CPP"], "jurisprudence": ["HC 653.299-SC", "6ª Turma do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T17:13:42.900837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=85", "doc_key": "8083cf3f0300456fba1e230c455c3a8c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3d4e587b30f6fb20612f88bb56e56a277c5f3586875cceeb6608bfbddb0653ae'),
  ('cpiuris2025::be2921e681272a285413ba350224301a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Oferecimento da denúncia e procedimento indisponível', '## Oferecimento da denúncia e procedimento indisponível

Não é necessário requisitar instauração de inquérito policial para oferecer denúncia, pois a autoridade policial não pode mandar arquivar autos de inquérito.

### Conceitos
- **Oferecimento da denúncia**: Ato pelo qual o Ministério Público apresenta a ação penal
- **Procedimento indisponível**: Rito que não pode ser alterado ou modificado por outrem
- **Inquérito policial**: Investigação realizada pela autoridade policial para formar a opinio delicti do titular da ação penal

### Referências legais
- Art. 17 do CPP
- Art. 28 do CPP

### Dicas de prova
- Distinção entre o oferecimento da denúncia e a instauração de inquérito policial
- Entendimento do artigo 17 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 17 do CPP", "Art. 28 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T17:14:15.041006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=85", "doc_key": "be2921e681272a285413ba350224301a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ade4a9d63a958ff60cae841bdb127f70845a25d8e51511793a3d6af55f3b38ca'),
  ('cpiuris2025::e53a096af0808dcfc8e06fb55cdeb858', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento sigiloso em investigação criminal', '## Procedimento sigiloso em investigação criminal

A publicidade dos atos processuais não se aplica ao inquérito policial, sendo necessário o sigilo para a eficácia das investigações. O advogado tem direito de consultar os autos de investigação, mas com restrições.

### Conceitos
- **Procedimento sigiloso**: Investigação criminal realizada sem a publicidade dos atos processuais
- **Sigilo necessário à elucidação do fato**: Necessidade de manter o sigilo para garantir a eficácia das investigações
- **Acesso ao advogado nos autos de investigação**: Direito do advogado consultar os autos de investigação, com restrições

### Referências legais
- Art. 20 do CPP
- Súmula Vinculante nº 14

### Jurisprudência
- Súmula Vinculante nº 14

### Dicas de prova
- Distinção entre procedimento investigatório e atos processuais
- Importância do sigilo para a eficácia das investigações
- Acesso ao advogado nos autos de investigação: direito, restrições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 20 do CPP", "Súmula Vinculante nº 14"], "jurisprudence": ["Súmula Vinculante nº 14"], "confidence": 0.8, "extracted_at": "2026-05-28T17:18:37.663810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=86", "doc_key": "e53a096af0808dcfc8e06fb55cdeb858"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '750e08f599481ec43cf8e21af62ad2fa36d4b1317441d26257b752218b33988d'),
  ('cpiuris2025::da9a08ecf03dee7116a178e9e47734f6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acesso aos autos do inquérito policial', '## Acesso aos autos do inquérito policial

O advogado pode requerer acesso aos autos do inquérito policial caso negado pelo delegado de polícia. Ele tem três opções: reclamação constitucional ou mandado de segurança.

### Conceitos
- **Reclamação Constitucional**: juizamento de reclamação ao Supremo Tribunal Federal
- **Mandado de Segurança**: ação para proteger o direito líquido e certo do advogado
- **Súmula Vinculante nº 14**: pronunciamento do Supremo Tribunal Federal sobre questões constitucionais
- **Art. 103-A, §3º, da CF/88**: disposição que permite o ajuizamento de reclamação ao Supremo Tribunal Federal
- **Estatuto da OAB**: leis que regem a profissão jurídica no Brasil
- **Art. 7º, XIV, do Estatuto da OAB**: disposição que protege o direito líquido e certo dos advogados

### Referências legais
- Art. 103-A, §3º, da CF/88
- Súmula Vinculante nº 14

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre reclamação constitucional e mandado de segurança
- Conhecer a Súmula Vinculante nº 14 e seu aplicabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 103-A, §3º, da CF/88", "Súmula Vinculante nº 14"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T17:28:36.687327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=86", "doc_key": "da9a08ecf03dee7116a178e9e47734f6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd00be9b6ed4c107d3ce629d5a4bb0ab5ea91c8eca11706f7f0a6fdd0474aa418'),
  ('cpiuris2025::b057514eacbfcdf115cebeeb2f0ec31a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exercício endógeno no processo penal', '## Exercício endógeno no processo penal

O exercício endógeno é a prática de atividades dentro do processo penal, como o interrogatório ou depoimento do imputado, sem a necessidade de intervenção externa.

### Conceitos
- **Exercício endógeno**: Prática de atividades dentro do processo penal
- **Investigação preliminar**: Fase inicial do processo penal, onde são realizadas as primeiras diligências
- **Oitiva do imputado**: Ato de ouvir o imputado para coletar informações
- **Diligências porventura**: Atividades adicionais realizadas pela autoridade policial

### Referências legais
- Art. 7º, XXI, do Estatuto da OAB

### Dicas de prova
- Entenda a diferença entre exercício endógeno e externo
- Conheça o direito do advogado de assistir seu cliente em apurações de infrações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º, XXI, do Estatuto da OAB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T17:28:55.355755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=87", "doc_key": "b057514eacbfcdf115cebeeb2f0ec31a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a60cca75b4c57ba0460f1c1b444458288e6545acfe02c7334e6d916dd7c6acc1'),
  ('cpiuris2025::f69aedbfab81746ebb7a969fb7700268', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Acesso ao Advogado', '## Investigação Criminal e Acesso ao Advogado

A negativa de acesso do advogado aos autos do procedimento investigatório pode acarretar constrangimento ilegal à liberdade de locomoção do investigado, podendo resultar em condenação à pena privativa de liberdade. No entanto, há exceções, como a relativa a documentos que envolvam dados sigilosos de terceiros não relacionados ao direito de defesa.

### Conceitos
- **Habeas corpus**: mandado judicial que determina o acesso ao advogado
- **Acesso ao advogado**: direito do investigado a ter acesso aos autos do procedimento investigatório
- **Constrangimento ilegal**: situação em que a negativa de acesso ao advogado resulta em restrição à liberdade de locomoção do investigado
- **Investigação criminal**: procedimento judicial que visa apurar a responsabilidade por um crime
- **Contraditório e ampla defesa**: direitos do investigado a ser ouvido pela autoridade investigadora e a exercer sua autodefesa

### Referências legais
- Art. 144, §1º, I, e §4º, da CF/88
- Súmula Vinculante nº 14

### Jurisprudência
- STF. 1ª Turma. Rcl 25872 AgR-AgR/SP
- RE 123456

### Dicas de prova
- Entenda a importância do acesso ao advogado no procedimento investigatório
- Conheça as exceções à regra geral de acesso ao advogado, como a relativa a documentos sigilosos de terceiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 144, §1º, I, e §4º, da CF/88", "Súmula Vinculante nº 14"], "jurisprudence": ["STF. 1ª Turma. Rcl 25872 AgR-AgR/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T17:44:31.383892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=87", "doc_key": "f69aedbfab81746ebb7a969fb7700268"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5462ccafa5616544b3ec89268f5fdb243f9a5ba48656467ce6c426d4ff92abaa'),
  ('cpiuris2025::2ed2870754d4b3001838723d13367afa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação de investigado em procedimentos investigatórios', '## Citação de investigado em procedimentos investigatórios

O artigo 14-A estabelece que o investigado deve ser notificado da instauração do procedimento investigatório, podendo constituir defensor no prazo de até 48 horas.

### Conceitos
- **Citação**: Ato processual pelo qual o acusado toma conhecimento de um processo contra si
- **Notificação**: Ato que informa ao investigado a instauração do procedimento investigatório

### Referências legais
- Art. 14-A da Lei nº 9.449/1997

### Dicas de prova
- Entenda o termo ''citação'' como ''notificação'' no contexto do artigo 14-A
- Conheça as instituições abrangidas pela disposição do art. 14-A', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14-A da Lei nº 9.449/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T18:16:09.064041+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=89", "doc_key": "2ed2870754d4b3001838723d13367afa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bf3eeb9ff7820c425fe5359e6a0c255d44a20505c50cc23e2be92c594749a3b5'),
  ('cpiuris2025::90afc62886b3e557306d1b4eca6bf49a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prerrogativas da defesa técnica em inquérito criminal', '## Prerrogativas da defesa técnica em inquérito criminal

A Lei nº 13.245/2016 reforçou as prerrogativas da defesa técnica, mas não conferiu ao advogado o direito de intimação prévia e tempestiva do calendário de inquirições.

### Conceitos
- **Prerrogativa da defesa técnica**: Direito do advogado de apresentar razões e quesitos no curso de investigação criminal
- **Intimação prévia e tempestiva**: O direito do advogado de ser notificado com antecedência sobre o calendário de inquirições
- **Lei nº 13.245/2016**: Reforço das prerrogativas da defesa técnica

### Referências legais
- Art. 14-A do CPP
- Lei nº 13.964/19 (Lei Anticrime)

### Jurisprudência
- STF. 2ª Turma. Pet 7612/DF, Rel. Min. Edson Fachin, julgado em 12/03/2019

### Dicas de prova
- Entenda a importância das prerrogativas da defesa técnica no inquérito criminal
- Conheça as limitações do direito de intimação prévia e tempestiva para o advogado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14-A do CPP", "Lei nº 13.964/19 (Lei Anticrime)"], "jurisprudence": ["STF. 2ª Turma. Pet 7612/DF, Rel. Min. Edson Fachin, julgado em 12/03/2019"], "confidence": 0.8, "extracted_at": "2026-05-28T18:16:09.740125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=88", "doc_key": "90afc62886b3e557306d1b4eca6bf49a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5b5c55de1a67824b55bb566d84b2734107beec3d1c919c4f3061bdc5cef5b2ae'),
  ('cpiuris2025::5ed92de09f725848f19ef1861cd30e82', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal - Caracterização Inquisitorial', '## Investigação Criminal - Caracterização Inquisitorial

O inquérito policial é um procedimento administrativo com caráter instrumental, destinado a fornecer elementos para o titular da ação penal iniciar o processo penal. A ausência de contraditório e ampla defesa é compensada pela eficácia das diligências investigatórias.

### Conceitos
- **Inquérito Policial**: Procedimento administrativo com caráter instrumental, destinado a fornecer elementos para o titular da ação penal iniciar o processo penal.
- **Contraditório**: Direito do acusado de ser ouvido antes de ser condenado
- **Ampla Defesa**: Direito do acusado de ter assistência jurídica adequada durante o processo
- **Investigação Criminal**: Procedimento destinado a apurar a existência de um delito e identificar os responsáveis

### Referências legais
- Art. 155, caput, do CPP
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo: natureza inquisitorial das investigações criminais

### Dicas de prova
- Distinguir entre o procedimento de inquérito policial e o processo judicial
- Entender a limitação do contraditório e da ampla defesa no inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 155, caput, do CPP", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: natureza inquisitorial das investigações criminais"], "confidence": 0.8, "extracted_at": "2026-05-28T18:16:23.746973+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=88", "doc_key": "5ed92de09f725848f19ef1861cd30e82"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6176ea4ec98ea487f4f2155062ec7e0ddfb5fcc53df3f3b0dc57477958ce20f2'),
  ('cpiuris2025::77406ddce77e763426f38dc688cee48c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Indicação de Defensor no Processo', '## Indicação de Defensor no Processo

A indicação de defensor é feita preferencialmente à Defensoria Pública, e em caso de não existência, a União ou a Unidade da Federação deve disponibilizar um profissional para acompanhar o procedimento.

### Conceitos
- **Defensoria Pública**: instituição pública que fornece assistência jurídica gratuita
- **União**: entidade política que representa o Estado
- **Unidade da Federação**: entidade política que representa uma região do Brasil

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas sobre a indicação de defensor podem ser muito específicas.
- O conceito de Defensoria Pública é fundamental para entender o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T18:32:16.898232+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=89", "doc_key": "77406ddce77e763426f38dc688cee48c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cf99e6124c1570b8539132294b9deea15c098c82f5b6f288b5abe2c1713a68a3'),
  ('cpiuris2025::c461672176db9ed898e26fc0a6af0879', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atribuição da Defensoria Pública em Investigação Criminal', '## Atribuição da Defensoria Pública em Investigação Criminal

Discute a hipótese em que pode ser indicado um profissional não integrante da Administração para atuar na investigação criminal, e a responsabilidade dos custos de patrocínio dos investigados quando não há atuação da Defensoria Pública.

### Conceitos
- **Defensoria Pública**: instituição pública que defende os interesses dos necessitados
- **Investigação Criminal**: procedimento utilizado para investigar crimes
- **Atribuição de Profissional**: designa a indicação de um profissional para atuar na investigação criminal

### Referências legais
- Art. 134 da CF/88
- Art. 45 do Estudo do Rio Grande do Sul
- Lei Complementar 9.230/1991 do Estado do Rio Grande do Sul

### Jurisprudência
- ADI 3022 (Relator: JOAQUIM BARBOSA)
- RE 123456

### Dicas de prova
- Entenda a hipótese de não atuação da Defensoria Pública e as consequências para os custos de patrocínio dos investigados.
- Conheça o modelo estabelecido no art. 134 da CF/88 e como ele se aplica às atribuições da Defensoria Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 134 da CF/88", "Art. 45 do Estudo do Rio Grande do Sul", "Lei Complementar 9.230/1991 do Estado do Rio Grande do Sul"], "jurisprudence": ["ADI 3022 (Relator: JOAQUIM BARBOSA)", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T18:32:33.434936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=90", "doc_key": "c461672176db9ed898e26fc0a6af0879"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '60493aadd3120c0b3d165afaa0071d9601d8d0250c0357df67ebdecf6b5d058d'),
  ('cpiuris2025::16ddc2f867197498e88038174c36bab5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação do Investigado em Procedimento Investigatório', '## Citação do Investigado em Procedimento Investigatório

O investigado deve ser citado desde o início do procedimento investigatório, especialmente em casos envolvendo servidores públicos. O investigado tem direito a constituir seu próprio defensor dentro de um prazo de 48 horas.

### Conceitos
- **Citação do Investigado**: A notificação formal do investigado desde o início do procedimento investigatório
- **Servidores Públicos**: Empregados públicos que estão vinculados a instituições específicas, como escolas e hospitais
- **Defensor**: O advogado nomeado pelo investigado para representá-lo em procedimento judicial

### Referências legais
- Art. 144 da CF/88
- Art. 142 da CF/88

### Dicas de prova
- Distinção entre servidores públicos e particulares
- Importância do prazo para a constituição do defensor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 144 da CF/88", "Art. 142 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T18:54:21.989489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=90", "doc_key": "16ddc2f867197498e88038174c36bab5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '90373885cfdac5a41fe17fa36cffb804923fd4bd8703723a39b9014e33afbe92'),
  ('cpiuris2025::dac2e9b25f51150873982603e40d6c2f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atribuição para presidir o inquérito policial', '## Atribuição para presidir o inquérito policial

A atribuição para presidir o inquérito policial é uma medida de poder distribuída às autoridades administrativas, que pode variar dependendo da natureza da infração penal e do local da consumação do delito.

### Conceitos
- **Polícia Administrativa**: Caráter preventivo, finalidade impedir prática de delitos
- **Polícia Judiciária**: Caráter repressivo, finalidade auxiliar Poder Judiciário
- **Atribuição**: Parcela de poder distribuída às autoridades administrativas
- **Competência**: Medida e limite da jurisdição outorgada aos juízes
- **Investigação Policial**: Colheita de elementos informativos quanto à autoria e materialidade das infrações penais

### Referências legais
- Art. 4º do CPP
- Art. 144, §1º, I da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre atribuição e competência

### Dicas de prova
- Entenda a distinção entre polícia administrativa e judiciária
- Conheça a definição de atribuição e competência no Direito Processual Penal
- Aprenda a aplicar as regras de investigação policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.91", "page_number": 91, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 4º do CPP", "Art. 144, §1º, I da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre atribuição e competência"], "confidence": 0.8, "extracted_at": "2026-05-28T19:09:56.091882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=91", "doc_key": "dac2e9b25f51150873982603e40d6c2f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '93a3091f751b0b706ec0cad5f3377f7b8b372f2dbb35d4b007999e3249a1821d'),
  ('cpiuris2025::0d1039b38b81d39a75a7ed5d92cdb5fe', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Competência Jurisdicional', '## Investigação Criminal e Competência Jurisdicional

A lei estabelece que crimes com repercussão interestadual ou internacional podem ser investigados pela Polícia Federal, desde que haja indícios de quadrilha ou bando em mais de um Estado. A competência para julgar esses crimes é da Justiça Federal.

### Conceitos
- **Investigação Criminal**: Ações processuais destinadas a apurar a existência de um crime
- **Competência Jurisdicional**: O direito do juiz ou tribunal de julgar uma causa
- **Repercussão Interestadual**: A influência de um evento ou ato em mais de um Estado
- **Polícia Federal**: O órgão responsável pela investigação criminal federal
- **Justiça Federal**: O sistema jurisdicional federal que julga crimes federais

### Referências legais
- Art. 1º da Lei n.º 10.446/02
- Inciso I do §1º do art. 144 da Constituição Federal

### Dicas de prova
- Entenda a noção de repercussão interestadual e sua importância na competência jurisdicional.
- Conheça as hipóteses de competência da Polícia Federal e da Justiça Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º da Lei n.º 10.446/02", "Inciso I do §1º do art. 144 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T19:10:09.780181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=92", "doc_key": "0d1039b38b81d39a75a7ed5d92cdb5fe"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a0ca09bc2ada034b4a8f2e8eaa827982c4056538368b080622cc246d41434865'),
  ('cpiuris2025::7a02a973e5bd197759293ec7f91ca94d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Autoridade Policial em Ações Penais', '## Competência e Autoridade Policial em Ações Penais

A competência da Polícia Federal para investigar crimes não impede a competência do juiz estadual para supervisionar o inquérito policial e julgar o processo-crime. A desconformidade com a Lei nº 10.446/2002 pode implicar responsabilidade administrativa ou criminal, mas não gera nulidade no processo.

### Conceitos
- **Competência**: A capacidade de uma autoridade ou juiz para julgar um caso específico.
- **Autoridade Policial**: Pessoal que exerce poderes de polícia, como a Polícia Federal.
- **Lei nº 10.446/2002**: Lei que estabelece as regras para a investigação de crimes por parte da Polícia Federal.
- **Inquérito Policial**: Procedimento administrativo destinado a coletar informações sobre um crime.
- **Processo-Crime**: Ação judicial que visa punir um indivíduo por um crime.
- **Nulidade**: O ato de declarar um processo nulo, ou seja, sem valor jurídico.
- **Princípio do Juiz Natural**: A ideia de que apenas o juiz competente pode julgar um caso.

### Referências legais
- Art. 5º, LIII, da Constituição Federal; Art. 1º da Lei n.º 10.446/2002

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência e autoridade policial em ações penais.
- Conheça as regras da Lei nº 10.446/2002 e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIII, da Constituição Federal; Art. 1º da Lei n.º 10.446/2002"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T19:42:17.106365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=92", "doc_key": "7a02a973e5bd197759293ec7f91ca94d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ad18dea497b349234925ee84c9f661c6750c9621d0d9438a42e1a00ce769f3bc'),
  ('cpiuris2025::cff7e8e5970551dfae463fa483ea2814', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atribuição territorial das delegacias e investigações', '## Atribuição territorial das delegacias e investigações

Resumo objetivo: Atribui-se competência territorial às delegacias, independentemente de precatórias ou requisições. Isso pode ser dividido por natureza da infração penal, criando delegacias especializadas. O advogado do investigado pode impetrar habeas corpus para trancamento do inquérito em caso de irregularidade policial.

### Conceitos
- **Atribuição territorial**: Competência conferida às delegacias
- **Delegacia especializada**: Unidade que investiga crimes com natureza específica
- **Habeas corpus**: Mecanismo para trancamento do inquérito em caso de irregularidade policial
- **Investigação presidida por autoridade policial sem atribuições**: Situação que pode gerar mera irregularidade, não afetando a nulidade do processo penal
- **Precação**: Requisição para que uma autoridade competente compareça em outra circunscrição
- **Requisição**: Pedidos feitos por uma autoridade para que outra compareça em sua presença
- **Requisição policial**: Ato pelo qual a polícia solicita a presença de uma autoridade competente

### Referências legais
- Art. 102 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre atribuição territorial e delegacia especializada
- Conheça o mecanismo do habeas corpus em casos de irregularidade policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T19:55:18.903734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=93", "doc_key": "cff7e8e5970551dfae463fa483ea2814"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'eb0e7919c93e976ddd0c7a4f56db5a4034799f8c9352bd7c10caced6ca71c978'),
  ('cpiuris2025::d282d7be14179801c9236644050de252', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atribuição da Polícia Federal e Justiça Federal', '## Atribuição da Polícia Federal e Justiça Federal

A Polícia Federal tem atribuição para investigar crimes previstos na Lei Antiterrorismo e crimes de competência da Justiça Federal. Em casos de crime eleitoral, a investigação pode ser realizada pela Polícia Civil em atribuição subsidiária.

### Conceitos
- **Atribuição**: Conferimento de competência para uma autoridade policial
- **Polícia Federal**: Autoridade policial responsável por investigar crimes previstos na Lei Antiterrorismo e crimes de competência da Justiça Federal
- **Justiça Federal**: Autoridade judiciária responsável por processar e julgar crimes de competência da Justiça Federal
- **Atribuição subsidiária**: Conferimento de competência para uma autoridade policial em caso de falta de órgão da Polícia Federal no município onde o crime foi cometido

### Referências legais
- Art. 144, §1º, I e IV, da CF/88
- Lei n.º 13.260/16
- Art. 109 da Constituição Federal
- Art. 7º do CPPM

### Jurisprudência
- STF. 1ª Turma. HC 169348/RS, Rel. Min. Marco Aurélio, julgado em 17/12/2019 (Info 964)

### Dicas de prova
- Entenda a diferença entre atribuição e atribuição subsidiária
- Conheça as regras para fixação de competência territorial do juízo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 144, §1º, I e IV, da CF/88", "Lei n.º 13.260/16", "Art. 109 da Constituição Federal", "Art. 7º do CPPM"], "jurisprudence": ["STF. 1ª Turma. HC 169348/RS, Rel. Min. Marco Aurélio, julgado em 17/12/2019 (Info 964)"], "confidence": 0.8, "extracted_at": "2026-05-28T19:55:23.103740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=93", "doc_key": "d282d7be14179801c9236644050de252"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd1c997a52d1dc91d95ded89ea65d6afccab7c291841ba43c6c574697702c76ce'),
  ('cpiuris2025::e66741eb3ddb12249564710655b87b91', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Denúncia Anônima', '## Denúncia Anônima

A denúncia anônima não é abusiva, mas pode ser fonte de informação e provas. A autoridade policial deve realizar investigações preliminares para confirmar a credibilidade da denúncia e instaurar inquérito se houver aparência mínima de procedência.

### Conceitos
- **Denúncia Anônima**: denúncia feita sem identificação do autor
- **Investigação Preliminar**: investigação realizada para confirmar a credibilidade da denúncia
- **Inquérito Policial**: procedimento investigatório instaurado em caso de denúncia anônima

### Referências legais
- Art. 5º, § 2º do CP
- STF. 2ª Turma. HC 180709/SP

### Jurisprudência
- RE 123456
- HC 180709/SP

### Dicas de prova
- Diferenciar entre denúncia anônima e abusiva
- Investigação preliminar é fundamental para confirmar a credibilidade da denúncia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, § 2º do CP", "STF. 2ª Turma. HC 180709/SP"], "jurisprudence": ["RE 123456", "HC 180709/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T20:27:14.102371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=94", "doc_key": "e66741eb3ddb12249564710655b87b91"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2ffd22ce4997f3b35f44d4f1bde2c77a4e4a3642859ec65edba9e3ad18eb5502'),
  ('cpiuris2025::764d00f0b0baeb334b2a7c1b5702248f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Notitia Criminis e Delatio Criminis', '## Notitia Criminis e Delatio Criminis

A notitia criminis é o conhecimento da autoridade policial sobre um fato delituoso, podendo ser espontâneo, provocado ou coercitivo. A delatio criminis é uma comunicação da occorrência de infração penal por qualquer pessoa à autoridade policial.

### Conceitos
- **Notitia Criminis**: Conhecimento da autoridade policial sobre um fato delituoso
- **Delatio Criminis**: Comunicação da occorrência de infração penal por qualquer pessoa à autoridade policial
- **Notitia Criminis Cognitiva**: Conhecimento espontâneo ou provocado pela autoridade policial
- **Notitia Criminis Coercitiva**: Conhecimento forçado pela apresentação de indivíduo preso em flagrante à autoridade policial

### Referências legais
- Art. 5º, IV da CF/88

### Jurisprudência
- Info 819 STF

### Dicas de prova
- Distinção entre notitia criminis e delatio criminis
- Validade das denúncias anônimas
- Limitações da interceptação telefônica e busca e apreensão em casos de denúncia anônima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, IV da CF/88"], "jurisprudence": ["Info 819 STF"], "confidence": 0.8, "extracted_at": "2026-05-28T20:27:23.809660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=94", "doc_key": "764d00f0b0baeb334b2a7c1b5702248f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '24c39fe5bd331203654a967781784709924ad334468bb4c96c997983661539e9'),
  ('cpiuris2025::9ca50e4bcd9dad599d71ce2ff4106512', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Instauração do Inquérito Policial', '## Instauração do Inquérito Policial

A instauração do inquérito policial depende da espécie de ação penal. Pode ser feita de ofício, por requisição da autoridade judiciária ou do Ministério Público.

### Conceitos
- **Obrigatoriedade**: Princípio que obriga a instauração do inquérito policial em determinadas hipóteses
- **Requisição**: Procedimento pelo qual a autoridade judiciária ou o Ministério Público solicita a instauração do inquérito policial
- **Ação Penal Pública Incondicionada**: Tipo de ação penal que não depende de requisição da autoridade judiciária ou do Ministério Público

### Referências legais
- Art. 5º, I, do CPP
- Art. 40 do Código de Processo Penal
- ADI 4346/MG
- Info 652
- Info 649

### Jurisprudência
- STJ
- STF

### Dicas de prova
- Entenda a obrigatoriedade e a requisição no contexto do inquérito policial
- Conheça as hipóteses de ação penal pública incondicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, I, do CPP", "Art. 40 do Código de Processo Penal", "ADI 4346/MG", "Info 652", "Info 649"], "jurisprudence": ["STJ", "STF"], "confidence": 0.8, "extracted_at": "2026-05-28T20:42:46.771965+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=95", "doc_key": "9ca50e4bcd9dad599d71ce2ff4106512"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd11875394f74c2611999daf46371a93e9b2f713ed6d5267c9a06784464e3a3fd'),
  ('cpiuris2025::d055590d1de476ab0370ec0019844461', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requerimento do ofendido ou de seu representante legal', '## Requerimento do ofendido ou de seu representante legal

O artigo 5º, II, segunda parte, do CPP estabelece que o requerimento do ofendido ou de seu representante legal deve conter certas informações, como a narração do fato com todas as circunstâncias e a individualização do indiciado. O delegado verificará a procedência das informações para obstar a instauração de investigações temerárias.

### Conceitos
- **Requerimento**: Solicitação feita pelo ofendido ou seu representante legal
- **Delegado**: Autoridade policial responsável por verificar a procedência das informações
- **Investigação temerária**: Investigação realizada sem o devido requisito legal

### Referências legais
- Art. 5º, II, segunda parte, do CPP
- Art. 27 do CPP

### Dicas de prova
- Entenda a importância do requerimento do ofendido ou de seu representante legal
- Conheça as exigências legais para o início da investigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.96", "page_number": 96, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, II, segunda parte, do CPP", "Art. 27 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T21:12:09.658668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=96", "doc_key": "d055590d1de476ab0370ec0019844461"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd71aaf022b0928c6969132f7a2557bee390ee20888eea15b29074fd5dd2d58d2'),
  ('cpiuris2025::29f3bf5adc7c9db96ce40dde9f472eb0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Inquérito Policial', '## Investigação Criminal e Inquérito Policial

O requerimento para instaurar inquérito policial deve ser feito dentro do prazo decadencial de 6 meses após o conhecimento do autor do delito, sob pena de extinção da punibilidade. A instauração de inquérito é necessária na hipótese de prisão em flagrante e depende da manifestação do ofendido.

### Conceitos
- **Prazo decadencial**: Período durante o qual deve ser feito o requerimento para instaurar inquérito policial
- **Extinção da punibilidade**: Fim do prazo para ações criminais
- **Prisão em flagrante**: Ato de prisão imediata após o cometimento de um delito

### Referências legais
- Art. 107, IV, do CP
- Art. 6º e 7º do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre a busca pessoal e buscas domiciliares
- Entender o prazo decadencial e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.97", "page_number": 97, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 107, IV, do CP", "Art. 6º e 7º do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T21:12:29.820873+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=97", "doc_key": "29f3bf5adc7c9db96ce40dde9f472eb0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e5ba723d4801f3f3aca835ec05be559534dda027276a22d30df6f3d88c321770'),
  ('cpiuris2025::72f3522c2d5da4d4feef5bd920ea878b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acesso aos autos pelo Ministério Público', '## Acesso aos autos pelo Ministério Público

O Ministério Público tem acesso aos autos do processo desde que atuando como custos legis, evitando assim a remessa de documentos desnecessários.

### Conceitos
- **Custos legis**: Ato pelo qual o Ministério Público assume a representação do Estado em um processo.
- **Obrigatoriedade**: Princípio que obriga uma autoridade a agir ou a tomar uma determinada atitude, mesmo que não seja favorável à sua vontade.
- **Requisição**: Solicitação feita por um órgão do Ministério Público para que outra autoridade policial realize um ato específico.
- **Abstenção**: Ação de não participar ou não agir em uma situação, geralmente devido a uma razão justificada.
- **Princípio da remessibilidade**: Princípio que estabelece que os autos de um processo devem ser remetidos ao órgão competente para o caso concreto.
- **Hipótese de ilegalidade manifesta**: Situação em que a autoridade policial deve se recusar a realizar uma atitude ou agir, devido a uma razão justificada.
- **Princípio da obrigatoriedade**: Princípio que obriga uma autoridade a agir ou a tomar uma determinada atitude, mesmo que não seja favorável à sua vontade.
- **Custos legis**: Ato pelo qual o Ministério Público assume a representação do Estado em um processo.

### Referências legais
- Art. 326 do Código de Processo Penal

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Acesso ao Ministério Público nos processos criminais

### Dicas de prova
- Entenda o conceito de custos legis e sua importância no processo penal.
- Conheça as hipóteses em que a autoridade policial deve se recusar a realizar uma atitude ou agir.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 326 do Código de Processo Penal"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Acesso ao Ministério Público nos processos criminais"], "confidence": 0.8, "extracted_at": "2026-05-28T21:43:30.043378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=95", "doc_key": "72f3522c2d5da4d4feef5bd920ea878b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '665196957af40dd694035ca03a988a2d0b14847577375f3e0bb0caa008edda73'),
  ('cpiuris2025::15952f1ed577b118fc3faaef7c7aec7a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisição de dados cadastrais', '## Requisição de dados cadastrais

O membro do Ministério Público ou o delegado de polícia pode requisitar dados cadastrais da vítima ou suspeitos, com prazo de 24 horas.

### Conceitos
- **Requisição**: ação de solicitar informações
- **Cadastral**: relacionado a registros oficiais
- **Inquérito Policial**: investigação policial

### Referências legais
- Art. 13-A do CPP

### Dicas de prova
- Entenda o conceito de requisição e sua importância no processo penal.
- Conheça a Lei nº 13.344/16 e seu impacto na prática processual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 13-A do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T21:43:56.581801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=98", "doc_key": "15952f1ed577b118fc3faaef7c7aec7a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1d12102182854888c1f58d7a8fd8e9d1710cbc95f002735b8aa81a49a0f0e08c'),
  ('cpiuris2025::83c1802b3e3c6a2d7ed0f3ec1237ef6d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal', '## Investigação Criminal

A investigação criminal envolve coletar provas para esclarecer o fato e suas circunstâncias, ouvir as partes interessadas e proceder a reconhecimento de pessoas e coisas.

### Conceitos
- **Investigação Criminal**: Coleta de provas para esclarecer o fato e suas circunstâncias
- **Ouvido das partes**: A autoridade policial ouve as partes interessadas, incluindo o ofendido e o indiciado
- **Reconhecimento de pessoas e coisas**: Procedimento para identificar pessoas e coisas
- **Princípio do nemo tenetur se detegere**: O indiciado não é obrigado a se manifestar, mas deve ser advertido sobre seu direito ao silêncio
- **Curador para o indiciado menor de vinte e um anos**: Não necessário desde que houve revogação tácita do art. 15 do CPP

### Referências legais
- Art. 7º, inciso VII do CPP
- Art. 226 e 227 do CPP
- Art. 5º, LVIII da Constituição

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o princípio da não autoincriminação e o direito ao silêncio
- Reconhecimento de pessoas e coisas: procedimento e importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º, inciso VII do CPP", "Art. 226 e 227 do CPP", "Art. 5º, LVIII da Constituição"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T21:49:12.415420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=98", "doc_key": "83c1802b3e3c6a2d7ed0f3ec1237ef6d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5675f11b7cb9fc305abe0d2e2aa23fda6911966ffaa642a297205f251ad2892a'),
  ('cpiuris2025::21a4e515c6ecad9c1fc824676a0a8d3e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Diligência policial', '## Diligência policial

A diligência policial pode ser executada sem autorização judicial por até 30 dias, conforme o §2º do artigo, mas não é necessária em um prazo tão exíguo quanto 12 horas, de acordo com o §4º. Outros entendem que a diligência necessita de prévia autorização judicial para proteger os direitos à intimidade e à vida privada.

### Conceitos
- **Diligência policial**: Execução de medidas policiais sem autorização judicial
- **Autorização judicial**: Previa ação do juiz para permitir a execução de medidas policiais
- **Intimidade e vida privada**: Direitos protegidos pela Constituição que não podem ser invadidos sem autorização judicial
- **Prazo exíguo**: Prazo muito curto para a execução de medidas policiais

### Referências legais
- Art. 13-A do CPP
- Art. 13-B do CPP

### Jurisprudência
- ADI 5.642/DF
- STF julgado em 19/04/2024

### Dicas de prova
- Entenda a distinção entre diligência policial com e sem autorização judicial
- Conheça os direitos à intimidade e à vida privada e como eles se relacionam com a diligência policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 13-A do CPP", "Art. 13-B do CPP"], "jurisprudence": ["ADI 5.642/DF", "STF julgado em 19/04/2024"], "confidence": 0.8, "extracted_at": "2026-05-28T21:50:00.790913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=99", "doc_key": "21a4e515c6ecad9c1fc824676a0a8d3e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e834334d96e520c9abecc962a0ceddbdebbdee297c8149a678e29807336d9538'),
  ('cpiuris2025::901584fad7906d20e6b228ff7c4bec19', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisição de dados de empresas de telecomunicações para investigação criminal', '## Requisição de dados de empresas de telecomunicações para investigação criminal

O artigo 13-B estabelece regras para a requisição de dados de empresas de telecomunicações por parte do Ministério Público ou delegados de polícia, com o objetivo de localizar vítimas ou suspeitos de crimes relacionados ao tráfico de pessoas.

### Conceitos
- **Investigação criminal**: Ação processual destinada a esclarecer os fatos de um crime
- **Requisição de dados**: Peça formal feita para obter informações ou documentos de uma pessoa jurídica ou física
- **Autorização judicial**: Conhecimento legal que autoriza a realização de uma ação específica
- **Direito à intimidade**: Garantia constitucional que protege o direito do indivíduo à privacidade e à segurança pessoal
- **Interceptação telefônica**: Atividade de interceptação de comunicações telefônicas sem a autorização prévia de uma das partes envolvidas
- **Dados cadastrais**: Informações pessoais e biográficas registradas em um cadastro oficial

### Referências legais
- Art. 13-B do Código de Processo Penal

### Dicas de prova
- Entenda a distinção entre interceptação telefônica e requisição de dados de empresas de telecomunicações
- Avalie a constitucionalidade do artigo 13-B e sua relação com o direito à intimidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 13-B do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T21:50:05.171137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=99", "doc_key": "901584fad7906d20e6b228ff7c4bec19"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f49a43e87144ff60602ad1d9d6a82ac69840a9ccadf10762cda2d051f98c1cdb'),
  ('cpiuris2025::d5fe4a7a44ccc63ba31b36378bac53e3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisitos para a realização da investigação criminal', '## Requisitos para a realização da investigação criminal

A polícia não precisa de autorização judicial para realizar a investigação criminal, mas é necessário requisitar dados e informações cadastrais da vítima ou suspeitos, além de meios técnicos adequados.

### Conceitos
- **Investigação Criminal**: Procedimento realizado pela polícia para investigar um crime
- **Autorização Judicial**: Permissão legal necessária para realizar uma ação ou procedimento
- **Dados Cadastrais**: Informações pessoais e de identificação da vítima ou suspeitos
- **Meios Técnicos Apropriados**: Equipamentos e recursos necessários para localizar a vítima ou suspeitos

### Referências legais
- Art. 5º, LVII, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre investigação criminal e identificação criminal
- Conheça as hipóteses que autorizam a realização da identificação criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.100", "page_number": 100, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LVII, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T21:52:32.382313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=100", "doc_key": "d5fe4a7a44ccc63ba31b36378bac53e3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e8f50c324756836a199d6e2298fae41b7e621a703ccee73d56619e211b1a7422'),
  ('cpiuris2025::775dd39a60575974fe31a1d1451bcfeb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Indiciamento', '## Investigação Criminal e Indiciamento

Discute-se a constitucionalidade do art. 5º-A, que dispõe sobre a identificação do perfil genético do acusado; o art. 21 do CPP, que trata da incomunicabilidade do indiciado preso; e o conceito de indiciamento, que consiste no ato de atribuir autoria ou participação de uma infração penal a uma pessoa.

### Conceitos
- **Identificação do perfil genético**: O acusado não pode ser obrigado a fornecer seu perfil genético, mas em caso de descarte, mostra-se possível sua coleta.
- **Incomunicabilidade do indiciado preso**: O art. 21 do CPP prevê a incomunicabilidade do indiciado preso, mas é considerada inconstitucional pela CF/88
- **Indiciamento**: Ato formal que atribui autoria ou participação de uma infração penal a uma pessoa, com base em juízo de probabilidade de autoria.

### Referências legais
- Art. 5º-A do CPP
- Art. 21 do CPP
- Art. 136, §3º, IV da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o sujeito indiciado e o suspeito ou investigado.
- Conheça as espécies de indiciamento: direto e indireto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.101", "page_number": 101, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º-A do CPP", "Art. 21 do CPP", "Art. 136, §3º, IV da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T21:53:12.037280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=101", "doc_key": "775dd39a60575974fe31a1d1451bcfeb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ca37c165620f455c35857bdafb4fe5a2b7974b8225cb928be904efca018ad16a'),
  ('cpiuris2025::0525fd0aa479205bd1c551ed80da20fd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Indiciamento Direto e Indireto em Investigação Criminal', '## Indiciamento Direto e Indireto em Investigação Criminal

O indiciamento é ato privativo do delegado de polícia, que aponta a autoria do ilícito. Não pode ser requerido pelo magistrado ou Ministério Público, exceto em casos específicos.

### Conceitos
- **Indiciamento Direto**: Ato do delegado de polícia que aponta a autoria do ilícito
- **Indiciamento Indireto**: Requisição do magistrado ou Ministério Público para o indiciamento de uma pessoa
- **Atribuição do Indiciamento**: É ato privativo do delegado de polícia, conforme Lei n.º 12.830/13
- **Sujeito Passivo do Indiciamento**: Pode ser qualquer pessoa, exceto em casos específicos, como o membro do Ministério Público ou magistrado

### Referências legais
- Art. 2º da Lei n.º 12.830/13
- Art. 41, II e parágrafo único da Lei n.º 8.625/93

### Jurisprudência
- STJ. 5ª Turma. RHC 47984-SP
- STF. 2ª Turma. HC 115015/SP

### Dicas de prova
- Entenda a diferença entre indiciamento direto e indireto
- Conheça as exceções ao indiciamento, como a prerrogativa do membro do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º da Lei n.º 12.830/13", "Art. 41, II e parágrafo único da Lei n.º 8.625/93"], "jurisprudence": ["STJ. 5ª Turma. RHC 47984-SP", "STF. 2ª Turma. HC 115015/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T21:53:34.961436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=102", "doc_key": "0525fd0aa479205bd1c551ed80da20fd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6c91d7bfde351ed6698a79cc64be555e4b6b8184545c9d851c7ae1c9af66c90b'),
  ('cpiuris2025::c10b536f7e099863e60b136f8ebddf81', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Indiciamento de autoridades com foro por prerrogativa de função', '## Indiciamento de autoridades com foro por prerrogativa de função

O STF entende que é necessária autorização do ministro-relator do inquérito para proceder ao indiciamento de autoridades com foro por prerrogativa de função, excetuadas hipóteses legais.

### Conceitos
- **Indiciamento**: Procedimento que visa determinar a existência de crime
- **Autoridade policial**: Entidade responsável pela investigação de crimes
- **Foro por prerrogativa de função**: Direito concedido a certas autoridades, como governadores e parlamentares
- **Ministro-relator**: Magistrado que orienta o inquérito
- **Tribunal competente**: Entidade responsável por julgar o caso

### Referências legais
- Art. 33, parágrafo único da Lei Complementar nº 35/79

### Jurisprudência
- Súmula 432 STF

### Dicas de prova
- Distinção entre autoridades com foro por prerrogativa de função e demais autoridades
- Importância do ministro-relator no inquérito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 33, parágrafo único da Lei Complementar nº 35/79"], "jurisprudence": ["Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-28T21:54:47.044209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=102", "doc_key": "c10b536f7e099863e60b136f8ebddf81"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3a0aee7ee1f7632baebf2a532cc7d62cc30be3421a6c9df32f2e16094729bd60'),
  ('cpiuris2025::d9bf4990a7fbedff4c1fe23988700f42', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Autoridade com foro por prerrogativa de função', '## Autoridade com foro por prerrogativa de função

Necessária autorização do tribunal para instauração das investigações e realização de diligências, bem como para o indiciamento da autoridade, exceto em casos específicos.

### Conceitos
- **Autoridade com foro por prerrogativa de função**: Ente que detém poderes jurisdicionais exclusivos
- **Instauração das investigações**: Procedimento para iniciar a investigação de um crime
- **Diligências investigatórias**: Ações realizadas para coletar provas e evidências
- **Indiciamento da autoridade**: O processo de identificação do sujeito passivo do inquérito

### Referências legais
- Art. 102, § 3º, inciso II, do CPC/2015

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Entenda a distinção entre instauração das investigações e início das investigações
- Conheça as exceções ao indiciamento da autoridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, § 3º, inciso II, do CPC/2015"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-28T21:55:41.017076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=103", "doc_key": "d9bf4990a7fbedff4c1fe23988700f42"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2e201c48c05f0018b74df0b4e66a2213d3a6b11b07a0603da6437619233d784d'),
  ('cpiuris2025::6f4442de765c8e528a597f3975859eb6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Autorização do STF', '## Investigação Criminal e Autorização do STF

As investigações criminais envolvendo autoridades com foro privativo no STF somente podem ser iniciadas após autorização formal do STF. As diligências devem tramitar sob a supervisão de um Ministro-Relator.

### Conceitos
- **Autorização do STF**: Necessária para iniciar investigações criminais envolvendo autoridades com foro privativo no STF
- **Investigação Policial**: Não é chamada inquérito ''policial'', mas sim inquérito criminal sob a supervisão do STF
- **Ministro-Relator**: Supervisa as diligências investigatórias envolvendo autoridades com foro privativo no STF
- **Competência do STF**: A Corte tem competência para julgar ações penais contra autoridades com foro privativo no STF

### Referências legais
- Art. 102, § 3º, inciso IV da CF/88
- STF. Decisão monocrática. HC 133835 MC, Rel. Min. Celso de Mello, julgado em 18/04/2016 (Info 825)

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre autorização para início das investigações e indiciamento
- Entender a importância da supervisão do STF em investigações criminais envolvendo autoridades com foro privativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, § 3º, inciso IV da CF/88", "STF. Decisão monocrática. HC 133835 MC, Rel. Min. Celso de Mello, julgado em 18/04/2016 (Info 825)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T21:56:19.772597+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=103", "doc_key": "6f4442de765c8e528a597f3975859eb6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5028217cf05d5ebd786420c8a805c5388b373c6ae0c59fd66d5e1d280865a8ce'),
  ('cpiuris2025::afb8d0240ab40de422dc970c2c76ea64', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Conclusão do Inquérito Policial', '## Investigação Criminal e Conclusão do Inquérito Policial

Resumo sobre a atribuição de competência para investigar crimes, procedimentos para o início das investigações, desindiciamento e conclusão do inquérito policial.

### Conceitos
- **Atribuição de competência**: Determinação da autoridade policial ou judiciária que deve investigar um crime
- **Desindiciamento**: Procedimento para desligar uma pessoa investigada do inquérito policial em caso de constrangimento ilegal à liberdade de locomoção
- **Conclusão do inquérito policial**: Relatório final da autoridade policial que apresenta as principais diligências realizadas durante o inquérito

### Referências legais
- Art. 17-D da Lei de Lavagem de Dinheiro (Lei nº 12.683/12)
- ADI 4911/DF
- Art. 10, §1º, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da atribuição de competência para investigar crimes.
- Conheça o procedimento para desindiciamento e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.104", "page_number": 104, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 17-D da Lei de Lavagem de Dinheiro (Lei nº 12.683/12)", "ADI 4911/DF", "Art. 10, §1º, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T21:57:17.072924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=104", "doc_key": "afb8d0240ab40de422dc970c2c76ea64"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2c1a253c7f876256c4c8b71024ad06fe64c0e6b6263c6d69c55e55969e594d8a'),
  ('cpiuris2025::b2c7367b2d7d1981f23460e00bfe9191', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Lei Anticrime e tramitação do inquérito policial', '## Lei Anticrime e tramitação do inquérito policial

A Lei Anticrime estabelece que o juiz das garantias receberá os autos do inquérito, separando a investigação da instrução. O prazo para finalização do inquérito é de 10 dias se o indiciado tiver preso ou 30 dias se solto.

### Conceitos
- **Lei Anticrime**: Lei que estabelece a separação entre a investigação e a instrução do processo
- **juiz das garantias**: Magistrado responsável pela tramitação do inquérito policial
- **prazo de finalização do inquérito**: Prazo estabelecido para conclusão da investigação

### Referências legais
- Art. 10, caput, do CPP

### Dicas de prova
- Entenda a separação entre a investigação e a instrução do processo
- Conheça o prazo de finalização do inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T21:58:19.886067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=105", "doc_key": "b2c7367b2d7d1981f23460e00bfe9191"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f4a5e7a4996808c6f1bc3ee2999f0a6a8ad0661bdb204dd7494e9c014df0f69e'),
  ('cpiuris2025::fd45ad60d1fb2a7b13093ff4cda176b4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tramitação Direta do Inquérito Policial', '## Tramitação Direta do Inquérito Policial

A tramitação direta do inquérito policial entre a polícia e o Ministério Público é uma questão controversa, com a maioria da doutrina defendendo que isso violaria o sistema acusatório. No entanto, o STF entende que o Estado-membro pode legislar sobre o tema, mas apenas complementando as normas gerais trazidas pelo CPP.

### Conceitos
- **Tramitação Direta**: Procedimento em que os autos do inquérito policial são enviados diretamente ao juiz competente ou entre a polícia e o Ministério Público
- **Sistema Acusatório**: Sistema jurídico que se baseia na acusação pública para processar um indivíduo
- **Garantia da Duração Razoável do Processo**: Direito do réu de ser processado de forma razoável e justa
- **Economia Processual**: Princípio que visa reduzir o tempo e os custos do processo
- **Eficiência**: Princípio que visa garantir a eficácia e a eficiência do processo

### Referências legais
- Art. 10, §1º, CPP; Art. 22, I, da CF/88; Art. 24, §1º, da CF/88

### Jurisprudência
- STF. Plenário. ADI 2886/RJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre tramitação direta e acusatória
- Conheça as garantias do processo, como duração razoável e economia processual
- Avalie a importância da eficiência no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, §1º, CPP; Art. 22, I, da CF/88; Art. 24, §1º, da CF/88"], "jurisprudence": ["STF. Plenário. ADI 2886/RJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T21:59:07.112521+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=105", "doc_key": "fd45ad60d1fb2a7b13093ff4cda176b4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '95ff8b78d00192e85b449767c4177031928b30e54356de86e0e55eb89f55127e'),
  ('cpiuris2025::485cc1eaf1b407de5ee90abfe774a76d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prorrogação do prazo do inquérito policial', '## Prorrogação do prazo do inquérito policial

A lei permite a prorrogação do prazo do inquérito policial quando o indiciado estiver solto, desde que dentro de um prazo impróprio. O juiz pode prorrogar por até 15 dias, uma única vez, e em caso de necessidade, pode decidir novamente.

### Conceitos
- **Prorrogação do prazo**: A ação de estender o prazo do inquérito policial
- **Indiciado solto**: O indivíduo que está sendo investigado, mas não está preso
- **Prazo impróprio**: O prazo estabelecido pela lei para a conclusão do inquérito policial
- **Prisão preventiva**: A medida cautelar que impede o indivíduo de ser julgado

### Referências legais
- Art. 10, §3º, do CPP
- Art. 3º-B, §2º, do CPP
- Lei nº 5.010/66, art. 66, caput

### Jurisprudência
- ADI 2886/RJ
- STF. Plenário

### Dicas de prova
- Entenda a diferença entre prorrogação e relaxamento da prisão preventiva
- Conheça as regras para a prorrogação do prazo do inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.106", "page_number": 106, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, §3º, do CPP", "Art. 3º-B, §2º, do CPP", "Lei nº 5.010/66, art. 66, caput"], "jurisprudence": ["ADI 2886/RJ", "STF. Plenário"], "confidence": 0.8, "extracted_at": "2026-05-28T22:00:19.709962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=106", "doc_key": "485cc1eaf1b407de5ee90abfe774a76d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8b2076f468dc4bd0977d73233fa4c5c968ffc12bf717f5451ebee336cb8a86c7'),
  ('cpiuris2025::f0e89ec4ea1e59e17d6b8a1ed532ac99', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Contagem do prazo de prisão preventiva', '## Contagem do prazo de prisão preventiva

A contagem do prazo de prisão preventiva tem natureza processual e é contada nos moldes do art. 798 do CPP, excluindo-se o dia do começo e incluindo-se o dia do vencimento.

### Conceitos
- **Prazo processual**: Prazo que tem natureza jurídica processual
- **Prazo material**: Prazo contado na forma do Código Penal
- **Art. 798 do CPP**: Regula a contagem do prazo de prisão preventiva

### Referências legais
- Art. 798 do CPP
- Art. 10 do Código Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prazo processual e material
- Conheça o artigo 798 do CPP para calcular o prazo de prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.107", "page_number": 107, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 798 do CPP", "Art. 10 do Código Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:00:31.184345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=107", "doc_key": "f0e89ec4ea1e59e17d6b8a1ed532ac99"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'de73ce4eb0969a49c13a7a727b4591663b31b7f1109f59f4726e4dfda23b209a'),
  ('cpiuris2025::592ce4c3e1a60654b7403c897d20abc5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento do Inquérito Policial', '## Arquivamento do Inquérito Policial

O arquivamento do inquérito policial é atribuição do Ministério Público, não da autoridade judiciária. A partir da nova redação do art. 28 do CPP, o arquivamento ocorre totalmente no âmbito do órgão acusador.

### Conceitos
- **Princípio da Indisponibilidade**: O princípio que impede a autoridade policial mandar arquivar autos de inquérito
- **Atribuição do Ministério Público**: O Ministério Público é o titular da opinio delicti e tem a atribuição de decidir sobre o arquivamento do inquérito
- **Lei Anticrime**: A Lei nº 13.964/19 que alterou a redação do art. 28 do CPP
- **Crimes contra a Economia Popular**: Há previsão de recurso de ofício da decisão de arquivamento em crimes contra a economia popular

### Referências legais
- Art. 17 do CPP
- Art. 28 do CPP
- Lei nº 13.964/19
- Art. 76 da Lei nº 9.099/95

### Jurisprudência
- STF. 2ª Turma. Inq 4420/DF. Rel. Min. Gilmar Mendes
- Info 912 do STF

### Dicas de prova
- Entenda o princípio da indisponibilidade e a atribuição do Ministério Público
- Conheça a nova redação do art. 28 do CPP e sua aplicação
- Aprenda sobre os crimes contra a economia popular e a previsão de recurso de ofício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 17 do CPP", "Art. 28 do CPP", "Lei nº 13.964/19", "Art. 76 da Lei nº 9.099/95"], "jurisprudence": ["STF. 2ª Turma. Inq 4420/DF. Rel. Min. Gilmar Mendes", "Info 912 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:02:23.614537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=108", "doc_key": "592ce4c3e1a60654b7403c897d20abc5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '99388f68ead3c38ff164aaa008186904af04fdb573a4994480eb6c33cc573378'),
  ('cpiuris2025::4d9d8198106ae89812be9d3c7af6b96d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência de investigação criminal', '## Competência de investigação criminal

A declinação de competência de investigação sem sucesso não representa apenas procrastinação e violação à duração razoável do processo, mas também à dignidade da pessoa humana. O Poder Judiciário exerce uma função de supervisão judicial para impedir coações ilegais pelo Estado-acusador.

### Conceitos
- **Competência de investigação**: A competência de investigação é a atribuição do poder judiciário para iniciar e conduzir as investigações criminais.
- **Declaração de competência**: É a decisão do juiz que determina a competência da causa para o tribunal competente.
- **Duração razoável do processo**: O prazo razoável para a conclusão do processo, garantido pela Constituição Federal.
- **Dignidade da pessoa humana**: A proteção dos direitos e dignidade das pessoas envolvidas no processo judicial.

### Referências legais
- Art. 109, § 4º, inciso IV do CPP
- Súmula 282 do STF

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Competência de investigação criminal

### Dicas de prova
- Entenda a competência de investigação e sua declaração.
- Conheça a duração razoável do processo e sua importância.
- Aprenda sobre a dignidade da pessoa humana nos processos judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 4º, inciso IV do CPP", "Súmula 282 do STF"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Competência de investigação criminal"], "confidence": 0.8, "extracted_at": "2026-05-28T22:03:05.480234+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=108", "doc_key": "4d9d8198106ae89812be9d3c7af6b96d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5f8ea08320fb97ccdd7841f0dfe8b5c7eaa0829a04e161e5909fa84f65b75c3e'),
  ('cpiuris2025::430d059dc2c22dda3bb97f7f2c825b7b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento do Inquérito Policial', '## Arquivamento do Inquérito Policial

O procedimento de arquivamento sofreu alterações com a Lei Anticrime. O órgão do Ministério Público pode requerer o arquivamento, mas deve submeter sua manifestação ao juiz competente e comunicar as partes envolvidas.

### Conceitos
- **Arquivamento**: Procedimento que encerra a investigação criminal
- **Lei Anticrime**: Lei que alterou o procedimento de arquivamento do inquérito policial
- **Denúncia**: Ação do Ministério Público para condenar o réu
- **Revisão Ministerial**: Instância que homologa a denúncia ou arquivamento do inquérito policial

### Referências legais
- Art. 28 da Lei n.º 13.964/19 (Lei Anticrime)

### Jurisprudência
- STJ. 5ª Turma. AgRg no REsp 1284335/MG
- REsp 1284335/MG

### Dicas de prova
- Distinção entre denúncia e arquivamento do inquérito policial
- Importância da comunicação às partes envolvidas
- Revisão ministerial: instância que homologa a denúncia ou arquivamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 da Lei n.º 13.964/19 (Lei Anticrime)"], "jurisprudence": ["STJ. 5ª Turma. AgRg no REsp 1284335/MG", "REsp 1284335/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T22:03:21.654461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=109", "doc_key": "430d059dc2c22dda3bb97f7f2c825b7b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fec27b5b9a8b01f118a9e20397885942278f9c9252a234160cf55f1ab85f645c'),
  ('cpiuris2025::63e9ee73fa57aa7afed975b2e4e0c352', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento no processo penal', '## Arquivamento no processo penal

O arquivamento no processo penal ocorre com a concordância do juiz ou após a devolução dos autos ao Procurador-Geral de Justiça.

### Conceitos
- **Arquivamento**: Procedimento pelo qual os autos são encerrados sem julgamento
- **Princípio da obrigatoriedade**: Requisito segundo o qual o juiz deve concordar com a decisão do Ministério Público
- **Função anômala**: Exercida pelo juiz ao concordar ou discordar do arquivamento

### Referências legais
- Art. 28 do CPP

### Dicas de prova
- Distinção entre concordância e discordância do juiz
- Entendimento da função anômala do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:03:53.987801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=109", "doc_key": "63e9ee73fa57aa7afed975b2e4e0c352"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7ca5ae453513187527f228bb737f90c33083b249d2ac1fb4bf971a6450364554'),
  ('cpiuris2025::4eb047546ba2d76111a30400c49fa369', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento na nova redação do art. 28 do CPP', '## Procedimento na nova redação do art. 28 do CPP

A nova redação do art. 28 do CPP estabelece que o magistrado não participa do arquivamento e não pode discordar do pedido de arquivamento, mas a interpretação do STF permite retornar à sistemática anterior, permitindo controle judicial do arquivamento.

### Conceitos
- **independência funcional**: Princípio que estabelece a autonomia dos órgãos do Ministério Público
- **promotor natural**: O órgão do Ministério Público competente para processar e julgar um caso específico
- **sistema acusatório**: Sistema que prioriza a investigação e o processo contra o autor de um crime
- **controle judicial**: Direito do juiz de interferir na decisão do Ministério Público sobre o arquivamento de um inquérito

### Referências legais
- Art. 10, IX, “d”, da Lei n.º 8.625/93; Art. 28 do CPP; Art. 5º, XXXV da CF

### Jurisprudência
- MS 21.081-DF - Info 565; ADI’s 6298, 6299, 6300 e 6305

### Dicas de prova
- Entenda a independência funcional e o princípio do promotor natural
- Conheça o sistema acusatório e seu impacto na nova redação do art. 28 do CPP
- Análise da interpretação do STF sobre o controle judicial do arquivamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, IX, “d”, da Lei n.º 8.625/93; Art. 28 do CPP; Art. 5º, XXXV da CF"], "jurisprudence": ["MS 21.081-DF - Info 565; ADI’s 6298, 6299, 6300 e 6305"], "confidence": 0.8, "extracted_at": "2026-05-28T22:04:30.855495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=110", "doc_key": "4eb047546ba2d76111a30400c49fa369"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dc207265baed6067616a3d2464a12c6d7ddd170c35609d690176d2d72386eb69'),
  ('cpiuris2025::fc4a0cd99b6bd1310193220afb66c63e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ciência e comunicação de fatos ao Ministério Público', '## Ciência e comunicação de fatos ao Ministério Público

O artigo 28 do Código de Processo Penal estabelece regras para a ciência e comunicação de fatos ao Ministério Público, incluindo prazos e condições.

### Conceitos
- **Ciência**: A notificação oficial dos fatos ao Ministério Público
- **Comunicação**: A notificação oficial de fatos a outras partes interessadas, como autoridade policial e vítima
- **Prazo**: O tempo limite para a ciência ou comunicação de fatos
- **Investigado**: A pessoa que é objeto da investigação
- **Vítima**: A pessoa afetada pelo crime
- **Ministério Público**: O órgão responsável pela investigação e persecução do crime

### Referências legais
- Art. 28, § 1º, do Código de Processo Penal

### Dicas de prova
- Entenda a importância da ciência e comunicação de fatos ao Ministério Público
- Conheça os prazos estabelecidos para a ciência e comunicação de fatos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28, § 1º, do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:07:03.039278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=111", "doc_key": "fc4a0cd99b6bd1310193220afb66c63e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6b0f2ae4c73660faf0ecf1ffcbf81e77a1b9acd1228972f3dc74aaf031927f5f'),
  ('cpiuris2025::43c795166f98bf44c1660d388714ef40', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Instauração do Inquérito e Comunicação ao Juízo Competente', '## Instauração do Inquérito e Comunicação ao Juízo Competente

O instaurador deve comunicar o arquivamento ao juiz competente, mas não há obrigatoriedade de encaminhar os autos para o PGJ ou CCR. O MP pode encaminhar os autos para fins de homologação.

### Conceitos
- **Instauração do Inquérito**: Procedimento que visa investigar um crime
- **Comunicação ao Juízo Competente**: Obrigação de informar o juiz sobre a instauração e arquivamento do inquérito
- **Encaminhamento de Autos**: Ação do MP em enviar os autos para o PGJ ou CCR
- **Decisão Homologatória**: Procedimento que confirma a decisão de arquivamento

### Referências legais
- Art. 102 do CP
- Lei nº 13.964/19, art. 5º

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Distinção entre comunicação e encaminhamento de autos
- Entendimento do STF sobre o sistema híbrido de arquivamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 do CP", "Lei nº 13.964/19, art. 5º"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:07:15.575047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=110", "doc_key": "43c795166f98bf44c1660d388714ef40"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ec9da43d46c7f38dad9f22ca266f8fa11cb3bb64a06230e24972eae43e6969f3'),
  ('cpiuris2025::8ceab16a54e1b3f0c0816dc60f964df1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento de Inquérito Policial e Decisão do Ministério Público', '## Arquivamento de Inquérito Policial e Decisão do Ministério Público

O artigo 19 da Resolução CNMP 289/2024 estabelece a decisão do membro do Ministério Público responsável pelo inquérito policial, procedimento investigatório criminal ou elementos informativos de natureza criminal sobre o arquivamento dos autos. O §1º determina a comunicação ao juízo competente, à vítima e à autoridade policial.

### Conceitos
- **Arquivamento**: Decisão do Ministério Público que encerra o inquérito policial ou procedimento investigatório criminal
- **Decisão ministerial**: Ato do membro do Ministério Público responsável pelo inquérito policial, procedimento investigatório criminal ou elementos informativos de natureza criminal
- **Comunicação ao juízo competente**: Notificação ao juiz que preside o caso sobre a decisão de arquivamento
- **Vítima**: Pessoa que sofreu ou está sendo vítima de um crime
- **Investigado**: Pessoa acusada de cometer um crime

### Referências legais
- Art. 10, IX, “d”, da Lei nº 8.625/93
- Resolução CNMP 289/2024

### Jurisprudência
- ADI''s 6298, 6299, 6300 e 6305

### Dicas de prova
- Entenda a importância da comunicação ao juízo competente após a decisão de arquivamento
- Conheça as regras para a designação do membro do Ministério Público responsável pelo inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, IX, “d”, da Lei nº 8.625/93", "Resolução CNMP 289/2024"], "jurisprudence": ["ADI''s 6298, 6299, 6300 e 6305"], "confidence": 0.8, "extracted_at": "2026-05-28T22:07:58.082080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=111", "doc_key": "8ceab16a54e1b3f0c0816dc60f964df1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'df64effb8de5ec38eb7f0cb41c835f20c954928d3705a438a822f125639d6022'),
  ('cpiuris2025::7be2c9480919c98c2f88fcca454a842d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Instância de Revisão Ministerial', '## Instância de Revisão Ministerial

A instância de revisão ministerial é o Procurador-Geral de Justiça, responsável por homologar os arquivamentos e receber as declinações de atribuição de competência.

### Conceitos
- **Procurador-Geral de Justiça**: O órgão responsável pela instância de revisão ministerial.
- **Competência**: A atribuição da competência para processar um caso específico.
- **Arquivamento**: A decisão de encerrar um inquérito policial ou processo sem procedimentos further.
- **Declinação de Atribuição**: A declaração feita pelo membro do Ministério Público que não tem competência para processar um caso específico.

### Referências legais
- Art. 10, IX, ''d'' da Lei nº 8.625/93
- Art. 28 do CPP
- Art. 62, IV, da LC nº 75/93
- Art. 171, V, da LC nº 75/93

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência do Procurador-Geral de Justiça e como ele se relaciona com o arquivamento.
- Conheça as diferenças entre a redação anterior e atual do artigo 10, IX, ''d'' da Lei nº 8.625/93.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, IX, ''d'' da Lei nº 8.625/93", "Art. 28 do CPP", "Art. 62, IV, da LC nº 75/93", "Art. 171, V, da LC nº 75/93"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:09:54.455093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=112", "doc_key": "7be2c9480919c98c2f88fcca454a842d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dbd2e5da6e234e67dcbe456dc3f75d174dcc4a3f8f142c76ca2d9da413a6b7db'),
  ('cpiuris2025::c5f410b13f85e4c7624511e037791ce9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Instância de Revisão Ministerial', '## Instância de Revisão Ministerial

A nova redação estabelece a instância de revisão ministerial para arquivamento, exceto em casos originários do Procurador-Geral. A competência é do órgão de instância de revisão ministerial, que pode homologar o arquivamento.

### Conceitos
- **Instância de Revisão Ministerial**: Órgão responsável pela revisão e homologação de arquivamentos
- **Competência Originária**: Direito do Procurador-Geral de Justiça para tomar decisões sobre o arquivamento em casos próprios
- **Revisão Ministerial**: Processo que visa revisar e homologar o arquivamento de um inquérito criminal

### Referências legais
- Art. 357, §1º, do Código Eleitoral
- Art. 136, IV, da LC nº 75/93
- Art. 28 do CPP

### Jurisprudência
- RE 123456
- Info 558

### Dicas de prova
- Entenda a competência originária e a revisão ministerial
- Conheça as instâncias de revisão ministerial para arquivamento
- Aprenda com o julgado do STF sobre o Procurador-Geral de Justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 357, §1º, do Código Eleitoral", "Art. 136, IV, da LC nº 75/93", "Art. 28 do CPP"], "jurisprudence": ["RE 123456", "Info 558"], "confidence": 0.8, "extracted_at": "2026-05-28T22:10:28.228256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=113", "doc_key": "c5f410b13f85e4c7624511e037791ce9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '70659c7e376a6a046440d6431df7c7c72b0b16dde4892231ac72d2cbe05da926'),
  ('cpiuris2025::7f80b6e0862d50a2ab1921671d3b729f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento de Inquérito Policial e Procedimento Investigatório Criminal', '## Arquivamento de Inquérito Policial e Procedimento Investigatório Criminal

Regulamenta o arquivamento de inquéritos policiais e procedimentos investigatórios criminais, incluindo as providências a serem tomadas em caso de retratação do membro do Ministério Público.

### Conceitos
- **Retratação**: Ação pelo qual o membro do Ministério Público reconhece sua participação no crime
- **Provocação ao órgão de revisão ministerial**: Ação que visa influenciar a decisão do órgão de revisão ministerial em relação ao arquivamento do inquérito
- **Requisição de diligências úteis e necessárias**: Providência tomada para realizar diligências adicionais para instruir o caso
- **Ajuizamento da ação penal**: Procedimento que visa processar o réu por crime cometido
- **Jurisprudência própria**: Súmulas, enunciados e orientações estabelecidas pelo órgão de revisão ministerial para orientar a decisão em casos semelhantes

### Referências legais
- Art. 19-B
- Art. 19-C
- Art. 19-D
- Art. 19-E
- Art. 19-F
- Art. 19-G
- Art. 19-H
- Art. 19-I
- Art. 19-J

### Dicas de prova
- Entenda a diferença entre retratação e provocação ao órgão de revisão ministerial
- Conheça as providências a serem tomadas em caso de retratação do membro do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 19-B", "Art. 19-C", "Art. 19-D", "Art. 19-E", "Art. 19-F", "Art. 19-G", "Art. 19-H", "Art. 19-I", "Art. 19-J"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:10:44.030768+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=112", "doc_key": "7f80b6e0862d50a2ab1921671d3b729f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '904bc0bb2a8708b24c2a4d0710a3b9427d23792992287990cfb46b4b8a4cedec'),
  ('cpiuris2025::de2349381e0d7c63935c1523122db07f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento de Investigação Criminal', '## Arquivamento de Investigação Criminal

O arquivamento de investigação criminal não é coisa julgada material e não precisa ser homologado pelo Poder Judiciário. O chefe do Ministério Público estadual é autoridade para aferir a legitimidade do arquivamento.

### Conceitos
- **Cosa Julgada Material**: Conceito jurídico que se refere à decisão final de um processo que não pode ser reaberto
- **Legitimidade do Arquivamento**: A capacidade de um ato ou decisão ser considerada válida e legítima

### Referências legais
- Art. 12, XI da Lei nº 8.625/93

### Jurisprudência
- STF. 1ª Turma. MS 34730/DF
- RE 123456

### Dicas de prova
- Entenda a diferença entre coisa julgada material e coisa julgada processual
- Conheça o papel do chefe do Ministério Público estadual na aferição da legitimidade do arquivamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 12, XI da Lei nº 8.625/93"], "jurisprudence": ["STF. 1ª Turma. MS 34730/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T22:12:04.429985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=113", "doc_key": "de2349381e0d7c63935c1523122db07f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b9ab91aac8ff3f60669d5e43cdaedae36fd181dcb44df0f9641b981892763f82'),
  ('cpiuris2025::4753caeb3017c0bdef4f313c723ca877', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento no âmbito do Ministério Público', '## Arquivamento no âmbito do Ministério Público

O arquivamento ocorre quando não há opinio delicti a favor da ação penal, ou seja, quando não há convicção da autoria e materialidade do crime.

### Conceitos
- **Arquivamento**: Decisão administrativa que não envolve mais uma decisão judicial
- **Opinio delicti**: Convicção da autoria e materialidade do crime
- **Ministério Público**: Entidade responsável por processar ações penais

### Referências legais
- Art. 28, nova redação

### Dicas de prova
- Diferenciar entre decisão judicial e administrativa
- Entender o conceito de opinio delicti', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28, nova redação"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:12:24.427797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=114", "doc_key": "4753caeb3017c0bdef4f313c723ca877"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8bd0c236ef5261c586d27ac2ace4ab1edc2d3917f6196b603392e3e2768a61e1'),
  ('cpiuris2025::9a08ff3eda72bb064629a2fb2e109f8d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento do Inquérito Policial', '## Arquivamento do Inquérito Policial

O arquivamento do inquérito policial ocorre quando não há justa causa para a ação penal, ou seja, quando faltar pressuposto processual ou condição para o exercício da ação penal.

### Conceitos
- **Arquivamento do Inquérito Policial**: Ocorre quando não há justa causa para a ação penal
- **Pressuposto Processual**: Falta de condição para o exercício da ação penal
- **Justa Causa**: Condição necessária para o exercício da ação penal
- **Rejeição da Peça Acusatória**: Ocorre quando não há justa causa para a ação penal
- **Absolvição Sumária**: Ocorre quando o juiz verifica a existência de excludente da ilicitude ou culpabilidade do agente

### Referências legais
- Art. 395, II e III do CPP
- Art. 397, I, II e III do CPP
- Art. 396-A do CPP

### Dicas de prova
- Diferenciar entre rejeição da peça acusatória e absolvição sumária
- Entender a importância da justa causa para o exercício da ação penal
- Conhecer as hipóteses de arquivamento do inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395, II e III do CPP", "Art. 397, I, II e III do CPP", "Art. 396-A do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:13:26.360271+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=114", "doc_key": "9a08ff3eda72bb064629a2fb2e109f8d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2a8a975d8d5679efa34582bd16679872843213a3db910bfe7ff9014228a7403f'),
  ('cpiuris2025::2aca3247d5631e8074445e657ef820fb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento no Processo Penal', '## Arquivamento no Processo Penal

O arquivamento não cria coisa julgada material, exceto em casos de atipicidade. Com a nova redação do art. 28 do CPP, o arquivamento passa a ser um ato administrativo composto.

### Conceitos
- **Causa Julgada Material**: Condição necessária para que o arquivamento seja considerado coisa julgada
- **Arquivamento**: Atividade processual que resulta na extinção do processo penal
- **Inquérito**: Investigação formalizada pelo juiz para apurar a existência de crime
- **Desarquivamento**: Ação que visa reabrir o inquérito e continuar a investigação
- **Oferecimento da Denúncia**: Atividade processual que resulta na apresentação formal da acusação ao juiz

### Referências legais
- Art. 28 do CPP
- Súmula 858/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre coisa julgada material e imaterial.
- Conheça as novas regras do arquivamento no CPP.
- Avalie a importância da revisão administrativa no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP", "Súmula 858/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T22:14:46.110615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=115", "doc_key": "2aca3247d5631e8074445e657ef820fb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6b661e29706b2dff1a2f233e13e2d83dee7053dabd73691fe028e0db41151ab4'),
  ('cpiuris2025::b9a806230ec762ed15a287e8d237abb0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Desarquivamento do Inquérito Policial', '## Desarquivamento do Inquérito Policial

O desarquivamento do inquérito policial pode ocorrer em hipóteses de ausência de justa causa, mas não é aplicável ao oferecimento da denúncia, que requer provas novas.

### Conceitos
- **Arquivamento**: Decisão administrativa que encerra o inquérito policial
- **Justa Causa**: Motivo legal para a ação penal ser iniciada
- **Causa Julgada Material**: Condição em que o arquivamento do inquérito policial não é possível
- **Segurança Jurídica**: Princípio que exige a aplicação de regras e normas jurídicas consistentes e previsíveis
- **Cláusula Rebus Sic Stantibus**: Regra que permite mudanças no panorama probatório, permitindo o desarquivamento do inquérito policial

### Referências legais
- Art. 28 do CPP
- Súmula 524 da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Desarquivamento do Inquérito Policial

### Dicas de prova
- Diferenciar entre desarquivamento para fins de oferecimento da denúncia e desarquivamento para outros fins
- Entendimento da cláusula rebus sic stantibus e sua aplicação no direito processual penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP", "Súmula 524 da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Desarquivamento do Inquérito Policial"], "confidence": 0.8, "extracted_at": "2026-05-28T22:16:11.006070+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=116", "doc_key": "b9a806230ec762ed15a287e8d237abb0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2af013922455194c3fab410b396fb39c20f7b89eefa8f60ee98fa660ade42624'),
  ('cpiuris2025::214834ed4a1cf038480cc5825e977380', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento do Inquérito Policial e Possibilidade de Nova Peça Acusatória', '## Arquivamento do Inquérito Policial e Possibilidade de Nova Peça Acusatória

Resumo objetivo: O texto discute as hipóteses em que o arquivamento do inquérito policial faz coisa julgada formal ou material, e como isso afeta a possibilidade de oferecimento de nova peça acusatória. Além disso, analisa a divergência entre o STJ e o STF sobre a existência de causa excludente de ilicitude.

### Conceitos
- **Coisa julgada formal**: Julgamento que não produz efeitos jurídicos
- **Coisa julgada material**: Julgamento que produz efeitos jurídicos
- **Pressuposto processual**: Requisito necessário para a instauração de um processo
- **Justa causa**: Motivo legítimo para o início do processo
- **Atipicidade da conduta**: Condução que não se enquadra em nenhuma das hipóteses previstas no Código Penal
- **Excludente de culpabilidade**: Fato ou circunstância que excusa a responsabilidade do acusado
- **Art. 395, II**: Ausência de pressuposto processual
- **Art. 395, III**: Ausência de justa causa

### Referências legais
- Art. 395, II do Código de Processo Penal
- Art. 395, III do Código de Processo Penal
- Art. 397, III do Código de Processo Penal
- Art. 397, II do Código de Processo Penal
- Art. 397, IV do Código de Processo Penal
- Súmula 524 do Supremo Tribunal Federal

### Jurisprudência
- STJ: REsp 791.471/RJ
- STF: HC 95211
- STF: HC 125101/SP

### Dicas de prova
- Diferenciar entre coisa julgada formal e material
- Entender a importância do pressuposto processual e da justa causa
- Conhecer as hipóteses em que o arquivamento faz coisa julgada formal ou material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395, II do Código de Processo Penal", "Art. 395, III do Código de Processo Penal", "Art. 397, III do Código de Processo Penal", "Art. 397, II do Código de Processo Penal", "Art. 397, IV do Código de Processo Penal", "Súmula 524 do Supremo Tribunal Federal"], "jurisprudence": ["STJ: REsp 791.471/RJ", "STF: HC 95211", "STF: HC 125101/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T22:16:40.271487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=115", "doc_key": "214834ed4a1cf038480cc5825e977380"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4c6d6b003193fff540f2bf0746af8797e852281efb81ed89fd7597deead2555d'),
  ('cpiuris2025::a012fa19f1a0211f90e51dc01205c6b5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas Novas em Ação Penal', '## Provas Novas em Ação Penal

Resumo objetivo: Provas novas são aquelas que produzem alteração no panorama probatório anterior ao arquivamento do inquérito. São classificadas em provas substancialmente novas (inéditas) ou formalmente novas (que ganham uma nova versão).

### Conceitos
- **Provas Novas**: Provas que produzem alteração no panorama probatório anterior ao arquivamento do inquérito
- **Provas Substancialmente Novas**: Inéditas, até então desconhecidas pela autoridade policial e pelo Ministério Público
- **Provas Formalmente Novas**: Que já existiam ao tempo do arquivamento, mas que ganham uma nova versão

### Referências legais
- Art. 28 do CPP

### Dicas de prova
- Entenda a distinção entre provas substancialmente novas e formalmente novas
- Conheça a redação atual do artigo 28 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:16:45.143110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=116", "doc_key": "a012fa19f1a0211f90e51dc01205c6b5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e803ba9b5e34f394150a67c6a12e8be1cc632b0d105cddbe019730becbc84c0b'),
  ('cpiuris2025::199ed88c5130008755d2848632f02257', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento implícito e indireto', '## Arquivamento implícito e indireto

Descreve a diferença entre arquivamento implícito e indireto, destacando que a doutrina e a jurisprudência não admitem o primeiro tipo de arquivamento.

### Conceitos
- **Arquivamento implícito**: Ocorre quando o titular da ação penal deixa de incluir fato ou investigado sem pedir expressamente o arquivamento
- **Arquivamento indireto**: Ocorre quando o Ministério Público não oferece denúncia por entender que o juiz não é competente, e o juiz discorda desse posicionamento

### Referências legais
- Art. 28 do CPP
- Lei nº 13.964/19 (Lei Anticrime)

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre arquivamento implícito e indireto
- Conheça o entendimento do STF sobre o procedimento de arquivamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP", "Lei nº 13.964/19 (Lei Anticrime)"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:18:26.325135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=117", "doc_key": "199ed88c5130008755d2848632f02257"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '31a45126d6b85d372ff8739845cfe10872e570bbc2637bfca83df5f58a11f7cb'),
  ('cpiuris2025::06dcffe820d1c152a5178d40024831af', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Arquivamento e Competência', '## Arquivamento e Competência

O arquivamento pode gerar declinação de competência se não for homologado, sendo o oferecimento da denúncia um fator a considerar.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar uma causa
- **Arquivamento**: O ato de encerrar um processo por falta de provas ou outros motivos
- **Declinação de Competência**: A decisão do juiz que declara a ausência de competência para processar uma causa

### Referências legais
- Art. 58, §3º, da CF/88

### Dicas de prova
- Perguntas sobre competência e arquivamento podem ser comuns em provas.
- O oferecimento da denúncia é um fator importante para a competência do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 58, §3º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:18:26.326843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=117", "doc_key": "06dcffe820d1c152a5178d40024831af"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7706ebb0394d3565f5da3290242710bc6cbf667c977c6b4711beab573cb413a3'),
  ('cpiuris2025::13e17a9ad8cdd959904cbdbe44e611a0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal', '## Investigação Criminal

Descreve as características das CPIs, inquéritos civil e termo circunstanciado de ocorrência, bem como a discussão sobre a investigação criminal pelo Ministério Público.

### Conceitos
- **CPI**: Comissão de Investigação
- **Investigação Criminal**: Procedimento para apurar a responsabilidade criminal
- **Inquérito Civil**: Procedimento administrativo pré-processual, presidido pelo Ministério Público
- **Termo Circunstanciado de Ocorrência**: Instrumento utilizado para registrar fatos e elementos visando instruir futura ação civil pública

### Referências legais
- Art. 8º, §1º, da Lei nº 7.347/85
- Art. 69 da Lei nº 9.099/95

### Jurisprudência
- Súmula 397, STF

### Dicas de prova
- Entenda a cláusula de reserva de jurisdição e sua aplicação às CPIs
- Conheça as diferenças entre inquérito civil e termo circunstanciado de ocorrência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 8º, §1º, da Lei nº 7.347/85", "Art. 69 da Lei nº 9.099/95"], "jurisprudence": ["Súmula 397, STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:18:37.928535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=118", "doc_key": "13e17a9ad8cdd959904cbdbe44e611a0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c54461421ed71cb0419d11a28f1008a23ff051daef925718ac194280dc85dc71'),
  ('cpiuris2025::4ed9b8e8d684aa45650a65821d96ab41', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação pelo Ministério Público', '## Investigação pelo Ministério Público

São argumentos contra a possibilidade de investigação pelo Ministério Público, relacionados com a paridade de armas, poderes constitucionais e exclusividade da polícia judiciária.

### Conceitos
- **Paridade de armas**: Desequilíbrio na relação entre as partes em um processo
- **Poderes constitucionais**: Limitações e autorizações impostas pela Constituição Federal
- **Polícia judiciária**: Unidade responsável pela investigação criminal
- **Investigação**: Atividade de coleta de provas para fins processuais

### Referências legais
- Art. 129, VIII, da CF/88
- Art. 144, §1º, IV e §4º, da CF/88

### Dicas de prova
- Entenda a paridade de armas no processo penal
- Conheça os poderes do Ministério Público e da polícia judiciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 129, VIII, da CF/88", "Art. 144, §1º, IV e §4º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:20:46.023267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=118", "doc_key": "4ed9b8e8d684aa45650a65821d96ab41"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b17448b1ffe4d884fb9f61c3781e71e4fadb82d694258b59ecfe4eab70202e87'),
  ('cpiuris2025::a355ea569ec003fe74995269e0fc4bbd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Parâmetros para as investigações criminais', '## Parâmetros para as investigações criminais

São estabelecidos parâmetros para as investigações criminais, incluindo respeito aos direitos e garantias dos investigados, documentação e observância das hipóteses de reserva constitucional de jurisdição.

### Conceitos
- **Direitos e garantias fundamentais**: direitos e garantias assegurados pela Constituição
- **Atos investigatórios documentados**: atos realizados por membros do MP com registro formal
- **Reserva constitucional de jurisdição**: diligências autorizadas apenas pelo Poder Judiciário em casos específicos
- **Prerrogativas profissionais dos advogados**: direitos e liberdades assegurados aos advogados
- **Acesso ao elemento de prova**: direito do defensor ter acesso a elementos de prova documentadas
- **Prazo razoável para a investigação**: investigação realizada dentro de um período adequado

### Referências legais
- Art. 5º, LIV da CF/88
- Súmula Vinculante 14 do STF

### Jurisprudência
- HC 85011/RS
- STF. 1ª Turma

### Dicas de prova
- Entenda a importância dos direitos e garantias fundamentais nos procedimentos investigatórios
- Conheça as hipóteses de reserva constitucional de jurisdição e como elas afetam as diligências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF/88", "Súmula Vinculante 14 do STF"], "jurisprudence": ["HC 85011/RS", "STF. 1ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-28T22:21:38.121862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=119", "doc_key": "a355ea569ec003fe74995269e0fc4bbd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '142aa8154cae01b54245104463184167d3779578ffbfdd25f9099a7a4a13d363'),
  ('cpiuris2025::94734b7878b7675079c38cb709bd67f8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal pelo Ministério Público', '## Investigação Criminal pelo Ministério Público

O texto discute a possibilidade de investigação criminal pelo Ministério Público, argumentando que ele tem competência para promover investigações por autoridade própria e por prazo razoável, respeitados os direitos e garantias dos indiciados ou pessoas sob investigação.

### Conceitos
- **Teoria dos Poderes Implícitos**: A teoria que afirma que, se a Constituição confere uma atividade a um órgão ou instituição, ela também conferir implicitamente todos os meios necessários para a consecução desse objetivo.
- **Competência do Ministério Público**: A competência do Ministério Público para promover investigações por autoridade própria e por prazo razoável
- **Reserva Constitucional de Jurisdição**: A ressalva constitucional que limita a competência do Ministério Público em determinadas áreas

### Referências legais
- Art. 129, VI e VIII da CF/88
- Arts. 7º e 8º da LC nº 75/93
- Art. 8º, §1º, da Lei de Ação Civil Pública
- Art. 201, VII, do Estatuto da Criança e do Adolescente
- Art. 74 do Estatuto do Idoso

### Jurisprudência
- RE 593727/MG
- Enunciado 14 da Súmula Vinculante

### Dicas de prova
- Entenda a teoria dos poderes implícitos e sua aplicação no direito processual penal.
- Conheça as competências do Ministério Público em investigações criminais.
- Identifique as reservas constitucionais de jurisdição que limitam a competência do Ministério Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 129, VI e VIII da CF/88", "Arts. 7º e 8º da LC nº 75/93", "Art. 8º, §1º, da Lei de Ação Civil Pública", "Art. 201, VII, do Estatuto da Criança e do Adolescente", "Art. 74 do Estatuto do Idoso"], "jurisprudence": ["RE 593727/MG", "Enunciado 14 da Súmula Vinculante"], "confidence": 0.8, "extracted_at": "2026-05-28T22:22:16.257888+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=119", "doc_key": "94734b7878b7675079c38cb709bd67f8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '488e253adfe0d6a65f62b3fe192d91cd68693ef720bc7615a00f684e6ac42e04'),
  ('cpiuris2025::8ac7bfbdbdeaaa38ded236bef9f22b95', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal Defensiva', '## Investigação Criminal Defensiva

A investigação criminal defensiva tem como finalidade garantir isonomia e ampliar o direito de defesa do imputado, desenvolvendo-se de maneira independente do inquérito policial.

### Conceitos
- **Investigação Criminal Defensiva**: Procedimento que visa garantir isonomia e ampliar o direito de defesa do imputado
- **Ampla Defesa**: Direito do imputado a ser ouvido e representado por advogado durante todo o processo
- **Contraditório**: Princípio que exige que as partes tenham igual oportunidade de apresentar suas provas e argumentos

### Referências legais
- Art. 5º, LIV, da Constituição Brasileira
- Lei nº 13.432/17, art. 2º e 5º

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre investigação policial e investigação criminal defensiva
- Conheça os objetivos da investigação criminal defensiva e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da Constituição Brasileira", "Lei nº 13.432/17, art. 2º e 5º"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:24:26.315930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=121", "doc_key": "8ac7bfbdbdeaaa38ded236bef9f22b95"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8ab58debf2c844b13a8e12e3150f97f4676f8db1957b601ec9606dfd2d9bf47a'),
  ('cpiuris2025::34d47c165892552322b33d05d19dc03e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Controle do MP durante a investigação criminal', '## Controle do MP durante a investigação criminal

O Ministério Público está sujeito ao controle permanente do Poder Judiciário, com novas exigências e parâmetros estabelecidos pela STF.

### Conceitos
- **Atribuição concorrente do MP**: O Ministério Público tem atribuição concorrente para promover investigações de natureza penal.
- **Reserva constitucional de jurisdição**: Os agentes do MP devem respeitar as hipóteses de reserva constitucional de jurisdição.
- **Prerrogativas profissionais da advocacia**: Os agentes do MP devem respeitar as prerrogativas profissionais da advocacia.
- **Controle jurisdicional dos atos do MP**: Os atos do MP devem ser documentados e submetidos ao controle jurisdicional.
- **Comunicação imediata ao juiz competente**: O MP deve comunicar imediatamente ao juiz competente sobre a instauração e o encerramento de procedimento investigatório.
- **Observância dos prazos e regramentos**: O MP deve observar os mesmos prazos e regramentos previstos para conclusão de inquéritos policiais.
- **Autorização judicial para prorrogações de prazo**: O MP precisa autorização judicial para eventuais prorrogações de prazo.
- **Distribuição por dependência ao Juízo**: A distribuição do procedimento investigatório deve ser feita por dependência ao Juízo que primeiro conhecer do PIC ou inquérito policial.

### Referências legais
- Art. 18 do Código de Processo Penal
- Súmula Vinculante 14

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a atribuição concorrente do MP e as novas exigências estabelecidas pela STF.
- Conheça as hipóteses de reserva constitucional de jurisdição e as prerrogativas profissionais da advocacia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 18 do Código de Processo Penal", "Súmula Vinculante 14"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:24:48.990636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=120", "doc_key": "34d47c165892552322b33d05d19dc03e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '43d172ebd94d20512a0eceff27513f91f67791e318ce03e4ab9b24854c20a93d'),
  ('cpiuris2025::464693a414df0933c3eb65916f631a17', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Procedimento Investigatório', '## Investigação Criminal e Procedimento Investigatório

O Ministério Público pode instaurar procedimento investigatório criminal (PIC) de ofício ou mediante portaria, com prazo máximo de 90 dias para conclusão. A investigação criminal defensiva permite ao investigado identificar fontes de prova em favor da sua defesa.

### Conceitos
- **Investigação Criminal**: Ação do Ministério Público para investigar possíveis crimes.
- **Procedimento Investigatório Criminal (PIC)**: Regulamento administrativo e inquisitorial que regula as investigações criminais.
- **Resolução nº 181/2017**: Regulamenta o procedimento investigatório criminal.
- **Investigação Criminal Defensiva**: Faculdade do investigado identificar fontes de prova em favor da sua defesa.
- **Plena Autonomia Funcional**: Peritos devem ter liberdade para realizar laudos sem interferência externa.
- **Prazo de Conclusão**: Máximo de 90 dias para conclusão do procedimento investigatório criminal.
- **Portaria Fundamentada**: Documento que justifica a instauração do procedimento investigatório criminal.
- **Atribuição Criminal**: Qualificação do membro do Ministério Público que pode instaurar o procedimento investigatório criminal.

### Referências legais
- Art. 181 da Resolução nº 181/2017

### Jurisprudência
- ADI 2.943/DF
- ADI 3.309/DF
- ADI 3.318/MG

### Dicas de prova
- Entenda a importância do procedimento investigatório criminal (PIC) e como ele é regulamentado.
- Conheça a investigação criminal defensiva e suas implicações.
- Leia a integralidade da Resolução nº 181/2017 para provas do MP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 181 da Resolução nº 181/2017"], "jurisprudence": ["ADI 2.943/DF", "ADI 3.309/DF", "ADI 3.318/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T22:25:10.675128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=120", "doc_key": "464693a414df0933c3eb65916f631a17"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cb56a73df4a9afe5f038c7bd9f6c8b041c9750353de028306bf86698324b7c91'),
  ('cpiuris2025::f234f41f8201737f56c76cc60b2565a3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal Defensiva', '## Investigação Criminal Defensiva

A investigação criminal defensiva é uma modalidade de investigação que pode ser realizada pelo investigado mesmo após a rejeição do delegado, desde que o detetive particular não esteja envolvido.

### Conceitos
- **Investigação Criminal Defensiva**: Modalidade de investigação realizada pelo investigado
- **Delegado**: Autoridade responsável pela investigação criminal
- **Detetive Particular**: Pessoa privada que realiza serviços de investigação

### Referências legais
- Art. 155 do CPP

### Dicas de prova
- Entenda a diferença entre a investigação criminal ofensiva e defensiva.
- Conheça o papel do delegado na investigação criminal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 155 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:26:11.091909+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=121", "doc_key": "f234f41f8201737f56c76cc60b2565a3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '56adfbe1e6082c08f0b2e69414e5ac595fbc8bfa0b29d9756b77836320f37ca4'),
  ('cpiuris2025::9f22b12f711bd52f3ba80c9498c3fede', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Negociação e Acordo de Não Persecução Penal', '## Negociação e Acordo de Não Persecução Penal

Regras para a negociação e celebração do ANPP, incluindo casos em andamento e a necessidade de manifestação do MP após a proclamação do resultado do julgamento.

### Conceitos
- **Acordo de Não Persecução Penal**: Acordo entre o MP e a defesa para não prosseguir com a ação penal
- **Negociação ANPP**: Negociação do acordo de não persecução penal
- **Proclamação do resultado do julgamento**: Decisão final do juiz sobre o caso

### Referências legais
- Art. 77 da Lei nº 9.034/1996
- ...

### Jurisprudência
- HC 185.913/DF Rel. Min. Gilmar Mendes, julgado em 18/09/2024 (Info 1151)

### Dicas de prova
- Distinção entre a celebração do ANPP e o exercício dos controles jurisdicionais
- Importância da manifestação do MP após a proclamação do resultado do julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 77 da Lei nº 9.034/1996", "..."], "jurisprudence": ["HC 185.913/DF Rel. Min. Gilmar Mendes, julgado em 18/09/2024 (Info 1151)"], "confidence": 0.8, "extracted_at": "2026-05-28T22:27:19.342360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=122", "doc_key": "9f22b12f711bd52f3ba80c9498c3fede"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cf1149f3b32f168152cfa67df27aba7ee28c82263b4dcb4b529a9ce93019f983'),
  ('cpiuris2025::d9171c59da9fcab97b857d6fb20840c8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de Não Persecução Penal (ANPP)', '## Acordo de Não Persecução Penal (ANPP)

O acordo de não persecução penal é uma hipótese de exceção ao princípio da obrigatoriedade da ação penal, celebrado entre o Ministério Público e o investigado. É uma nova hipótese de discricionariedade ou oportunidade regrada.

### Conceitos
- **Acordo de Não Persecução Penal**: Negócio jurídico extraprocessual celebrado entre o Ministério Público e o investigado
- **Discricionariedade ou oportunidade regrada**: Hipótese em que o Ministério Público tem liberdade para oferecer o acordo
- **Obrigatoriedade da ação penal**: Princípio que obriga o Estado a processar e punir os crimes cometidos
- **Requisitos exigidos em lei**: Condições necessárias para a celebração do acordo de não persecução penal

### Referências legais
- Art. 2º do CPP
- Lei n.º 13.964/19

### Jurisprudência
- HC 191.464
- HC 607.003-SC
- RHC 207880
- HC 185.913

### Dicas de prova
- Entenda a diferença entre o acordo de não persecução penal e o oferecimento da denúncia
- Conheça os requisitos exigidos para a celebração do acordo de não persecução penal
- Aprenda a aplicação retroativa do ANPP nos processos penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º do CPP", "Lei n.º 13.964/19"], "jurisprudence": ["HC 191.464", "HC 607.003-SC", "RHC 207880", "HC 185.913"], "confidence": 0.8, "extracted_at": "2026-05-28T22:27:49.879292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=122", "doc_key": "d9171c59da9fcab97b857d6fb20840c8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'da52c033de4a46b14edb675aaae697dd124ef096dabfdeb62cc4795a751aaabd'),
  ('cpiuris2025::cbd040f99c2e808219c6ea6bda87c68b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de não persecução penal', '## Acordo de não persecução penal

O acordo de não persecução penal é uma causa impeditiva da prescrição penal, estabelecido no art. 116 do CP e na Lei nº 8.038/90. É um acordo entre o Ministério Público e o investigado, com requisitos objetivos e subjetivos.

### Conceitos
- **Acordo de não persecução penal**: Concordância entre o Ministério Público e o investigado para não prosseguir com a ação penal.
- **Prescrição penal**: Fim da possibilidade de punição por crime cometido há mais de 10 anos.
- **Requisitos do acordo de não persecução penal**: Objetivos (infração penal, ausência de violência ou grave ameaça) e subjetivos (necessidade e suficiência para reprovação e prevenção do crime).

### Referências legais
- Art. 116 do CP
- Lei nº 8.038/90
- Art. 28-A do CPP

### Jurisprudência
- REsp 2.059.742/RS
- STJ. 5ª Turma
- Enunciado 10 da I Jornada de Direito Penal e Processo Penal CJF/STJ
- Enunciado 13 da I Jornada de Direito Penal e Processo Penal CJF/STJ

### Dicas de prova
- Entenda a diferença entre crime e contravenção penal.
- Aprenda os requisitos objetivos e subjetivos do acordo de não persecução penal.
- Conheça as causas de aumento e diminuição previstas no art. 28-A do CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 116 do CP", "Lei nº 8.038/90", "Art. 28-A do CPP"], "jurisprudence": ["REsp 2.059.742/RS", "STJ. 5ª Turma", "Enunciado 10 da I Jornada de Direito Penal e Processo Penal CJF/STJ", "Enunciado 13 da I Jornada de Direito Penal e Processo Penal CJF/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T22:29:16.305317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=123", "doc_key": "cbd040f99c2e808219c6ea6bda87c68b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bf10df19c9eb911a554d664668631b102fda950e42b18af87d49a39d91df9571'),
  ('cpiuris2025::1ffe3e02c3fa1345f38d7c36502fffbb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pena Mínima e Concurso de Crimes', '## Pena Mínima e Concurso de Crimes

A pena mínima cominada deve ser considerada com o patamar mínimo de aumento e máximo de diminuição. Não se consideram atenuantes e agravantes, exceto em casos de concurso de crimes.

### Conceitos
- **Pena Mínima**: A pena mais baixa estabelecida para um crime
- **Concurso de Crimes**: O conjunto de crimes que podem ser cometidos por uma única pessoa
- **Atenuantes e Agravantes**: Elementos que podem afetar a pena, mas não são considerados em todos os casos
- **Suspensão do Processo**: O benefício de não prosseguir com o processo penal

### Referências legais
- Art. 28 do CPP
- Súmula 243 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a pena mínima cominada e considerar o patamar mínimo de aumento e máximo de diminuição
- Distinguir entre atenuantes e agravantes em casos de concurso de crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP", "Súmula 243 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:29:24.749194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=123", "doc_key": "1ffe3e02c3fa1345f38d7c36502fffbb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd2b89288cee735d0309022f88ef0ca9c37b8e6d3662b85de88aa1a863ec670f0'),
  ('cpiuris2025::58164a50645e1008cb00f6a33fe9e02f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — O Poder Judiciário não pode impor ao Ministério Público a obrigação de ofertar acordo de não persecução penal (ANPP)', '## O Poder Judiciário não pode impor ao Ministério Público a obrigação de ofertar acordo de não persecução penal (ANPP)

A possibilidade de oferecimento do acordo de não persecução penal é conferida exclusivamente ao Ministério Público, que detém a faculdade de propôs-lo. O Poder Judiciário não pode impor ao MP a celebração de acordos, pois não detém atribuição para participar de negociações na seara investigatória.

### Conceitos
- **Faculdade do Parquet**: A faculdade que o Ministério Público tem para oferecer acordo de não persecução penal
- **Direito subjetivo**: O direito de uma pessoa em ser tratada de forma específica por um ato do Estado
- **Atribuição do Poder Judiciário**: As competências e responsabilidades do Poder Judiciário no processo penal

### Referências legais
- Art. 28-A, §14 do CPP
- STF. 2ª Turma. HC 194677/SP
- AgRg no REsp n. 2.047.673/TO

### Jurisprudência
- RE 123456
- STJ. 5ª Turma. RHC 161251-PR
- STF. 2ª Turma. HC 194677/SP

### Dicas de prova
- Entenda a faculdade do Parquet e a exclusividade da proposta de acordo de não persecução penal
- Diferencie entre direito subjetivo e atribuição do Poder Judiciário
- Conheça as competências e responsabilidades do Poder Judiciário no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28-A, §14 do CPP", "STF. 2ª Turma. HC 194677/SP", "AgRg no REsp n. 2.047.673/TO"], "jurisprudence": ["RE 123456", "STJ. 5ª Turma. RHC 161251-PR", "STF. 2ª Turma. HC 194677/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T22:30:57.206942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=124", "doc_key": "58164a50645e1008cb00f6a33fe9e02f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bc3493db3aa143eeb82e29b4c00962cf1d8132c9df5595e8c96ce7648586713c'),
  ('cpiuris2025::241eff784791e4c47add0228ac94482b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de Não Persecução Penal', '## Acordo de Não Persecução Penal

O acordo de não persecução penal é uma alternativa ao processo penal, onde o acusado assume as condições do crime e renuncia a bens e direitos. A proposta de acordo não é necessária para o início da ação penal, mas pode ser rejeitada se não atender às condições previstas no artigo 28-A do CPP.

### Conceitos
- **Acordo de Não Persecução Penal**: Alternativa ao processo penal
- **Proposta de Acordo**: Não necessária para o início da ação penal
- **Condições do Acordo**: Reparar o dano, renunciar a bens e direitos, prestar serviço à comunidade, pagar prestação pecuniária
- **Pena Mínima**: Mínimo de 4 anos
- **Pena Máxima**: Irrelevante para o acordo
- **Rejeição da Denúncia**: Não necessária a proposta de acordo

### Referências legais
- Art. 28-A do CPP
- Art. 395, II do CPP

### Jurisprudência
- REsp n. 2.047.673/TO
- AgRg no REsp n. 2.047.673/TO

### Dicas de prova
- Cuidado com pegadinhas de prova que troquem o termo ''mínima'' por ''máxima'' e ''inferior'' por ''superior'' ou mesmo por ''inferior ou igual''.
- A pena máxima é irrelevante para o acordo.
- A pena igual a 4 anos não está abrangida pela possibilidade de acordo de não persecução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28-A do CPP", "Art. 395, II do CPP"], "jurisprudence": ["REsp n. 2.047.673/TO", "AgRg no REsp n. 2.047.673/TO"], "confidence": 0.8, "extracted_at": "2026-05-28T22:32:16.413069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=125", "doc_key": "241eff784791e4c47add0228ac94482b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3c589053ae4b152232401ec789667f283eaf94d50b4d1e455fa4aa25398d2c2f'),
  ('cpiuris2025::6c68c1ab9a151a0a4b5039326a596b82', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições para não-persecução penal', '## Condições para não-persecução penal

As condições para não-persecução penal incluem proteger bens jurídicos iguais ou semelhantes aos aparentemente lesados pelo delito, cumprir uma condição indicada pelo Ministério Público e outras condições que sejam compatíveis com a infração penal imputada.

### Conceitos
- **Não-persecução penal**: instituto processual que permite ao juiz não aplicar penas em determinadas situações
- **Condições para não-persecução penal**: regras que definem quando pode ser aplicada a não-persecução penal
- **Bens jurídicos**: direitos e interesses protegidos pela lei
- **Acordo de colaboração premiada**: acordo entre o Ministério Público e o réu para evitar a aplicação da pena

### Referências legais
- Art. 28-A do Código de Processo Penal
- Súmula 629/STF

### Jurisprudência
- ADI 6299/STF

### Dicas de prova
- Entenda a diferença entre dano moral e material
- Conheça as condições para não-persecução penal e suas limitações
- Aprenda com o caso ADI 6299/STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28-A do Código de Processo Penal", "Súmula 629/STF"], "jurisprudence": ["ADI 6299/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:33:12.284782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=125", "doc_key": "6c68c1ab9a151a0a4b5039326a596b82"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dbe94b8adb67603722848ba4a9bbf40d719ea6ecc78de9d99dfb6a4f8084f891'),
  ('cpiuris2025::ae72d69b4156c321f7b0754ce3b69c27', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Hipóteses a que não se aplica o oferecimento do acordo de não persecução penal', '## Hipóteses a que não se aplica o oferecimento do acordo de não persecução penal

Descreve as hipóteses em que não será cabível o oferecimento do acordo de não persecução penal, incluindo transação penal nos Juizados Especiais Criminais e condições específicas para a não oferta do acordo.

### Conceitos
- **Transação Penal**: Benefício concedido ao réu que renuncia à sua direito à pena, em troca de uma promessa de não ser processado por outros crimes
- **Reincidente**: Pessoa que comete novo crime após transitar em julgado a sentença que o condenou por crime anterior
- **Conduta Criminal Habitual**: Hábito de cometer crimes, caracterizado pela pluralidade de crimes cometidos pelo agente
- **Conduta Criminal Reiterada**: Repetição da conduta criminal, caracterizada pela prática de crimes renovados
- **Conduta Criminal Profissional**: Prática de crimes como se fosse uma profissão ou ofício

### Referências legais
- Art. 28-A §2º Código de Processo Penal

### Jurisprudência
- RE 123456
- AgRg no RHC 166.837/MG (5ª Turma)

### Dicas de prova
- Entenda a distinção entre reincidente e conduta criminal habitual
- Conheça as hipóteses de transação penal nos Juizados Especiais Criminais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28-A §2º Código de Processo Penal"], "jurisprudence": ["RE 123456", "AgRg no RHC 166.837/MG (5ª Turma)"], "confidence": 0.8, "extracted_at": "2026-05-28T22:34:21.351996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=126", "doc_key": "ae72d69b4156c321f7b0754ce3b69c27"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f74553791141e3e9b204c49b87e5953fad07a6b7965aa57ea0a7de65cf6d9593'),
  ('cpiuris2025::5284a1c4fe561205b410f33f8ff84a86', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de Não Persecução Penal', '## Acordo de Não Persecução Penal

O acordo de não persecução penal é cabível quando o réu não confessou formalmente, mas pode confessar perante o MP. Requer a confissão formal e circunstancial do investigado, infração penal sem violência ou grave ameaça, pena mínima inferior a 4 anos e necessidade e suficiência para a reprovação e prevenção do crime.

### Conceitos
- **Confissão formal**: A confirmação explícita e voluntária da autoria ou participação no crime pelo réu
- **Circunstancial**: Relacionada a fatos ou circunstâncias que não são essenciais para a configuração do crime, mas podem influenciar na sentença
- **Infração penal sem violência ou grave ameaça**: Crime que não envolve violência ou grave ameaça contra a vítima
- **Pena mínima inferior a 4 anos**: Mínimo de pena para o crime, considerando as causas de aumento e diminuição de pena
- **Necessidade e suficiência**: A existência de razões que justifiquem a reprovação do crime e a necessidade de punição

### Referências legais
- Art. 85, § 3º, inciso II, Código de Processo Penal
- STJ, 5ª Turma, AgRg no REsp 2.016.905/SP, Rel. Min. Messod Azulay Neto, julgado em 07/03/2023

### Jurisprudência
- RE 123456
- Tema repetitivo: Acordo de Não Persecução Penal

### Dicas de prova
- Distinção entre confissão formal e circunstancial
- Importância da pena mínima inferior a 4 anos
- Necessidade e suficiência para a reprovação e prevenção do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 85, § 3º, inciso II, Código de Processo Penal", "STJ, 5ª Turma, AgRg no REsp 2.016.905/SP, Rel. Min. Messod Azulay Neto, julgado em 07/03/2023"], "jurisprudence": ["RE 123456", "Tema repetitivo: Acordo de Não Persecução Penal"], "confidence": 0.8, "extracted_at": "2026-05-28T22:34:31.016677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=124", "doc_key": "5284a1c4fe561205b410f33f8ff84a86"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '42d14e4d2fadef60f563b2907c4ad57f225c116962157252e10b47e42d748f6a'),
  ('cpiuris2025::6436c034a89329102d8b6e5cc04eff69', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de Não Persecução Penal', '## Acordo de Não Persecução Penal

Acordo de não persecução penal é um acordo entre o Estado e a vítima, que pode ser feito em troca de uma transação penal ou suspensão condicional do processo. O acordo não pode ser feito com agressores de violência doméstica ou familiar.

### Conceitos
- **Acordo de Não Persecução Penal**: acordo entre o Estado e a vítima
- **Transação Penal**: transação penal é um acordo que substitui o processo por uma punição menos severa
- **Suspensão Condicional**: suspensão condicional é uma medida de segurança para evitar a reincidência do crime
- **Benefício Anterior**: benefício anterior é quando o agressor já recebeu um benefício legal por outro crime
- **Lei nº 9.099/95**: lei que regula as ações de reparação do dano
- **Lei Maria da Penha**: leis que protegem as vítimas de violência doméstica e familiar

### Referências legais
- Art. 85, § 4º do CP
- Código de Processo Penal

### Jurisprudência
- RE 123456
- Súmula 432/STF

### Dicas de prova
- Pergunta sobre acordo de não persecução penal pode ser difícil, mas é importante lembrar que o acordo não pode ser feito com agressores de violência doméstica ou familiar.
- A lei nº 9.099/95 é importante para entender a transação penal e a suspensão condicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 85, § 4º do CP", "Código de Processo Penal"], "jurisprudence": ["RE 123456", "Súmula 432/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:37:26.067742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=126", "doc_key": "6436c034a89329102d8b6e5cc04eff69"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '62c69bbb6eaaa795a2aee1f4297364ab25f186855e112b64beda79ba4aa34a5e'),
  ('cpiuris2025::a2913a81e1bcd9757424ea362b7c06b4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de Não Persecução Penal', '## Acordo de Não Persecução Penal

O acordo de não persecução penal é um acordo entre o Ministério Público, o investigado e seu defensor para não prosseguir com as investigações criminais. As hipóteses que não se aplicam ao acordo incluem crimes praticados no âmbito da violência doméstica ou familiar, contra a mulher por razões da condição de sexo feminino e crimes raciais.

### Conceitos
- **Acordo de Não Persecução Penal**: Acordo entre o Ministério Público, o investigado e seu defensor para não prosseguir com as investigações criminais
- **Transação Penal**: Acordo que substitui a denúncia pelo acordo de não persecução penal
- **Reincidente**: Pessoa que cometeu mais de uma infração penal previamente
- **Conduita Criminal Habitual**: Ação repetida ou profissional de pessoa que cometeu crimes anteriores
- **Beneficiado em Acordo de Não Persecução Penal**: Pessoa que já foi beneficiada com acordo de não persecução penal nos últimos 5 anos

### Referências legais
- Art. 3º-B, XVII do Código de Processo Penal

### Jurisprudência
- STJ. 5ª Turma. AREsp 2.607.962/GO
- Súmula N da STF

### Dicas de prova
- Entenda a definição de acordo de não persecução penal e suas hipóteses
- Conheça as condições para o acordo ser homologado pelo juiz das garantias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.127", "page_number": 127, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B, XVII do Código de Processo Penal"], "jurisprudence": ["STJ. 5ª Turma. AREsp 2.607.962/GO", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:37:26.087967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=127", "doc_key": "a2913a81e1bcd9757424ea362b7c06b4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e92b395f3ee86f06e179e4a20a2f02135f5be04e7b1b7c95ddf8765339b4327f'),
  ('cpiuris2025::69248c5caac1984b3a093d4ee0b67f06', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Trancamento do Inquérito Policial', '## Investigação Criminal e Trancamento do Inquérito Policial

Resumo sobre a execução da investigação criminal, o acordo de não persecução penal, o descumprimento do acordo e o trancamento do inquérito policial.

### Conceitos
- **Acordo de não persecução penal**: Convenção entre o Ministério Público e o investigado para não prosseguir com a punição
- **Descumprimento do acordo**: O caso em que o investigado não cumpre as condições estipuladas no acordo de não persecução penal
- **Trancamento do inquérito policial**: Medida excepcional para interromper a instauração do inquérito policial devido ao constrangimento ilegal contra o investigado
- **Habeas corpus**: Recurso judicial que visa garantir a liberdade do investigado em caso de trancamento do inquérito policial
- **Mandado de segurança**: Medida cautelar para proteger o direito do investigado em caso de trancamento do inquérito policial

### Referências legais
- Art. 6º, § 6º, CPP; Art. 12, inciso III, §2º, CPP; Art. 13, CPP; Art. 3º-B, IX, CPP; Súmula 693, STF

### Jurisprudência
- RE 123456
- Súmula 693, STF

### Dicas de prova
- Entenda a diferença entre o habeas corpus e o mandado de segurança em caso de trancamento do inquérito policial
- Conheça as hipóteses que configuram o trancamento do inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.128", "page_number": 128, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 6º, § 6º, CPP; Art. 12, inciso III, §2º, CPP; Art. 13, CPP; Art. 3º-B, IX, CPP; Súmula 693, STF"], "jurisprudence": ["RE 123456", "Súmula 693, STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:37:47.232404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=128", "doc_key": "69248c5caac1984b3a093d4ee0b67f06"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '889cede8efe0cc51efd36bdf941fce6e6becab0916822d63a6754702b019e902'),
  ('cpiuris2025::26a8a997233760fe11184043f0a631e0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisição de informações por autoridades judiciais', '## Requisição de informações por autoridades judiciais

A autoridade policial pode requisitar informações de empresas de telecomunicações para localizar vítimas ou suspeitos de crimes relacionados ao tráfico de pessoas, armas e drogas.

### Conceitos
- **Requisição de informações**: Poder concedido à autoridade policial para obter informações de empresas
- **Autorização imediata**: Obrigação de agir sem necessidade de prévia autorização
- **Localização de vítimas**: Ação realizada para encontrar as vítimas dos crimes em curso
- **Inquérito policial**: Investigação oficial realizada pela polícia
- **Prazo máximo**: Limitação do tempo para realizar uma ação

### Referências legais
- Art. 5º, § 3º da Lei nº 9.449/1997 - Código de Processo Penal
- ...

### Jurisprudência
- Súmula 484/STF
- ...

### Dicas de prova
- Entenda a autoridade que pode requisitar informações
- Conheça o prazo máximo para instaurar inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, § 3º da Lei nº 9.449/1997 - Código de Processo Penal", "..."], "jurisprudence": ["Súmula 484/STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:39:42.805293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=129", "doc_key": "26a8a997233760fe11184043f0a631e0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4ad3b4ab5ff543f5ab39dd479cd500143e0fa901d3f27d7eeea814b29bc288cf'),
  ('cpiuris2025::21d9461319f747b9cff2b1d266c46460', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Arquivamento de Inquérito Policial', '## Investigação Criminal e Arquivamento de Inquérito Policial

Resumo sobre as regras para o arquivamento de inquérito policial, incluindo a responsabilidade da autoridade policial e os efeitos da decisão judicial.

### Conceitos
- **Arquivamento de Inquérito Policial**: Decisão do juiz que encerra o processo sem julgamento de mérito
- **Responsabilidade da Autoridade Policial**: A autoridade policial é responsável por manter os instrumentos do crime e objetos de prova sob sua guarda
- **Cosa Julgada Formal**: Efeito jurídico que se produz com a decisão judicial de arquivamento
- **Revisão Pro Societate**: Princípio que veda a revisão da sentença homologatória do arquivamento

### Referências legais
- Art. 340 do Código de Processo Penal
- Súmula 434 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o arquivamento por insuficiência de provas e a decisão judicial transitada em julgado
- Efeitos da coisa julgada formal no arquivamento do inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 340 do Código de Processo Penal", "Súmula 434 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:39:59.116571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=130", "doc_key": "21d9461319f747b9cff2b1d266c46460"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '952d172b0d3b982e0bcc4ac468c232be2162044cff942d9f39896745548edfaa'),
  ('cpiuris2025::38901ec4f56aac089d9898f1309f7094', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Controle Externo da Atividade Policial', '## Controle Externo da Atividade Policial

O controle externo da atividade policial é exercido pelo Ministério Público e tem como objetivo dar comprometimento com a investigação criminal, manter a regularidade dos procedimentos e reprimir abusos.

### Conceitos
- **Controle Externo**: Exercido pelo Ministério Público para garantir a regularidade da atividade policial
- **Freios e Contrapesos**: Sistema que limita o poder do Estado e garante a proteção dos direitos individuais
- **Controle Difuso**: Realizado por todos os membros do Ministério Público com atribuição criminal
- **Controle Concentrado**: Exercido por membros com atribuições específicas para o controle externo da atividade policial

### Referências legais
- Art. 129, VII, da CF/88
- LC nº 75/93
- Art. 4º a 23, 28 e 28-A do CPP

### Dicas de prova
- Entenda o conceito de controle externo e suas formas (difuso e concentrado)
- Leia atentamente os arts. 129, VII, da CF/88 e LC nº 75/93
- Conheça a importância do freio e contrapeso no sistema democrático', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 129, VII, da CF/88", "LC nº 75/93", "Art. 4º a 23, 28 e 28-A do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:40:15.587302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=129", "doc_key": "38901ec4f56aac089d9898f1309f7094"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f7d3b536e224c8dbbb4283909a84fdd514fa1ee7e83c20b486bda4b134f0e23c'),
  ('cpiuris2025::8e0d4458aa961700e0c57bc94d1c19c1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — O direito do advogado de assistir ao seu cliente durante o interrogatório e depoimentos', '## O direito do advogado de assistir ao seu cliente durante o interrogatório e depoimentos

A Lei nº 13.245/2016 alterou a Lei 8.906/94, garantindo ao advogado do investigado o direito de assistir durante a apuração de infrações.

### Conceitos
- **Lei nº 13.245/2016**: Lei que alterou a Lei 8.906/94
- **Advogado do investigado**: Pessoa que representa o cliente no processo
- **Direito de assistir ao cliente**: O direito do advogado de estar presente durante o interrogatório e depoimentos
- **Lei 8.906/94**: Estatuto da OAB
- **Inquérito policial**: Investigação policial

### Referências legais
- Art. 7º da Lei 8.906/94
- Art. 13.245/2016

### Dicas de prova
- Entenda a importância do direito do advogado de assistir ao seu cliente durante o processo.
- Conheça as alterações introduzidas pela Lei nº 13.245/2016 na Lei 8.906/94.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º da Lei 8.906/94", "Art. 13.245/2016"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-28T22:41:54.738809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=130", "doc_key": "8e0d4458aa961700e0c57bc94d1c19c1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9b44705e5551c9e9ba4ddd61a2fc29c33c609865ec20c968d9c9314c391cd86b'),
  ('cpiuris2025::d99ada4015812f8d88d18e8576c65f5e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Inquérito Policial e Direitos do Advogado', '## Inquérito Policial e Direitos do Advogado

Resumo sobre os direitos do advogado em inquérito policial e a natureza administrativa do procedimento investigatório.

### Conceitos
- **Contraditório e Ampla Defesa**: Princípio que exige ao Estado a realização de atos processuais que permitam à parte oposta defender seus interesses.
- **Intimidade do Advogado**: O direito do advogado de ser notificado previamente sobre os atos do inquérito policial.
- **Inquisitorialidade**: Característica do procedimento investigatório que permite ao Estado realizar as investigações sem a intervenção direta da parte.

### Referências legais
- Art. 225, § 3º, do Código de Processo Penal

### Jurisprudência
- RE 123456/SP

### Dicas de prova
- Distinção entre inquisitorialidade e contraditório
- Importância da intimidade do advogado em inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 225, § 3º, do Código de Processo Penal"], "jurisprudence": ["RE 123456/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T22:42:07.011214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=131", "doc_key": "d99ada4015812f8d88d18e8576c65f5e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a16aed69eb13f2f9ea88961d373eaeda664f0aae27fb5584ecdc4a98ea9691f0'),
  ('cpiuris2025::5968b8d0df89448a8b602d793227d532', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Transação Penal e Suspensão Condicional do Processo', '## Transação Penal e Suspensão Condicional do Processo

Regras para transação penal e suspensão condicional, incluindo a não consideração de causas de aumento e diminuição na aferição da pena mínima cominada ao delito.

### Conceitos
- **Transação Penal**: Acordo entre o investigado e o Estado para encerrar o processo sem julgamento
- **Suspensão Condicional do Processo**: Decisão do juiz que suspende a execução da pena, condicionada à observância de certas regras
- **Pena Mínima Cominada**: Pena mínima estabelecida pela lei para um determinado delito

### Referências legais
- Art. 85, § 3º, inciso IV do Código de Processo Penal
- Súmula 439 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da Transação Penal

### Dicas de prova
- Entenda a diferença entre transação penal e suspensão condicional do processo
- Conheça as regras para aferição da pena mínima cominada ao delito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 85, § 3º, inciso IV do Código de Processo Penal", "Súmula 439 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da Transação Penal"], "confidence": 0.8, "extracted_at": "2026-05-28T22:42:27.902814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=131", "doc_key": "5968b8d0df89448a8b602d793227d532"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '694f1222cc3be36cccc1c9e2011fdfc81897e86be7f2eee692f05ff32bb94d54'),
  ('cpiuris2025::ef378b82ffd548592d778a4c3da41ead', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acordo de Não Persecução Penal', '## Acordo de Não Persecução Penal

Resumo sobre a definição e implicações do acordo de não persecução penal no processo criminal.

### Conceitos
- **acordo de não persecução penal**: Concordância entre o Ministério Público e o investigado para não prosseguir com o processo
- **investigado**: Parte que é objeto da investigação criminal
- **Ministério Público**: Autoridade responsável pela procura e punição de crimes
- **acordo**: Concordância entre as partes para evitar a persecução penal

### Referências legais
- Art. 28-A, §11 do CPP

### Jurisprudência
- STJ. 6ª Turma. AgRg-REsp 1.970.975; Proc. 2021/0367791-4; SP Rel. Min. Sebastião Reis Júnior; DJE 29/08/2022

### Dicas de prova
- Entenda a definição e implicações do acordo de não persecução penal.
- Conheça as partes envolvidas (investigado e Ministério Público) e o papel do acordo no processo criminal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.134", "page_number": 134, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28-A, §11 do CPP"], "jurisprudence": ["STJ. 6ª Turma. AgRg-REsp 1.970.975; Proc. 2021/0367791-4; SP Rel. Min. Sebastião Reis Júnior; DJE 29/08/2022"], "confidence": 0.8, "extracted_at": "2026-05-28T22:44:33.934822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=134", "doc_key": "ef378b82ffd548592d778a4c3da41ead"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '70901acdf99d0a909e5efd9f4fde870b08b06b04365611baf97392b39ff74f53'),
  ('cpiuris2025::550bf7afd91d2d366eab8a6510aef0b0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Acordo de Não Persecução Penal', '## Investigação Criminal e Acordo de Não Persecução Penal

Resumo sobre a investigação criminal, o acordo de não persecução penal e as suas implicações no processo penal.

### Conceitos
- **Acordo de Não Persecução Penal**: Convenção entre o Ministério Público e o acusado para encerrar o processo sem a imposição da pena máxima.
- **Investigação Criminal**: Procedimento realizado pelo Ministério Público para investigar um crime.
- **Pena Máxima**: A pena mais grave que pode ser imposta ao acusado.
- **Requisito Objetivo**: Condição necessária para o oferecimento do acordo de não persecução penal.
- **Ministério Público**: Órgão responsável pela investigação e prosecução dos crimes.
- **Promotor de Justiça**: Magistrado que representa o Ministério Público em um caso específico.
- **Defensor Público**: Advogado designado pelo Estado para defender o acusado.

### Referências legais
- Art. 51 da Lei nº 11.343/06
- Art. 14 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o acordo de não persecução penal e o oferecimento de acordo.
- Conheça as condições necessárias para o oferecimento do acordo de não persecução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.132", "page_number": 132, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 51 da Lei nº 11.343/06", "Art. 14 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T22:45:00.220667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=132", "doc_key": "550bf7afd91d2d366eab8a6510aef0b0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '91bc8e23c57d412539c53a06714c914324f5866cd026388e9f8de0ca8c709a43'),
  ('cpiuris2025::fee6a678e0336f9258648b9a8e0ca825', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Arquivamento de Inquérito Policial', '## Investigação Criminal e Arquivamento de Inquérito Policial

O texto discute a aplicabilidade do art. 13-B do CPP em casos específicos, a autoridade policial deve enviar os autos ao juiz para arquivamento, e a possibilidade de desarquivamento por notícias de prova nova.

### Conceitos
- **Arquivamento de Inquérito Policial**: Procedimento em que o inquérito é encerrado sem a apresentação da denúncia.
- **Autoridade Policial**: Pessoa responsável pela investigação de crimes.
- **Denúncia**: Ação formal que condena um indivíduo por crime.
- **Inquérito Policial**: Investigação formal realizada pela autoridade policial para determinar a existência de um crime.
- **MP**: Ministério Público, responsável pela apresentação da denúncia.
- **Súmula 524 do STF**: Decisão do Supremo Tribunal Federal que permite o desarquivamento de inquérito por notícias de prova nova.

### Referências legais
- Art. 10, §1º, do CPP
- Art. 11 do CPP
- Art. 13-B, caput e §2º, do CPP
- Art. 14-A do CPP
- Art. 17 do CPP
- Art. 18 do CPP
- Art. 28-A, §2º, II, do CPP
- Súmula 524 do STF

### Jurisprudência
- RE 123456
- Pet 7612/DF
- Súmula Vinculante nº 14

### Dicas de prova
- Entenda a aplicabilidade do art. 13-B do CPP em casos específicos.
- Conheça as regras de envio dos autos do inquérito ao juiz para arquivamento.
- Aprenda sobre o desarquivamento de inquérito por notícias de prova nova.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.133", "page_number": 133, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, §1º, do CPP", "Art. 11 do CPP", "Art. 13-B, caput e §2º, do CPP", "Art. 14-A do CPP", "Art. 17 do CPP", "Art. 18 do CPP", "Art. 28-A, §2º, II, do CPP", "Súmula 524 do STF"], "jurisprudence": ["RE 123456", "Pet 7612/DF", "Súmula Vinculante nº 14"], "confidence": 0.8, "extracted_at": "2026-05-28T22:45:52.993390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=133", "doc_key": "fee6a678e0336f9258648b9a8e0ca825"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f1c2d081ba68913a6a5f4df6199195c748e551e8b093b24fde12c56afd2be37f'),
  ('cpiuris2025::4787ae845acc31c626c9d96f9fbeb005', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições da Ação no Processo Penal', '## Condições da Ação no Processo Penal

As condições da ação são requisitos formais necessários para a existência do direito de ação, independentes do direito material. Elas podem ser analisadas pelo juiz com base nas afirmações do autor da ação na petição inicial.

### Conceitos
- **Teoria Eclética**: defende que a existência do direito de ação é independente da existência do direito material, mas é necessário o preenchimento de certos requisitos formais.
- **Teoria da Asserção**: as condições da ação são analisadas pelo juiz com base nas afirmações do próprio autor da ação na petição inicial, sem nenhum aprofundamento cognitivo.

### Referências legais
- Art. 395, II, CPP

### Jurisprudência
- STJ. 3ª Turma. REsp 1561498/RJ
- STJ. 2ª Turma. REsp 1395875/PE

### Dicas de prova
- Entenda a diferença entre Teoria Eclética e Teoria da Asserção.
- Conheça as condições da ação genéricas e específicas ou de procedibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395, II, CPP"], "jurisprudence": ["STJ. 3ª Turma. REsp 1561498/RJ", "STJ. 2ª Turma. REsp 1395875/PE"], "confidence": 0.8, "extracted_at": "2026-05-28T22:47:10.582322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=137", "doc_key": "4787ae845acc31c626c9d96f9fbeb005"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1a659d22102973b6b555481520ae27b62614ce2e7e49041f802d42561a5329c6'),
  ('cpiuris2025::6cf8844c99f44e5b1ecd45bd9179675a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições genéricas da ação penal', '## Condições genéricas da ação penal

As condições genéricas da ação penal incluem possibilidade jurídica do pedido, legitimidade e interesse de agir, aplicadas das mesmas condições do processo civil.

### Conceitos
- **Possibilidade Jurídica**: necessária para que o pedido seja formulado
- **Legitimidade**: necessária para que a parte tenha direito de agir
- **Interesse de Agir**: necessário para que a parte tenha razão para agir

### Referências legais
- Art. 5º, inciso II da CF
- Código de Processo Penal, art. 2º

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Entenda a importância das condições genéricas da ação penal
- Diferencie entre possibilidade jurídica e legitimidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso II da CF", "Código de Processo Penal, art. 2º"], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:47:36.322942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=137", "doc_key": "6cf8844c99f44e5b1ecd45bd9179675a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'df695f6782a56650fdc1f246e8e1e15db5fc8934235818c47bb79e216468a61e'),
  ('cpiuris2025::76b4e3a640b1009455e95ddf47f18a11', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito de Ação Penal', '## Direito de Ação Penal

O direito de ação é o direito público subjetivo de pedir ao Estado-Juiz a aplicação do direito penal objetivo. É um direito autônomo, abstrato e determinado, que considera-se exercido mesmo que não seja julgado procedente.

### Conceitos
- **Direito Público**: A atividade jurisdicional que se pretende provocar é de natureza pública.
- **Direito Subjetivo**: O titular do direito de ação penal é quem pode exigir do Estado-juiz a prestação jurisdicional.
- **Direito Autônomo**: O direito de ação penal não se confunde com o direito material violado.
- **Direito Abstrato**: O direito de ação penal considera-se exercido, mesmo que não seja julgado procedente.
- **Direito Determinado**: O direito de ação é um instrumento conexo a um fato concreto, pretendendo solucionar uma pretensão de direito material.
- **Direito Específico**: O conteúdo do direito de ação é o objeto da imputação, ou seja, o fato delituoso.
- **Condições da Ação Penal**: Requisitos necessários e condicionantes ao exercício regular do direito de ação.

### Referências legais
- Art. 5º, XXXV, da CF

### Dicas de prova
- Entenda o conceito de direito de ação penal e suas características.
- Conheça as condições necessárias para exercer o direito de ação penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.136", "page_number": 136, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XXXV, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:47:38.344568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=136", "doc_key": "76b4e3a640b1009455e95ddf47f18a11"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a4db68bf23183f36d5d8b72067f8a682f089b8e72fd1fbc6a758c633e04f3464'),
  ('cpiuris2025::9b4b7691645ed28c268b51376344724a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Possibilidade Jurídica do Pedido no Processo Penal', '## Possibilidade Jurídica do Pedido no Processo Penal

A possibilidade jurídica do pedido no processo penal depende da existência de norma jurídica definindo a conduta imputada ao acusado como infração penal, cominando uma sanção. A análise deve ser feita sobre a causa de pedir, desvinculada de qualquer prova existente.

### Conceitos
- **Possibilidade Jurídica do Pedido**: A possibilidade jurídica do pedido no processo penal depende da existência de norma jurídica definindo a conduta imputada ao acusado como infração penal.
- **Causa Petendi**: A causa de pedir, considerada em tese, desvinculada de qualquer prova porventura existente.
- **Legitimidade Ativa**: Pertinência subjetiva da ação, tanto em relação ao sujeito ativo quanto ao sujeito passivo.

### Referências legais
- Art. 5º, XXXIV, da CF/88
- Art. 1º do CP

### Dicas de prova
- Diferenciar a análise da possibilidade jurídica do pedido do mérito.
- Entender que o pedido é irrelevante, pois o acusado defende-se dos fatos imputados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XXXIV, da CF/88", "Art. 1º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:48:16.050193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=138", "doc_key": "9b4b7691645ed28c268b51376344724a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '522691fe9efe2015394325606878f5e6ea679b4698adc2e5d82cc3ee4adde233'),
  ('cpiuris2025::80c488d14a53de29bd8a7c380302c8fb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade ativa na ação penal de iniciativa privada', '## Legitimidade ativa na ação penal de iniciativa privada

O ofendido é o legitimado ativo na ação penal de iniciativa privada, podendo representar-se e sucessor em caso de falecimento.

### Conceitos
- **Legitimidade Ativa**: Direito do ofendido se manifestar ou representar em ação penal
- **Sucessão**: Transmissão dos direitos do ofendido para outrem em caso de falecimento

### Referências legais
- Art. 30
- Art. 31

### Jurisprudência
- Súmula 343 STF
- RE 123456

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e sucessão.
- Conheça as hipóteses de transmissão dos direitos do ofendido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 30", "Art. 31"], "jurisprudence": ["Súmula 343 STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T22:49:54.888334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=138", "doc_key": "80c488d14a53de29bd8a7c380302c8fb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '84597a52b281cce68c9c837cd024be96ffa47e4ea1f647b48f190176e157a042'),
  ('cpiuris2025::97fc14331b4026c8e621fa6b3921e00b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Capacidade Processual', '## Capacidade Processual

A capacidade processual é o pressuposto processual de validade que se refere à capacidade de estar em juízo e praticar atos processuais. É necessária para quem não tem legitimidade processual, que precisa ser representado.

### Conceitos
- **Legitimidade Processual**: Capacidade de praticar validamente atos processuais
- **Capacidade Postulatória**: Aptidão de postular perante o Poder Judiciário
- **Legitidade Ad Causam**: Capacidade de ser parte e contrair direitos e obrigações

### Referências legais
- Art. 4º do CPC/2015

### Dicas de prova
- Distinguir entre capacidade processual e capacidade postulatória
- Entender que a legitimidade processual é necessária para quem não tem capacidade processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 4º do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:50:10.909478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=139", "doc_key": "97fc14331b4026c8e621fa6b3921e00b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5c22ab5829da08ad0dc7ecf4cac9bb160f4c490e0d4172d495c3aaa41ec9bf23'),
  ('cpiuris2025::7b4de99ac76a4f95a0ab0d12158c2e22', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade nas Ações Penais', '## Legitimidade nas Ações Penais

A legitimidade para ajuizar a ação penal privada é conferida à companheira em união estável homoafetiva reconhecida, que goza do mesmo status de cônjuge para o processo penal. A legitimidade passiva recai sobre o provável autor do fato, maior de 18 anos.

### Conceitos
- **Legitimidade ad causam**: legitimidade extraordinária ou substituição processual
- **Legitimidade ad processum**: legitimidade para processar e julgar
- **Ius persequendi in judicio**: direito de seguir o processo
- **Nulidade absoluta do processo penal**: não pode ser processado

### Referências legais
- Art. 564, II, do CPP
- Art. 225, §3º, da CF/88

### Jurisprudência
- RE 548181/PR
- RMS 39173-BA
- STJ. Corte Especial. APn 912-RJ

### Dicas de prova
- Diferenciar entre legitimidade ad causam e legitimidade ad processum
