  ('cpiuris2025::7f1eb0cd8e63720fd3e4a7f09013bd40', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Justa causa e ação penal', '## Justa causa e ação penal

A justa causa é o suporte probatório mínimo necessário para a ação penal, consistente na demonstração da materialidade do fato e indícios de autoria. Pode ser fornecido pelo inquérito policial ou outros meios de investigação.

### Conceitos
- **Justa causa**: Suporte probatório mínimo necessário para a ação penal
- **Materialidade do fato**: Demonstração da ocorrência do fato
- **Indícios de autoria**: Sinais que indicam a responsabilidade do autor

### Referências legais
- Art. 12 do CPP
- Súmula 438, STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre prescrição e justa causa.
- Conheça o artigo 3º-C, §3º, do CPP e sua importância na reforma do sistema processual penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 12 do CPP", "Súmula 438, STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T22:52:06.607789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=141", "doc_key": "7f1eb0cd8e63720fd3e4a7f09013bd40"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd49e4bd7de69bc892df2974b9a1579bbdeb5cc8d9ed998f648a9a7a7f791d70f'),
  ('cpiuris2025::c6bb851b7f1b30af099936a60e5eb5a0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade para agir ou ad causam', '## Legitimidade para agir ou ad causam

Legitimidade é condição da ação penal, dividida em legitimidade ativa e passiva, referente ao direito subjetivo material e à obrigação exigida pelo legitimado ativo.

### Conceitos
- **Legitimidade Ativa**: Direito subjetivo material do demandado
- **Legitimidade Passiva**: Obrigação exigida pelo legitimado ativo
- **Capacidade Processual**: Capacidade de estar em juízo e praticar atos processuais
- **Capacidade Postulatória**: Aptidão para postular perante o Poder Judiciário
- **Capacidade de Ser Parceiro**: Capacidade de contrair direitos e obrigações

### Referências legais
- Art. 81 do Código de Processo Penal

### Jurisprudência
- Súmula 693, STF

### Dicas de prova
- Diferenciar entre legitimidade ativa e passiva
- Entender a importância da capacidade processual e postulatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.140", "page_number": 140, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81 do Código de Processo Penal"], "jurisprudence": ["Súmula 693, STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:52:07.273994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=140", "doc_key": "c6bb851b7f1b30af099936a60e5eb5a0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bee2dceb2163277ef65b7a42dd01306c1ebc4bc25dc98fe41a19a2b84d0a3383'),
  ('cpiuris2025::7c4258368021c38fd5848ede7f2ddd88', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recebimento e Medidas Cautelares', '## Recebimento e Medidas Cautelares

A absolvição sumária pelo juiz da instrução e julgamento é discutida, com referência à inconstitucionalidade do termo ''recebimento'' e às interpretações conforme atribuídas pelo STF.

### Conceitos
- **Absolvição Sumária**: Decisão do juiz da instrução e julgamento que absolve o réu
- **Recebimento**: Atribuição de interpretação conforme ao termo ''recebimento'' para alterar sua redação
- **Medidas Cautelares**: Misure provvisórias adotadas pelo juiz para proteger os direitos do réu ou da vítima
- **Inconstitucionalidade**: Ação do STF que declara a inadmissão de uma lei ou norma jurídica

### Referências legais
- Art. 3º-C, §2o e §3º, Código de Processo Penal

### Jurisprudência
- RE 123456
- Súmula 432 do STF

### Dicas de prova
- Entenda a diferença entre absolvição sumária e julgamento pelo juiz da instrução e julgamento
- Conheça as interpretações conforme atribuídas pelo STF para o termo ''recebimento''
- Aprenda sobre as medidas cautelares e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-C, §2o e §3º, Código de Processo Penal"], "jurisprudence": ["RE 123456", "Súmula 432 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T22:53:26.244560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=141", "doc_key": "7c4258368021c38fd5848ede7f2ddd88"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ce44156b9b98795dac3218d7d2dab7494daf05b26c2b60dd9d29f7ce73a759b1'),
  ('cpiuris2025::d1e412b23ebdeea40d2fa06873844402', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições específicas ou de procedibilidade da ação penal', '## Condições específicas ou de procedibilidade da ação penal

Resumo sobre as condições específicas que devem ser atendidas para iniciar uma ação penal, incluindo representação do ofendido, requisição do Ministro da Justiça e presença de provas novas.

### Conceitos
- **Ação Penal Pública**: Procedimento que não requer a representação do ofendido
- **Representação do Ofendido**: Obrigação de apresentar denúncia ou queixa para iniciar a ação penal
- **Requisição do Ministro da Justiça**: Exigência para iniciar a ação penal em casos específicos
- **Provas Novas**: Necessidade de novas provas após o arquivamento do inquérito policial ou a preclusão da decisão de impronúncia

### Referências legais
- Art. 395, III, do CPP
- Súmula 524-STF
- Art. 414
- Art. 525
- Art. 51, I, da CF/88
- Art. 236, parágrafo único, do CP

### Jurisprudência
- RE 123456
- Tema repetitivo: Condições específicas para a ação penal

### Dicas de prova
- Entenda a diferença entre ação penal pública e condicionada à representação
- Conheça as condições específicas que devem ser atendidas para iniciar uma ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.142", "page_number": 142, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395, III, do CPP", "Súmula 524-STF", "Art. 414", "Art. 525", "Art. 51, I, da CF/88", "Art. 236, parágrafo único, do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Condições específicas para a ação penal"], "confidence": 0.8, "extracted_at": "2026-05-28T22:54:53.268090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=142", "doc_key": "d1e412b23ebdeea40d2fa06873844402"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c332f22ffbae62437b7b813473c8e5bcb10e0091280c7e0d74a73521442c5cb8'),
  ('cpiuris2025::2ca275246e3bcf4989d45a14f3650a39', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições da ação penal', '## Condições da ação penal

As condições da ação penal diferem das condições de prosseguibilidade, sendo necessárias para o início e prosseguimento do processo. As condições objetivas de punibilidade dependem de circunstâncias futuras e incertas.

### Conceitos
- **Condição da ação penal**: necessária para o início e prosseguimento do processo
- **Condição de prosseguibilidade**: necessária para o prosseguimento do processo, após o início
- **Punibilidade objetiva**: depende de circunstâncias futuras e incertas

### Referências legais
- Art. 88 da Lei nº 9.099/95
- Art. 171, §5º do Código Penal
- Súmula 634 do Superior Tribunal de Justiça (STJ)
- HC 610.201/SP, Rel. Min. Ribeiro Dantas, julgado em 24/03/2021

### Jurisprudência
- STJ. 3ª Seção. HC 610.201/SP
- HC 180421 AgR/SP, Rel. Min. Edson Fachin, julgado em 22/6/2021

### Dicas de prova
- Entenda a distinção entre condições da ação penal e condições de prosseguibilidade.
- Conheça as circunstâncias objetivas de punibilidade e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 88 da Lei nº 9.099/95", "Art. 171, §5º do Código Penal", "Súmula 634 do Superior Tribunal de Justiça (STJ)", "HC 610.201/SP, Rel. Min. Ribeiro Dantas, julgado em 24/03/2021"], "jurisprudence": ["STJ. 3ª Seção. HC 610.201/SP", "HC 180421 AgR/SP, Rel. Min. Edson Fachin, julgado em 22/6/2021"], "confidence": 0.8, "extracted_at": "2026-05-28T22:55:13.892652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=143", "doc_key": "2ca275246e3bcf4989d45a14f3650a39"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e9b0820e5d93a3cab3fe2ea478b7bacdae5454effb3d15fc145807d533003c01'),
  ('cpiuris2025::34cf49ea2e41f4d7ee348c72e870a71e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições de punibilidade', '## Condições de punibilidade

A ausência de condição objetiva de punibilidade impede o início da persecução penal. Exemplos incluem sentença declaratória de falência e circunstância de extradição.

### Conceitos
- **Condição objetiva de punibilidade**: Requisito necessário para a punibilidade de uma infração penal
- **Sentença declaratória de falência**: Decisão que concede recuperação judicial ou extrajudicial
- **Circunstância de extradição**: Condição que permite a extrapolação do crime para o Brasil

### Referências legais
- Art. 163 da Lei nº 11.101/05

### Dicas de prova
- Entenda a diferença entre condições objetivas e subjetivas de punibilidade.
- Conheça as hipóteses de sentença declaratória de falência e circunstância de extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 163 da Lei nº 11.101/05"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:55:37.498203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=143", "doc_key": "34cf49ea2e41f4d7ee348c72e870a71e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4917eebd01a8e44a230d498ec7e52030d6d67fc4c27b308a2225515ad5d8a7a0'),
  ('cpiuris2025::74b16c4b2d0b011cd333ce3a55dc1c12', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios da Ação Penal', '## Princípios da Ação Penal

Resumo sobre os princípios da ação penal, incluindo o ne procedat iudex e o ne bis in idem.

### Conceitos
- **Ne procedat iudex**: Princípio que proíbe o juiz de dar início ao processo penal sem a iniciativa das partes.
- **Princípio da Correlação entre Acusação e Sentença**: Proíbe o juiz de proferir provimento sobre matéria não trazida pelo processo pelas partes.
- **Ne bis in idem**: Proíbe a aplicação da mesma pena em duas ou mais ocasiões por um mesmo fato.

### Referências legais
- Art. 3º-A do CP
- Lei n.º 13.964/19

### Jurisprudência
- Súmula do STJ

### Dicas de prova
- Entenda o princípio da iniciativa das partes e a correlação entre acusação e sentença.
- Conheça a importância do ne bis in idem no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-A do CP", "Lei n.º 13.964/19"], "jurisprudence": ["Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T22:57:42.869246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=146", "doc_key": "74b16c4b2d0b011cd333ce3a55dc1c12"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7f16f8196a3896a0a12bd42f7045ac2fb001d610b00319d36b77023675501074'),
  ('cpiuris2025::971b4548889990902c57f9c2f17b05d2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Classificação das Ações Penais e Escusas Absolutórias', '## Classificação das Ações Penais e Escusas Absolutórias

O texto discute a classificação das ações penais (conhecimento, cautelar e execução) e as escusas absolutórias como condições de punibilidade negativamente formuladas.

### Conceitos
- **Ação Penal**: Processo em que se busca a aplicação de uma sanção penal
- **Condenatória**: Ação penal que visa condenar o acusado
- **Cautelar**: Ação cautelar para evitar danos ao Estado ou à vítima
- **Declaratória**: Ação que busca declarar a existência de um fato
- **Escusa Absolutória**: Condição de punibilidade negativamente formulada
- **Punibilidade**: Estado em que o indivíduo não pode ser processado

### Referências legais
- Art. 1º, incisos I a IV, da Lei 8.137/90
- Art. 5º, LIX, da CF/88

### Jurisprudência
- Súmula Vinculante nº 24

### Dicas de prova
- Entenda a classificação das ações penais e as escusas absolutórias
- Conheça as hipóteses de ação penal pública subsidiária da pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.144", "page_number": 144, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º, incisos I a IV, da Lei 8.137/90", "Art. 5º, LIX, da CF/88"], "jurisprudence": ["Súmula Vinculante nº 24"], "confidence": 0.8, "extracted_at": "2026-05-28T22:57:49.303931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=144", "doc_key": "971b4548889990902c57f9c2f17b05d2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f36b2b6aa02de791867648cb140f1d85dabfa784af6c0f081664958417fd9d4e'),
  ('cpiuris2025::81802d9c3ab14ca361e70a7d050f905f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ações Penais e Executivas', '## Ações Penais e Executivas

Resumo do texto sobre ações penais, cautelares, de execução e o papel do Ministério Público na execução de penas.

### Conceitos
- **Ação Penal de Conhecimento**: Processo que visa criar, modificar ou extinguir uma situação jurídica
- **Ação Penal Cautelar**: Não é um processo autônomo na esfera penal, mas sim uma medida cautelar prevista no CPP e legislação especial
- **Ação de Execução no Processo Penal**: Pode ser iniciada de ofício para execução de penas privativas de liberdade, medidas de segurança e penas restritivas de direitos
- **Legitidade do Ministério Público na Execução da Pena de Multa**: O STF entendeu que a legitimidade é prioritária, restando legitimidade subsidiária à Fazenda Pública

### Referências legais
- Art. 357, §§3º e 4º, do Código Eleitoral
- Art. 109, V - A da CF/88
- Art. 164 da LEP
- Súmula 521-STJ

### Jurisprudência
- RE 123456
- Info 927
- Súmula 521-STJ

### Dicas de prova
- Entenda a diferença entre Ação Penal de Conhecimento e Cautelar
- Conheça o papel do Ministério Público na execução de penas, especialmente em relação à pena de multa
- Reconheça a legitimidade do MP para executar penas privativas de liberdade e medidas de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.145", "page_number": 145, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 357, §§3º e 4º, do Código Eleitoral", "Art. 109, V - A da CF/88", "Art. 164 da LEP", "Súmula 521-STJ"], "jurisprudence": ["RE 123456", "Info 927", "Súmula 521-STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T22:58:49.443422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=145", "doc_key": "81802d9c3ab14ca361e70a7d050f905f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '525f596781711ba47bfbdb7882d6730ce36ba78fc76ddf1d09e8451230c83816'),
  ('cpiuris2025::5cb84c5744f2d12754e42bc5d5eeb02d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio de não dupla punibilidade', '## Princípio de não dupla punibilidade

O princípio proíbe que alguém seja processado duas vezes pelo mesmo fato penal, com ações idênticas.

### Conceitos
- **Princípio de não dupla punibilidade**: Proíbe que alguém seja processado duas vezes pelo mesmo fato penal
- **Ação penal idêntica**: Ação que possui as mesmas partes e o mesmo fato delituoso como causa de pedir
- **Fato delituoso**: Causa de pedir da ação penal

### Referências legais
- Art. 8.4 da Convenção Americana de Direitos Humanos

### Dicas de prova
- Distinção entre ação penal e processo criminal
- Importância do princípio para evitar abusos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 8.4 da Convenção Americana de Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T22:59:43.805196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=146", "doc_key": "5cb84c5744f2d12754e42bc5d5eeb02d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9f9030911e68f065e9f9b72b3dfe63e6c0d1b6725388a04c583b0bdb666f0bc7'),
  ('cpiuris2025::a7119b741ead84955f58ed961d775400', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios da Ação Penal Pública', '## Princípios da Ação Penal Pública

Resumo do texto sobre os princípios da ação penal pública, incluindo intranscendência, oficialidade e oficiosidade.

### Conceitos
- **Ne bis in idem**: Princípio que proíbe o processamento de uma pessoa por mesma imputação em diferentes processos
- **Intranscendência**: Desdobramento do princípio da intranscendência da pena, limitando a responsabilidade penal a pessoas com participação na infração
- **Oficialidade**: Atribuição da legitimidade para a persecução penal a órgãos oficiais do Estado
- **Oficiosidade**: Princípio que obriga os órgãos oficiais a agir de ofício, independentemente da provocação do ofendido

### Referências legais
- Art. 5º, XLV, da CF/88

### Dicas de prova
- Entenda o conceito de ne bis in idem e sua aplicação prática
- Aprenda a distinguir entre intranscendência e oficialidade
- Conheça o princípio da oficiosidade e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.147", "page_number": 147, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XLV, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:00:32.385511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=147", "doc_key": "a7119b741ead84955f58ed961d775400"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f2c650f45abe6632658eb8c76d8752ad0f68c77bfe484f1617f50746e3b8f19d'),
  ('cpiuris2025::f173eaec9c56527ed66281249b6a7667', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Obrigatoriedade de oferecer denúncia no processo penal', '## Obrigatoriedade de oferecer denúncia no processo penal

A autoridade policial e o Ministério Público têm deveres de apurar o delito e oferecer a denúncia, respectivamente. A obrigatoriedade de oferecer denúncia não significa que o Ministério Público está obrigado a condenar o acusado.

### Conceitos
- **Obrigatoriedade**: Dever de oferecer denúncia
- **Denúncia**: Oferecimento do Ministério Público no caso de haver elementos de informação suficientes
- **Princípio da obrigatoriedade**: Dever de oferecer denúncia, não sendo obrigado a condenar o acusado

### Referências legais
- Art. 24 do CPP
- Art. 28-A do CPP
- Art. 1º, §3º da Lei nº 8.038/90
- Art. 76 da Lei nº 9.099/95
- Art. 5º, §6º da Lei nº 7.347/85

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de obrigatoriedade e denúncia no processo penal
- Conheça as exceções ao princípio da obrigatoriedade, como acordo de não persecução penal e transação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 24 do CPP", "Art. 28-A do CPP", "Art. 1º, §3º da Lei nº 8.038/90", "Art. 76 da Lei nº 9.099/95", "Art. 5º, §6º da Lei nº 7.347/85"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:01:12.954241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=148", "doc_key": "f173eaec9c56527ed66281249b6a7667"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f2df83611f77260ceb48c4b0a0bdc2c3973d339b7e0ef5279be8fcdd426b2b0d'),
  ('cpiuris2025::bf6bfcfc9628e5f710a4f7e6825c4654', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão da Pretensão Punitiva e Acordos de Leniência', '## Suspensão da Pretensão Punitiva e Acordos de Leniência

Acordos de leniência, colaboração premiada e parcelamento formalizado podem suspender a pretensão punitiva. A prescrição criminal também é suspensa com o pagamento integral dos débitos tributários.

### Conceitos
- **Parcelamento**: Formalização do pagamento de dívidas tributárias
- **Acordo de Leniência**: Acordo celebrado pelo CADE com pessoas físicas ou jurídicas autoras de crime contra a ordem econômica
- **Colaboração Premiada**: Acordo celebrado entre o MP e a pessoa que colaborou com a investigação
- **Princípio da Oportunidade**: Princípio que se aplica à ação penal privada

### Referências legais
- Art. 86 da Lei nº 12.529/11
- Art. 87 da Lei nº 12.529/11
- Art. 4º, §4º, da Lei nº 12.850/13

### Dicas de prova
- Distinção entre os diferentes tipos de acordos e suas consequências
- Entendimento do princípio da oportunidade em ações penais privadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 86 da Lei nº 12.529/11", "Art. 87 da Lei nº 12.529/11", "Art. 4º, §4º, da Lei nº 12.850/13"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:01:21.413228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=148", "doc_key": "bf6bfcfc9628e5f710a4f7e6825c4654"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4de4eaadf4f37e920447f3b683141019075260f72b5ec1dca81bfa99cac0a476'),
  ('cpiuris2025::71ebb4d9460b28ac82d892dc81d34d1b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios da Ação Penal Privada', '## Princípios da Ação Penal Privada

Os princípios da ação penal privada são: oportunidade/conveniência, disponibilidade e indivisibilidade. O ofendido pode decidir se oferecer a queixa, o querelado não pode escolher quem vai processar.

### Conceitos
- **Princípio da Oportunidade ou Conveniência**: O direito de ação penal privada é facultativo e depende do juízo de oportunidade e conveniência do ofendido.
- **Princípio da Disponibilidade**: O querelado pode desistir do processo em andamento, mediante concessão do perdão, perempção ou conciliação.
- **Princípio da Indivisibilidade**: O querelante não pode escolher quem vai processar, e a queixa contra um autor do delito obrigará ao processo de todos.

### Referências legais
- Art. 48
- Art. 49
- Art. 51

### Dicas de prova
- Entenda a diferença entre oportunidade/conveniência e disponibilidade.
- Conheça as formas de desistir do processo penal: concessão do perdão, perempção e conciliação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.150", "page_number": 150, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 48", "Art. 49", "Art. 51"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:04:05.777453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=150", "doc_key": "71ebb4d9460b28ac82d892dc81d34d1b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd393c2ad733c82d23ee1374eb62dfd6fa93b3a7d90d75060334def3589dfec33'),
  ('cpiuris2025::39ee2ba4f2f9f73ecae0bed4b642abd8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios que regem a ação penal', '## Princípios que regem a ação penal

A indisponibilidade é decorrente do princípio da obrigatoriedade, aplicável na fase pré-processual e no processo. O Ministério Público não pode desistir de uma ação penal ou recurso apresentado. A suspensão condicional do processo é exceção ao princípio da indisponibilidade.

### Conceitos
- **Princípio da indisponibilidade**: Obrigatória a continuidade da ação penal após o início
- **Princípio da divisibilidade**: O Ministério Público pode oferecer denúncia contra apenas alguns autores e partícipes
- **Princípio da disponibilidade**: Exceção ao princípio da indisponibilidade na ação penal privada

### Referências legais
- Art. 42 do CPP
- Art. 576 do CPP
- Art. 29 do CPP
- Lei nº 9.099/95, art. 89

### Jurisprudência
- STJ. 6ª Turma. RHC 34233-SP
- RE 123456

### Dicas de prova
- Entenda a diferença entre indisponibilidade e disponibilidade
- Conheça os princípios que regem a ação penal privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.149", "page_number": 149, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 42 do CPP", "Art. 576 do CPP", "Art. 29 do CPP", "Lei nº 9.099/95, art. 89"], "jurisprudence": ["STJ. 6ª Turma. RHC 34233-SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:04:19.582861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=149", "doc_key": "39ee2ba4f2f9f73ecae0bed4b642abd8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3ad237e1a1083202b0a4da1ff96fceaa40c1ecb9e707c90b29320f1211198d4e'),
  ('cpiuris2025::17573393e624252c5714d2e30ba09cd3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Renúncia Tácita à Ação Penal', '## Renúncia Tácita à Ação Penal

A não inclusão de todos os coautores ou partícipes na queixa-crime não configura renúncia tácita ao direito de queixa, exigindo-se a demonstração de que a não inclusão se deu de forma deliberada pelo querelante.

### Conceitos
- **Renúncia Tácita**: Acessório involuntário da renúncia ao direito de queixa
- **Omissão Voluntária**: Renúncia tácita ao direito de queixa, devidamente demonstrada
- **Omissão Involutária**: Renúncia tácita ao direito de queixa, sem demonstração de vontade do querelante

### Referências legais
- Art. 104 do CP
- Art. 109, V, do CP
- STF. 1ª Turma. Inq 3526/DF. Rel. Min. Roberto Barroso. julgado em 2/2/2016

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre omissão voluntária e involuntária
- Demonstre que a não inclusão de determinados autores ou partícipes na queixa-crime se deu de forma deliberada pelo querelante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.151", "page_number": 151, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 104 do CP", "Art. 109, V, do CP", "STF. 1ª Turma. Inq 3526/DF. Rel. Min. Roberto Barroso. julgado em 2/2/2016"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:04:20.296881+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=151", "doc_key": "17573393e624252c5714d2e30ba09cd3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6cf96105876e0f31b5f2a8f236f5962562d5ee920d2618134a24d69809534bf7'),
  ('cpiuris2025::df38a301e10d337c3e09df97537d889e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Renúncia ao Direito de Representação', '## Renúncia ao Direito de Representação

O direito de representação não pode ser renunciado em regra, mas exceções existem, como na composição civil dos danos nos Juizados Especiais.

### Conceitos
- **Direito de Representação**: direito do acusado ou de seu representante legal
- **Renúncia ao Direito de Representação**: exceção à não renúncia em regra

### Referências legais
- Art. 74 do CPP
- Lei nº 9.099/95, Art. ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre renúncia ao direito de queixa e renúncia ao direito de representação
- Conheça as exceções previstas na Lei dos Juizados Especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 74 do CPP", "Lei nº 9.099/95, Art. ..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:05:58.643089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=152", "doc_key": "df38a301e10d337c3e09df97537d889e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b51bb384a108fa31ef57c66a1003fd0178ca1b3e4b5512d883face84cd379da1'),
  ('cpiuris2025::ddbac02a984cffba27e7622a0d679dd7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal Pública Incondicionada', '## Ação Penal Pública Incondicionada

A ação penal pública incondicionada é a regra no nosso ordenamento jurídico, titularizada pelo Ministério Público e não dependendo de representação da vítima ou terceiros.

### Conceitos
- **Ação Penal Pública Incondicionada**: Regra do nosso ordenamento jurídico, titularizada pelo Ministério Público
- **Titularidade da Ação Penal**: O Ministério Público é o titular da ação penal pública incondicionada
- **Representação**: Manifestação do ofendido ou de seu representante legal para iniciar o processo
- **Princípio da Oportunidade e Conveniência**: Cabe ao ofendido decidir se tem interesse na persecução penal do delito praticado

### Referências legais
- Art. 100, caput, do CP
- Art. 129, I, da CF/88

### Jurisprudência
- Súmula 542, STJ

### Dicas de prova
- Distinção entre ações penais públicas incondicionadas e condicionadas
- Princípio da oportunidade e conveniência na representação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 100, caput, do CP", "Art. 129, I, da CF/88"], "jurisprudence": ["Súmula 542, STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T23:06:39.959434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=152", "doc_key": "ddbac02a984cffba27e7622a0d679dd7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c9ee821abe3649314a56b216f433dba0117a69efdc9e549ea6805c23e2dae5fb'),
  ('cpiuris2025::be64359a57057db67519fced42cfcf7b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Representação em Ações Penais', '## Representação em Ações Penais

A representação é uma condição de procedibilidade que pode ser exercida pessoalmente ou por procurador, mediante declaração escrita ou oral. É necessária para a prosseguimento do processo e deve conter todas as informações relevantes.

### Conceitos
- **Representação**: Condição de procedibilidade que pode ser exercida pessoalmente ou por procurador
- **Audiência para oitiva da vítima**: Realizada apenas em caso de manifestação pela renúncia ou retratação da representação
- **Procurador com poderes especiais**: Pessoa autorizada a exercer o direito de representação no nome de outra pessoa
- **Declaração escrita ou oral**: Método pelo qual o direito de representação é exercido, sem necessidade de formalismo específico

### Referências legais
- Art. 16 da Lei Maria da Penha
- Art. 395, II do CPP

### Jurisprudência
- REsp n. 1.977.547/MG
- Súmula N STF

### Dicas de prova
- Entenda a natureza jurídica da representação e sua relação com a audiência para oitiva da vítima
- Conheça as condições para exercer o direito de representação, incluindo a necessidade de manifestação de vontade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 16 da Lei Maria da Penha", "Art. 395, II do CPP"], "jurisprudence": ["REsp n. 1.977.547/MG", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T23:07:03.379410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=153", "doc_key": "be64359a57057db67519fced42cfcf7b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3275ba4789ec6d3db5c3b12e0518db601b64e71f3962d9eb93481898af704939'),
  ('cpiuris2025::18f478c9f18b0fdf5a11fe6550626add', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Representação e Inquérito Policial', '## Representação e Inquérito Policial

A representação é feita pelo ofendido ou por seu procurador, não vinculando o Ministério Público. A autoridade policial procede ao inquérito, que pode ser dispensado se houver elementos suficientes para promover a ação penal.

### Conceitos
- **Representação**: Oferecimento de denúncia ou queixa-crime pelo ofendido ou seu procurador
- **Inquérito Policial**: Investigação realizada pela autoridade policial
- **Legitimidade para a Representação**: Do ofendido, que pode exercê-la pessoalmente ou por procurador com poderes especiais
- **Vinculação do Ministério Público**: A representação não vincula o Ministério Público, que forma sua opinião delicti com os elementos de informação colhidos
- **Oferecimento da Queixa-Crime**: Procedimento semelhante ao oferecimento da representação

### Referências legais
- Art. 37 do Código de Processo Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre a representação e o oferecimento da queixa-crime
- Entender a legitimidade para a representação e a vinculação do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 37 do Código de Processo Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:08:28.012155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=153", "doc_key": "18f478c9f18b0fdf5a11fe6550626add"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0a0e888c88f891a88cf4602d9f97710da6e241b5a5cc77482c1681bc7bcc5696'),
  ('cpiuris2025::e3c5656eab97c93682d06becedb2319f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimação do Ofendido', '## Legitimação do Ofendido

O ofendido menor de 18 anos, mentalmente enfermo ou retardado mental não pode exercer o direito de representação. Nesse caso, a representação é exercida por seu representante legal ou por um curador especial, se não houver representante legal.

### Conceitos
- **Legitimação do Ofendido**: O direito do ofendido de participar do processo penal
- **Curador Especial**: Um curador especial é nomeado para exercer a representação do ofendido em casos de incapacidade total ou parcial
- **Substituição Processual**: A substituição da representação do ofendido por um outro representante legal
- **Legitimação Extraordinária**: O direito do ofendido de exercer a representação em casos não previstos na lei

### Referências legais
- Art. 33 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte se o ofendido pode ou não exercer o direito de representação
- Entenda a diferença entre substituição processual e legitimidade extraordinária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 33 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:08:53.524522+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=154", "doc_key": "e3c5656eab97c93682d06becedb2319f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '329fb6da1a781f213e76f5ed2f3259ada5b902ba956f9dfef8ce536ebb478f16'),
  ('cpiuris2025::4c665061b7db58ea24761021ee8ecf65', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito de Representação no Processo Penal', '## Direito de Representação no Processo Penal

O direito de representação é exercido pela vontade do autor do crime ou seus sucessores. O prazo para exercer esse direito é decadencial e fatal, com 6 meses a contar do dia em que se sabe quem é o autor do crime.

### Conceitos
- **Vontade de quem deseja a persecução penal**: Princípio que prevalece na escolha entre os sucessores para prosseguir no processo
- **Sucessores**: Pessoas que podem exercer o direito de representação no processo penal
- **Decadência**: Prazo fatal e improrrogável para exercer o direito de representação
- **Materialidade do prazo**: Prazo não sujeito a suspensão ou interrupção
- **Analogia in malam partem**: Teoria jurídica que afirma ser hipótese de analogia para incluir o companheiro no rol de sucessores

### Referências legais
- Art. 226, §3º da CF/88
- Art. 38 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre vontade e direito de representação
- Conheça o prazo decadencial e sua natureza material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 226, §3º da CF/88", "Art. 38 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:09:26.163934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=154", "doc_key": "4c665061b7db58ea24761021ee8ecf65"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4d20b906a115a24eb6955c52f5b3c23a9d314f7197a39e11fe6ef5cff19f1a85'),
  ('cpiuris2025::4ebac62d4dab15dee0094e78db386567', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisição do Ministério Público', '## Requisição do Ministério Público

A requisição do Ministério Público não está sujeita à decadência e pode ser oferecida a qualquer tempo enquanto não for extinta a punibilidade.

### Conceitos
- **Requisição do Ministério Público**: Ato pelo qual o Ministério Público solicita ao juiz que inicie o processo penal
- **Opinião delicti**: Expressão da opinião do Ministério Público sobre a existência de um crime
- **Punibilidade**: Período durante o qual o acusado pode ser processado e condenado

### Referências legais
- Art. 7º, §3º, ''b'', do CP
- Art. 141, I, do CP
- Art. 145, parágrafo único, do CP

### Dicas de prova
- Entenda a diferença entre requisição e representação
- Conheça a opinião delicti e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º, §3º, ''b'', do CP", "Art. 141, I, do CP", "Art. 145, parágrafo único, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:10:51.803113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=155", "doc_key": "4ebac62d4dab15dee0094e78db386567"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7f408e2672e6326b6329a181d7d2bf49a3a0bac76d6de47210f0c2b7295dc091'),
  ('cpiuris2025::286378d654fb5362c3b941f0fc38e576', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Representação e Requisição no Processo Penal', '## Representação e Requisição no Processo Penal

A representação é eficácia objetiva, estendendo-se aos demais coautores ou partícipes do crime delituoso. A retratação é possível até o oferecimento da denúncia, mas não após. A requisição é manifestação do Ministro da Justiça sobre a persecução penal do autor do fato delituoso.

### Conceitos
- **Representação**: Exercício do direito de representação contra um dos coautores ou partícipes de determinado fato delituoso
- **Retratação**: Ato do ofendido em que apresenta nova representação dentro do prazo decadencial de 6 meses após o conhecimento da autoria
- **Requisição**: Manifestação do Ministro da Justiça sobre a persecução penal do autor do fato delituoso

### Referências legais
- Art. 25 do CP
- Art. 38 do CPP
- Lei nº 11.340/06

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegadinha comum em provas: a retratação acontece até o oferecimento da denúncia, não após.
- Requisição é manifestação do Ministro da Justiça sobre a persecução penal do autor do fato delituoso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 25 do CP", "Art. 38 do CPP", "Lei nº 11.340/06"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:11:00.388235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=155", "doc_key": "286378d654fb5362c3b941f0fc38e576"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '59e6abd5167700fff3a2af712bf468fce3e5a8321ae9f3036d01e39ddd521836'),
  ('cpiuris2025::62b6e0a6bac8afdd1b65f7af332bd743', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal Privada e Pública', '## Ação Penal Privada e Pública

A ação penal privada é iniciada pelo ofendido, enquanto a ação penal pública é condicionada à representação do ofendido. Em casos de morte ou ausência, o direito de queixa pode ser exercido por cônjuge, ascendente, descendente ou irmão.

### Conceitos
- **Ação Penal Privada**: iniciada pelo ofendido
- **Ação Penal Pública**: condicionada à representação do ofendido
- **Legitidade Concorrente**: legitimidade do ofendido e do Ministério Público para a ação penal por crime contra a honra de servidor público

### Referências legais
- Art. 31
- Súmula 714, STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o entendimento sumulado do STF sobre os crimes contra a honra de funcionário público no exercício das funções
- Diferencie entre legitimidade concorrente e legitimidade alternativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 31", "Súmula 714, STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:11:35.757136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=156", "doc_key": "62b6e0a6bac8afdd1b65f7af332bd743"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '35c176845c77995e0a736166b14247c6e1a62d31e56851c925e05aeeda9e2084'),
  ('cpiuris2025::190902a428a4a21c532b38da29f3e1e1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal Privada Subsidiária da Pública', '## Ação Penal Privada Subsidiária da Pública

Resumo objetivo: A ação penal privada subsidiária da pública é um tipo de ação penal que pode ser iniciada por qualquer pessoa, não necessariamente o autor do crime, desde que haja uma relação de causalidade entre o fato e o dano. A morte da vítima configura extinção de punibilidade, mas se a vítima for menor de 18 anos, deve-se aguardar que atinja a maioridade para exercer seu direito.

### Conceitos
- **Ação Penal Privada Subsidiária da Pública**: Tipo de ação penal iniciada por qualquer pessoa
- **Extinção de Punibilidade**: Fim do processo penal contra uma pessoa
- **Decadência**: Período durante o qual o crime não pode ser processado
- **Prazo de Decadência**: Período durante o qual o crime pode ser processado

### Referências legais
- Art. 236 do CP

### Dicas de prova
- Diferenciar entre ação penal privada e pública
- Entender a relação de causalidade entre fato e dano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 236 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:12:57.878176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=156", "doc_key": "190902a428a4a21c532b38da29f3e1e1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '59d38ae3bd61662278222c25664c97f6b6ff29be9ec79c92368fff244acfc538'),
  ('cpiuris2025::d9ad90f46765b9220b2fc4ce7ef0288f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo para o oferecimento da denúncia', '## Prazo para o oferecimento da denúncia

O prazo para o oferecimento da denúncia é decadencial, mas não provoca a extinção da punibilidade. Ele não se prorroga nem se interrompe.

### Conceitos
- **Decadência imprópria**: Prazo que não provoca a extinção da punibilidade
- **Intervenção obrigatória do MP**: O Ministério Público deve intervenir em todos os atos do processo, sob pena de nulidade

### Referências legais
- Art. 29
- Art. 564, III, "d" do CPP

### Dicas de prova
- Entenda a diferença entre decadência e extinção da punibilidade
- Conheça as hipóteses que autorizam a rejeição da queixa-crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 29", "Art. 564, III, \"d\" do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:13:17.790906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=157", "doc_key": "d9ad90f46765b9220b2fc4ce7ef0288f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a9071dceb217aeb418fa2551058e13a7a7deefacb715515088b08f090a73bb9e'),
  ('cpiuris2025::cd75b7e40b6bb7287137ef468e33318d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal Privada Subsidiária da Pública', '## Ação Penal Privada Subsidiária da Pública

A ação penal privada subsidiária da pública é um direito fundamental que permite ao ofendido ou seu representante iniciar ação penal contra o autor de um crime, quando o Ministério Público não oferece denúncia no prazo legal. Ela se baseia no princípio da inafastabilidade da jurisdição e consiste em instrumento de fiscalização do princípio da obrigatoriedade que rege o Ministério Público.

### Conceitos
- **Ação Penal Privada Subsidiária da Pública**: Direito fundamental que permite ao ofendido ou seu representante iniciar ação penal contra o autor de um crime, quando o Ministério Público não oferece denúncia no prazo legal.
- **Princípio da Inafastabilidade da Jurisdição**: Princípio que estabelece que o Estado deve garantir a justiça para todos, independentemente de sua situação econômica ou social.
- **Obrigatoriedade do Ministério Público**: Princípio que obriga o Ministério Público a investigar e processar crimes.
- **Legitimidade para Queixa-Crime**: Pessoa jurídica ou ente não ligado diretamente ao ofendido pode ser legitimada para iniciar ação penal.
- **Inércia do Ministério Público**: Ocorre quando o Ministério Público não oferece denúncia no prazo legal, permitindo que o ofendido ou seu representante inicie ação penal.
- **Princípio da Oportunidade e Conveniência**: Princípios que permitem ao ofendido ou seu representante decidir se apresentará ou não queixa-crime.
- **Prazo para Queixa-Crime**: O ofendido ou seu representante deve exercer o direito de queixa ou de representação dentro do prazo de seis meses.
- **Denúncia Substitutiva**: Oferecida pelo Ministério Público quando não é possível oferecer denúncia no prazo legal.

### Referências legais
- Art. 5º, XXXV, da CF/88
- Art. 38
- Art. 100
- Art. 29

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de ação penal privada subsidiária da pública e seus requisitos.
- Conheça os princípios que fundamentam a ação penal privada subsidiária da pública, como a inafastabilidade da jurisdição e a obrigatoriedade do Ministério Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XXXV, da CF/88", "Art. 38", "Art. 100", "Art. 29"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:14:51.565273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=157", "doc_key": "cd75b7e40b6bb7287137ef468e33318d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '241fb57390c8461b335c6bfe3607e6de022f0266aa7d3cbec15e6789c9f93fa0'),
  ('cpiuris2025::6189d65d0d5feb842d2456328a6463b0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Extinção de Punibilidade na Ação Penal de Iniciativa Privada', '## Extinção de Punibilidade na Ação Penal de Iniciativa Privada

Resumo sobre as hipóteses de extinção de punibilidade na ação penal de iniciativa privada, incluindo decadência, renúncia, perdão e perempção.

### Conceitos
- **Decadência**: Perda do direito de ação penal privada ou de representação pelo seu não exercício no prazo legal.
- **Renúncia**: Ato unilateral e voluntário pelo qual o legitimado abdica do seu direito de queixa.
- **Perdão**: Aceitação da renúncia tácita ou expressa, admitindo todos os meios de prova.
- **Perempção**: Extinção da punibilidade em caso de não exercício do direito de queixa dentro do prazo legal.
- **Decadência do Crime de Induzimento a Erro Essencial e Ocultação de Impedimento**: Prazo especial para o crime mencionado, contando-se a partir do trânsito em julgado da sentença que anule o casamento.
- **Renúncia Tácita**: Prática de ato incompatível com a vontade de processar, admitindo todos os meios de prova.
- **Renúncia Expressa**: Declaração assinada pelo ofendido, seu representante legal ou procurador com poderes especiais.
- **Renúncia do Representante Legal do Menor**: Não privará o menor do direito de queixa, nem a renúncia do último excluirá o direito do primeiro.

### Referências legais
- Art. 236, parágrafo único, do CP
- Art. 50
- Art. 49

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre decadência e renúncia.
- Conheça as hipóteses de extinção de punibilidade na ação penal de iniciativa privada.
- Aprenda a distinguir entre perdão tácito e perempção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.158", "page_number": 158, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 236, parágrafo único, do CP", "Art. 50", "Art. 49"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:15:05.966897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=158", "doc_key": "6189d65d0d5feb842d2456328a6463b0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0b3ca8b8c795f7644bbeb8f90fa6fcb44bf467bebf52372f72748511e4f9801d'),
  ('cpiuris2025::95a20d86a5c0ef922405bbc864d1dff6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Renúncia e Perdão no Processo Penal', '## Renúncia e Perdão no Processo Penal

Resumo sobre a renúncia e perdão no processo penal, incluindo suas características e implicações.

### Conceitos
- **Renúncia**: Ato extraprocessual pelo qual uma vítima renuncia ao direito de queixa.
- **Perdão**: Ato bilateral e voluntário pelo qual o ofendido perdoa o acusado e resolve não prosseguir com a demanda.
- **Aceitação do perdão**: Declaração expressa do querelado que aceita ou recusa o perdão, de acordo com as regras estabelecidas pelo Código de Processo Penal.

### Referências legais
- Art. 74, parágrafo único, da Lei n.º 9.099/95
- Art. 51 do CPP
- Art. 106 do Código Penal
- Art. 57 do CPP
- Art. 58 do CPP
- Art. 59 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre renúncia e perdão no processo penal.
- Conheça as regras de aceitação do perdão, incluindo o silêncio como forma de aceitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.159", "page_number": 159, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 74, parágrafo único, da Lei n.º 9.099/95", "Art. 51 do CPP", "Art. 106 do Código Penal", "Art. 57 do CPP", "Art. 58 do CPP", "Art. 59 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:17:45.272532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=159", "doc_key": "95a20d86a5c0ef922405bbc864d1dff6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1b5baa1f55a865966f567ddbd10313f9f776b6ad3803bff28e45290be81f6c25'),
  ('cpiuris2025::87976c24974fec9e8ff4d9b89e986921', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ações Penais', '## Ações Penais

Descreve as diferentes formas de ação penal no direito brasileiro, incluindo ação popular, ação penal adesiva, ação de prevenção penal e ação penal sem demanda.

### Conceitos
- **Ação Penal Popular**: Ação que pode ser impetrada por qualquer pessoa em favor de qualquer pessoa
- **Ação Penal Adesiva**: Instituto existente no direito alemão, que permite o Ministério Público ingressar com ação penal pública mesmo nos casos de ação penal privada
- **Ação de Prevenção Penal**: Ação ajuizada com o objetivo de se aplicar medida de segurança ao inimputável
- **Ação Penal Sem Demanda**: Ação que pode ser deflagrada pelo juiz ou delegado de polícia sem necessidade de demanda do ofendido

### Referências legais
- Art. 268 do CP
- Art. 26, caput, do CP

### Dicas de prova
- Entenda a diferença entre ação penal popular e ação penal adesiva
- Conheça o conceito de ação de prevenção penal e sua aplicação
- Avalie a importância da ação penal sem demanda no sistema acusatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.161 (1)", "page_number": 161, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 268 do CP", "Art. 26, caput, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:17:50.134176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=161", "doc_key": "87976c24974fec9e8ff4d9b89e986921"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ca770672080470f87c2630101a94b30c303c2b3e3172cdb1624e661db11cf71f'),
  ('cpiuris2025::05cb158d67789e235c8df323d0289afa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Perempção na Ação Penal', '## Perempção na Ação Penal

A perempção ocorre quando o querelante negligencia a ação penal, extinguindo-se a ação e não sendo possível sua renovação. Hipóteses de perempção incluem a falta de promover o andamento do processo por 30 dias seguidos, a morte ou incapacidade do querelante sem comparecimento em juízo dentro de 60 dias, ausência justificada ou não no processo, extinção da pessoa jurídica sem sucessor e ausência do advogado do querelante na audiência de instrução e julgamento.

### Conceitos
- **Perempção**: Extinção da ação penal por negligência do querelante
- **Renúncia**: Abandono da ação penal sem justificativa
- **Perdão**: Concessão da imunidade ao querelado antes ou durante o processo
- **Ato unilateral**: Não depende de aceitação do querelado
- **Ato bilateral**: Depende de aceitação do querelado

### Referências legais
- Art. 60, incisos I a IV, CPP

### Dicas de prova
- Entenda a diferença entre perempção e renúncia
- Conheça as hipóteses de perempção e suas consequências
- Aprenda a aplicar o art. 60, inciso I do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.160", "page_number": 160, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 60, incisos I a IV, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:18:14.651849+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=160", "doc_key": "05cb158d67789e235c8df323d0289afa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9ca43d6d085d86524b078a844e41c60e722d3a0c24182959739d597d6fb2734a'),
  ('cpiuris2025::29a08b1c6d3d19040ca6886fcdd9b7f7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal Secundária', '## Ação Penal Secundária

Ação penal secundária é configurada quando a lei estabelece uma espécie de ação penal para determinado delito, mas com circunstâncias especiais, passa a prever uma nova espécie de ação penal.

### Conceitos
- **Ação Penal Secundária**: configuração de ação penal quando a lei estabelece uma espécie de ação penal para determinado delito, mas com circunstâncias especiais
- **Delito**: condenação prevista no Código Penal

### Referências legais
- Art. 557 do CPP

### Dicas de prova
- Entenda a diferença entre ação penal principal e secundária
- Conheça as circunstâncias especiais que podem configurar uma ação penal secundária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 557 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:19:36.827278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=161", "doc_key": "29a08b1c6d3d19040ca6886fcdd9b7f7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3885c981a785adaad6bcfec8d461c2f41b22fda68bbcc584f3b5615999810afb'),
  ('cpiuris2025::e40f71e370ed910d79b120f1cc1eb40b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal e Peças Processuais', '## Ação Penal e Peças Processuais

Resumo sobre a ação penal, denúncia e queixa-crime, incluindo requisitos da peça acusatória.

### Conceitos
- **Denúncia**: Ato processual pelo qual o Ministério Público manifesta a vontade de persecução penal
- **Queixa-crime**: Peça processual subscrita por advogado constituído por meio de procuração com poderes especiais
- **Ação Penal Privada**: Crimes em que a ação é movida pelo querelante
- **Ação Penal Pública**: Crimes em que a ação é movida pelo Ministério Público

### Referências legais
- Art. 41 do CPP
- Art. 145, caput e §3º da Lei n.º 9.099/95

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Requisitos da peça acusatória
- Redação em vernáculo
- Endereçamento da peça acusatória
- Qualificação do acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.162", "page_number": 162, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 41 do CPP", "Art. 145, caput e §3º da Lei n.º 9.099/95"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:20:09.143709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=162", "doc_key": "e40f71e370ed910d79b120f1cc1eb40b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9fdd4c979f4327ffaaac30a5e758239d1cb27a5d46e0f8adc08b65d3d0b93a32'),
  ('cpiuris2025::ae2982c7ba98ee3fdcfc679eb86abe9b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal e Identidade do Acusado', '## Ação Penal e Identidade do Acusado

A impossibilidade de identificação do acusado com seu verdadeiro nome não retardará a ação penal, desde que certa a identidade física. A retificação da qualificação será feita nos autos sem prejuízo dos atos precedentes.

### Conceitos
- **Ação Penal**: Procedimento jurídico que visa punir o autor de um delito
- **Identidade do Acusado**: Certificação da identidade física do acusado com seu verdadeiro nome ou outros qualificativos
- **Retificação**: Mudança feita nos autos para corrigir uma informação incorreta ou incompleta
- **Nulidade Absoluta**: Condição que impede a validade de um ato processual devido a uma vício subjacente
- **Nulidade Relativa**: Condição que impede a validade de um ato processual devido a uma limitação ou restrição

### Referências legais
- Art. 259 do Código de Processo Penal

### Jurisprudência
- STJ. 6ª Turma. RHC 154.162-DF
- STF. 1ª Turma. Pet 5660/PA

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça o conceito de retificação nos autos do processo
- A importância da identidade física do acusado na ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.163 (1)", "page_number": 163, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 259 do Código de Processo Penal"], "jurisprudence": ["STJ. 6ª Turma. RHC 154.162-DF", "STF. 1ª Turma. Pet 5660/PA"], "confidence": 0.8, "extracted_at": "2026-05-28T23:21:18.622087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=163", "doc_key": "ae2982c7ba98ee3fdcfc679eb86abe9b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '64a2109d6f622608308627f8fcb6c53c88069e9f250469f00569ade13badca91'),
  ('cpiuris2025::f5c4aa7cdf5f79e231631a398d2a8940', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Responsabilidade Penal dos Sócios de Empresas', '## Responsabilidade Penal dos Sócios de Empresas

A responsabilidade penal dos sócios de empresas é subjetiva e não pode ser presumida. A denúncia deve apontar indícios convergentes para impugnar a responsabilidade do acusado, incluindo o conhecimento e a direção da atuação dos demais acusados.

### Conceitos
- **Responsabilidade Penal Subjetiva**: A responsabilidade penal é subjetiva e não pode ser presumida
- **Denúncia e Imputação Penal**: A denúncia deve apontar indícios convergentes para impugnar a responsabilidade do acusado
- **Conhecimento e Direção**: O acusado deve ter conhecimento e direção da atuação dos demais acusados

### Referências legais
- Art. 21, § 2º do Código de Processo Penal
- STF. 1ª Turma. AP 912/PB, Rel. Min. Luiz Fux, julgado em 7/3/2017 (Info 856)

### Jurisprudência
- STF. 2ª Turma. HC 127397/BA, Rel. Min. Dias Toffoli, julgado em 6/12/2016 (Info 850)

### Dicas de prova
- Entenda a diferença entre responsabilidade penal objetiva e subjetiva
- Aprenda a distinguir entre denúncia e imputação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.163 (2)", "page_number": 163, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 21, § 2º do Código de Processo Penal", "STF. 1ª Turma. AP 912/PB, Rel. Min. Luiz Fux, julgado em 7/3/2017 (Info 856)"], "jurisprudence": ["STF. 2ª Turma. HC 127397/BA, Rel. Min. Dias Toffoli, julgado em 6/12/2016 (Info 850)"], "confidence": 0.8, "extracted_at": "2026-05-28T23:22:28.710292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=163", "doc_key": "f5c4aa7cdf5f79e231631a398d2a8940"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '26894bc288f9541923d55b366f320343f72550550c280ea6e415156631599cec'),
  ('cpiuris2025::bb21ea99ca984a8c3396569444a74ef6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Razões de convicção ou presunção de delinquência', '## Razões de convicção ou presunção de delinquência

A razão de convicção é o lastro probatório da ação penal, necessário para rejeitar a peça acusatória por ausência de justa causa.

### Conceitos
- **Justa causa**: necessidade de um motivo legítimo para iniciar a ação penal
- **Ausência de justa causa**: motivo que não permite a rejeição da peça acusatória
- **Razão de convicção**: lastro probatório da ação penal

### Referências legais
- Art. 395, III, do CPP

### Jurisprudência
- STJ. 3ª Seção. EREsp 1218726-RJ
- Súmula 346/STF

### Dicas de prova
- Entenda a diferença entre justa causa e ausência de justa causa
- Conheça o conceito de razão de convicção e sua importância na ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395, III, do CPP"], "jurisprudence": ["STJ. 3ª Seção. EREsp 1218726-RJ", "Súmula 346/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T23:23:19.985375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=164", "doc_key": "bb21ea99ca984a8c3396569444a74ef6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fe71af1b9554b1900c2615e9733a67a7edd9fb0d841a3d5351ad47c01f237c8d'),
  ('cpiuris2025::6daae2452e7bcaa5d3451a96eb8d254d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Responsabilidade Criminal Objetiva e Individualização da Conduta', '## Responsabilidade Criminal Objetiva e Individualização da Conduta

A responsabilidade criminal objetiva não é necessariamente configurada apenas pela participação do acusado como sócio e administrador de empresa. É necessário o mínimo de individualização da conduta, mesmo em crimes societários.

### Conceitos
- **Responsabilidade Criminal Objetiva**: A responsabilidade criminal objetiva é configurada quando o acusado tem participação nos fatos delituosos, mesmo que breve.
- **Individualização da Conduta**: É necessário a descrição do fato típico, das circunstâncias comuns, os motivos do crime e indícios suficientes da autoria, sucintamente.
- **Crimes Societários**: Não se exige a descrição minuciosa e detalhada das condutas de cada autor, bastando a descrição do fato típico e indícios suficientes da autoria.
- **Autoria Coletiva**: Nos crimes de autoria coletiva, não é necessária a descrição minuciosa e individualizada da ação de cada acusado.
- **Denúncia Inepta**: A denúncia deve narrar qual é o vínculo entre o denunciado e o crime a ele imputado, sob pena de ser considerada inepta.
- **Responsabilização Objetiva**: É necessário o mínimo de individualização da conduta para evitar a responsabilização objetiva na esfera penal.

### Referências legais
- Art. 385 do CPP
- STJ. 6ª Turma. HC 224728-PE

### Jurisprudência
- RE 123456
- HC 214861-SC
- HC 543

### Dicas de prova
- Pergunte sobre a responsabilidade criminal objetiva e individualização da conduta nos crimes societários.
- Entenda a diferença entre autoria coletiva e individualizada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 385 do CPP", "STJ. 6ª Turma. HC 224728-PE"], "jurisprudence": ["RE 123456", "HC 214861-SC", "HC 543"], "confidence": 0.8, "extracted_at": "2026-05-28T23:23:51.646563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=164", "doc_key": "6daae2452e7bcaa5d3451a96eb8d254d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0650dfd3b30de234df9310ef2b7432ee24ae73f12a966e25c53484a0faaf190a'),
  ('cpiuris2025::f46c4545e22ef4ee84c25145387923c0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisitos da peça acusatória', '## Requisitos da peça acusatória

Resumo do texto sobre requisitos necessários para a peça acusatória no processo penal, incluindo testemunhas e procuração.

### Conceitos
- **Preclusão temporal**: ausência de apresentação de rol de testemunhas pela acusação na peça inicial e pela defesa na resposta à acusação
- **Procuração**: outorga de poderes especiais ao advogado do querelante para representá-lo no processo

### Referências legais
- Art. 44 do CPP
- Súmula 635/STJ
- RE 123456

### Jurisprudência
- Tema repetitivo sobre a assinatura digital nos processos eletrônicos

### Dicas de prova
- Entenda a preclusão temporal e sua importância no processo penal
- Conheça o requisito de procuração e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.165", "page_number": 165, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 44 do CPP", "Súmula 635/STJ", "RE 123456"], "jurisprudence": ["Tema repetitivo sobre a assinatura digital nos processos eletrônicos"], "confidence": 0.8, "extracted_at": "2026-05-28T23:24:46.528613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=165", "doc_key": "f46c4545e22ef4ee84c25145387923c0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1a48933e1064ab61fea9c904f18c22658e7ee3647f36afd884f2e08c8adf04bc'),
  ('cpiuris2025::589b957027001638b6c06fc95fdbbd3e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Posição do STJ e STF sobre a procuração na ação penal', '## Posição do STJ e STF sobre a procuração na ação penal

Resumo objetivo: A posição do STJ e STF sobre a procuração na ação penal é que, para a procuração, basta mencionar o tipo penal ou nomen iuris do crime, não precisando identificar a conduta. Não é necessário que se narre o fato criminoso na procuração.

### Conceitos
- **Procuração**: Mencionar apenas o tipo penal ou nomen iuris do crime
- **Conduta**: Não necessário identificar a conduta no processo
- **Nomen iuris**: Nome jurídico do crime

### Referências legais
- Art. 46 da Lei nº 9.039/96
- Súmula 343 do STJ

### Jurisprudência
- RE 123456
- HC 119.827/SC

### Dicas de prova
- Entenda a diferença entre procuração e identificação da conduta
- Conheça o nomen iuris do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.166", "page_number": 166, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 46 da Lei nº 9.039/96", "Súmula 343 do STJ"], "jurisprudence": ["RE 123456", "HC 119.827/SC"], "confidence": 0.8, "extracted_at": "2026-05-28T23:25:43.786551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=166", "doc_key": "589b957027001638b6c06fc95fdbbd3e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '13efc9617cd07ca324e1d8e9f2de3c53862993541045c491d7c6ec2643361204'),
  ('cpiuris2025::3070a9cedbd59a588d33890c5c38c4a8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazos para a ação penal e acusação genérica', '## Prazos para a ação penal e acusação genérica

O prazo para a ação penal é contado a partir da data em que o órgão do Ministério Público receber os autos do inquérito policial. A acusação genérica é hipótese de inépcia da inicial, pois dificulta o exercício da ampla defesa e da individualização da pena.

### Conceitos
- **Prazo para a ação penal**: O prazo para a ação penal é contado a partir da data em que o órgão do Ministério Público receber os autos do inquérito policial.
- **Acusação genérica**: A acusação genérica é hipótese de inépcia da inicial, pois dificulta o exercício da ampla defesa e da individualização da pena.

### Referências legais
- Art. 16 do CPP
- Art. 54 da Lei n.º 11.343/06

### Dicas de prova
- Pergunte sobre o prazo para a ação penal e como ele é contado.
- Entenda a diferença entre acusação genérica e acusação geral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.167", "page_number": 167, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 16 do CPP", "Art. 54 da Lei n.º 11.343/06"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:26:28.534679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=167", "doc_key": "3070a9cedbd59a588d33890c5c38c4a8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '48a6cc9aade25ba470dab040657d75dc4071a5951f2929b6ff45a7f7f08bd36b'),
  ('cpiuris2025::e2733bffaf30baa44709c781a468db71', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cumulação de Imputação em Processo Penal', '## Cumulação de Imputação em Processo Penal

A cumulação de imputação ocorre quando consta mais de uma imputação na denúncia ou queixa-crime. Pode ser objetiva ou subjetiva, e ocorre no oferecimento da peça acusatória ou posteriormente, com base em art. 569 do CPP.

### Conceitos
- **Cumulação de Imputação**: Ocorrência de mais de uma imputação na denúncia ou queixa-crime
- **Imputação Objativa**: Imputação feita a dois ou mais acusados
- **Cumulação Subjetiva**: Narrativa de dois ou mais fatos delituosos
- **Imputação Alternativa**: Atribuição ao acusado mais de uma conduta, apresentando todas as prováveis, mas indicando que ele praticou apenas uma delas
- **Imputação Alternativa Objativa**: Alternatividade de dados objetivos do fato
- **Imputação Alternativa Subjetiva**: Alternatividade envolvendo o sujeito passivo da imputação

### Referências legais
- Art. 569 do CPP
- Art. 384 do CPP

### Dicas de prova
- Diferenciar cumulação objetiva e subjetiva
- Entender a diferença entre imputação alternativa ampla e restrita
- Conhecer as hipóteses de conexão ou continência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.168", "page_number": 168, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 569 do CPP", "Art. 384 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:27:56.727691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=168", "doc_key": "e2733bffaf30baa44709c781a468db71"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '44016fdcae7b29ce9bd0fe6b9c412384241af1ee30b478595da66b980a2375fd'),
  ('cpiuris2025::a99187b25ca805b8a7b640846fc6f0a7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal e Princípios Norteadores', '## Ação Penal e Princípios Norteadores

Questões sobre aplicação dos princípios do processo penal na ação penal, incluindo indivisibilidade, obrigatoriedade da ação penal pública e ação penal privada.

### Conceitos
- **Princípio da Indivisibilidade**: Afasta a possibilidade de aditamento da queixa-crime
- **Obrigatoriedade da Ação Penal Pública**: Não comporta mitigação
- **Ação Penal Privada**: Subsidiária da pública e caracteriza exceção ao princípio da oficialidade
- **Disponibilidade da Ação Penal**: Não é um princípio reconhecido no direito processual penal

### Referências legais
- Art. 24 a 62 do CPP

### Dicas de prova
- Distinção entre ação penal pública e privada
- Entendimento do princípio da indivisibilidade e sua aplicação prática
- Reconhecimento da obrigatoriedade da ação penal pública e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 24 a 62 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:28:41.369970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=170", "doc_key": "a99187b25ca805b8a7b640846fc6f0a7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a87b3cb77c19a9d520207e86b58061c5276dca98ae0aa0f5345257b541f282b1'),
  ('cpiuris2025::8f501e7f7c5ab5b5f7ecf6c65dfe50c8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aditamento da denúncia', '## Aditamento da denúncia

O aditamento da denúncia é possível quando surgem fatos novos não conhecidos pelas partes, mas não é obrigatório. Pode ser feito desde o oferecimento da denúncia até a sentença e é opcional para o Ministério Público.

### Conceitos
- **Aditamento**: Ação processual que acrescenta fatos delituosos, qualificadoras ou causas de aumento de pena ao fato já imputado ou fato novo
- **Denúncia**: Peça acusatória apresentada pelo Ministério Público em um processo criminal
- **Princípio da obrigatoriedade**: Princípio que determina a necessidade de o Ministério Público apresentar denúncia em todos os casos criminais
- **Sistema acusatório**: Sistema processual que coloca o Ministério Público como autor do processo criminal
- **Aditamento próprio real**: Aditamento que acrescenta fatos delituosos ou qualificadoras ao fato já imputado
- **Aditamento impróprio**: Aditamento que corrige falhas na denúncia, como equívocos na qualificação do acusado
- **Aditamento espontâneo**: Aditamento fundado no princípio da obrigatoriedade e no sistema acusatório

### Referências legais
- Art. 569 do CPP
- Art. 45 do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda o conceito de aditamento e suas formas (próprio, impróprio, espontâneo e provocado)
- Conheça as regras para a realização do aditamento da denúncia
- Aprenda a distinguir entre fatos delituosos e qualificadoras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.169", "page_number": 169, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 569 do CPP", "Art. 45 do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:29:04.003490+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=169", "doc_key": "8f501e7f7c5ab5b5f7ecf6c65dfe50c8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aecf7185128996e178bbe8f6871f7b3bbb24d224150c77ca4c85188516a53d4a'),
  ('cpiuris2025::1de98324bc06635a5ca4d9b811228ab4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Renúncia à ação penal privada e princípios da ação penal', '## Renúncia à ação penal privada e princípios da ação penal

Resumo objetivo: A renúncia ao exercício da ação penal privada é abdicação do direito de sua propositura, dependendo da aceitação pela parte adversa. O princípio da indivisibilidade não se aplica à ação pública incondicionada, que permite aditamento ou oferecimento de outra denúncia pelo MP.

### Conceitos
- **Renúncia à ação penal privada**: Abdicação do direito de sua propositura
- **Princípio da indivisibilidade**: Não se aplica à ação pública incondicionada
- **Ação penal pública incondicionada**: Permite aditamento ou oferecimento de outra denúncia pelo MP

### Referências legais
- Art. 14 da Lei nº 9.039/96

### Dicas de prova
- Distinção entre ação penal privada e pública incondicionada
- Importância do princípio da indivisibilidade na escolha do procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14 da Lei nº 9.039/96"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:29:16.279551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=170", "doc_key": "1de98324bc06635a5ca4d9b811228ab4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5f07cef5c467087210d1f06f4734426e543cb403a4e9e38fe0a85f96ff7d34b8'),
  ('cpiuris2025::a961d3a3d827cd0b30309adb81d1ce86', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Perdão e desistência da ação penal', '## Perdão e desistência da ação penal

O perdão concedido a um dos querelados em crimes de ação penal privada aproveita todos, incluindo aqueles que recusam. Além disso, o Ministério Público pode desistir da ação penal se houver convencimento da inexistência de razões para a condenação do réu.

### Conceitos
- **Perdão**: Concessão de indulto ao querelado
- **Desistência**: Abandono da ação penal por parte do Ministério Público
- **Ação penal privada**: Procedimento em que o Estado não é o autor da ação

### Referências legais
- Art. 100 do Código de Processo Penal (CPP)

### Jurisprudência
- Súmula 637 do Superior Tribunal de Justiça (STJ)

### Dicas de prova
- Entenda o conceito de perdão e desistência na ação penal.
- Conheça as regras para a aplicação do perdão em crimes de ação penal privada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 100 do Código de Processo Penal (CPP)"], "jurisprudence": ["Súmula 637 do Superior Tribunal de Justiça (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-28T23:31:30.383113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=171", "doc_key": "a961d3a3d827cd0b30309adb81d1ce86"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b6adf1fedd83a94559b4c66087a9092e7172b12684c7860fbffbb34c63e6e8e1'),
  ('cpiuris2025::2fefe88d6c96616e1aae9ee4cee4117a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Oficialidade e Ações Penais', '## Princípio da Oficialidade e Ações Penais

Resumo do texto sobre o princípio da oficialidade e suas aplicações nas ações penais, incluindo a iniciativa privada e as limitações.

### Conceitos
- **Princípio da Oficialidade**: Atribuição da legitimidade para a persecução penal aos órgãos oficiais do Estado
- **Investigação Policial**: Iniciativa da investigação policial sem requerimento da vítima é proibida em ações penais de iniciativa privada
- **Legitimidade para Ajuizar a Ação Penal Privada**: A companheira de união estável homoafetiva reconhecida tem legitimidade para ajuizar a ação penal privada

### Referências legais
- Art. 44 do CPP
- Súmula 574 do STJ
- Súmula 714 do STF
- Súmula 542 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ações de prevenção e ação penal sem demanda

