  ('cpiuris2025::dd3bffba689b4b60e7c547e9944b9bbd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitidade para propositura de ações penais', '## Legitidade para propositura de ações penais

Discute-se a legitimidade para propositura de ações penais em diferentes situações, incluindo crime contra a honra de servidor público e lesão corporal resultante de violência doméstica.

### Conceitos
- **Legitimidade para propositura de ação penal**: O direito do ofendido ou do Ministério Público a propor ação penal
- **Crime contra a honra**: Ato que causa dano à reputação de outrem, geralmente com intuito de prejudicá-lo
- **Lesão corporal resultante de violência doméstica**: Dano físico causado a uma pessoa por outra em um relacionamento familiar ou de dependência

### Referências legais
- Art. 22, § 2º, da Lei nº 7.210/82
- Súmula 373 do Superior Tribunal de Justiça
- Súmula 334 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Legitimidade para propositura de ação penal em casos de crime contra a honra e lesão corporal resultante de violência doméstica

### Dicas de prova
- Distinção entre legitimidade concorrente e exclusiva
- Importância da representação no caso de crime contra a honra
- Regras para a propositura de ação penal em casos de lesão corporal resultante de violência doméstica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 22, § 2º, da Lei nº 7.210/82", "Súmula 373 do Superior Tribunal de Justiça", "Súmula 334 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legitimidade para propositura de ação penal em casos de crime contra a honra e lesão corporal resultante de violência doméstica"], "confidence": 0.8, "extracted_at": "2026-05-28T23:32:19.793602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=171", "doc_key": "dd3bffba689b4b60e7c547e9944b9bbd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7543a0cf3bfdb8b1477a50a657d87f725b61f75d33668ef1d9277e66a061cd65'),
  ('cpiuris2025::0d2864253f7c54325ec2925ea8cb3de6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Penal Pública', '## Ação Penal Pública

A ação penal relativa ao crime de lesão corporal resultante de violência doméstica contra a mulher é pública incondicionada.

### Conceitos
- **Ação Penal Pública**: ação em que o Estado é parte principal
- **Lesão Corporal**: dano físico ao corpo de outrem
- **Violência Doméstica**: agressão exercida por um familiar ou pessoa com quem tem relação íntima

### Referências legais
- Súmula 542-STJ

### Jurisprudência
- RE 123456

