  ('cpiuris2025::e4f7f3fca3f4131d4cb24df998133c42', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto', '## Ação Civil Ex Delicto

A ação civil ex delicto tem como objetivo reparar o dano causado pela infração penal, além da pretensão punitiva do Estado.

### Conceitos
- **Infração Penal**: Atividade ilegal que cometeu um ato ilícito
- **Dano**: Prejuízo causado a outrem pela infração penal
- **Ação Civil Ex Delicto**: Procedimento que busca reparar o dano causado pela infração penal
- **Sistema da Independência**: O sistema adotado pelo CPP, onde as duas ações podem ser propostas independentemente

### Referências legais
- Art. 186 do Código Civil
- Art. 927 do Código Civil
- Art. 91, I do Código Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ação penal e ação civil ex delicto
