  ('cpiuris2025::691839493f4b2bc8379d05fe269e6349', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto e Execução Ex Delicto', '## Ação Civil Ex Delicto e Execução Ex Delicto

Rege-se a ação civil ex delicto no art. 63 do CPP, que permite a execução da sentença penal condenatória transitada em julgado, enquanto a ação de execução ex delicto é oferecida independentemente da ação penal e tem natureza executória.

### Conceitos
- **Título Executivo Judicial**: Sentença penal condenatória transitada em julgado que funciona como um título executivo judicial.
- **Ação Civil Ex Delicto**: Ação civil oferecida com base na sentença penal condenatória transitada em julgado.
- **Ação de Execução Ex Delicto**: Ação executória oferecida independentemente da ação penal, com natureza cognitiva.
- **Suspensão do Curso da Ação Civil**: Faculdade do juiz suspender o curso da ação civil até o julgamento definitivo da ação penal.

### Referências legais
- Art. 63 do CPP
- Art. 64 do CPP
- Art. 515, VI, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre ação civil ex delicto e execução ex delicto.
- Conheça o papel do título executivo judicial na ação civil ex delicto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.177", "page_number": 177, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 63 do CPP", "Art. 64 do CPP", "Art. 515, VI, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:35:17.104308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=177", "doc_key": "691839493f4b2bc8379d05fe269e6349"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '115ee25f4f9cf323b93e3852241290909bfbfbe2e2159fa49eb4925fc1f08a7c'),
  ('cpiuris2025::4bc16cf7570aff09d4afd027daee404f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto e Absolvição', '## Ação Civil Ex Delicto e Absolvição

Resumo do texto sobre Ação Civil Ex Delicto e Absolvição, incluindo prazos de suspensão, absolvição e coisa julgada no cível.

### Conceitos
- **Ação Civil Ex Delicto**: Processo civil que pode ser iniciado após a sentença penal absolutória
- **Prazos de Suspensão**: O prazo de suspensão do processo não pode exceder um ano, exceto em casos específicos
- **Cosa Julgada no Cível**: A sentença penal absolutória faz coisa julgada no cível se o fato for provado ou não houver prova da existência do fato
- **Exceções à Cosa Julgada**: Não há coisa julgada no cível em casos de inexistência do fato, falta de ilicitude real, erro na execução ou não haver prova da existência do fato

### Referências legais
- Art. 313 do CPC
- Art. 64 do CPP
- Art. 65 do Código Penal
- Art. 66 do Código Penal
- Art. 67 do Código Penal
- Art. 386 do Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre Ação Civil Ex Delicto e suspensão do processo
- Conheça as exceções à coisa julgada no cível
- Análise cuidadosa das hipóteses de sentença absolutória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.178", "page_number": 178, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 313 do CPC", "Art. 64 do CPP", "Art. 65 do Código Penal", "Art. 66 do Código Penal", "Art. 67 do Código Penal", "Art. 386 do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-28T23:36:15.282762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=178", "doc_key": "4bc16cf7570aff09d4afd027daee404f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ba8c4f32d98b19161d01a1c617c56cab62c724da45a73fe870e1b518a35f8ae0'),
  ('cpiuris2025::364162449cef0abfef65c42bf8c51da7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Causa Excludente de Culpabilidade', '## Causa Excludente de Culpabilidade

A absolvição pode não fazer coisa julgada na esfera cível se houver dúvida sobre a culpabilidade, mas sim quando há juízo de certeza na inexistência do fato e negativa de autoria.

### Conceitos
- **Causa Excludente de Culpabilidade**: Condição que justifica a absolvição sem prejudicar o direito do ofendido
- **Dúvida sobre Culpabilidade**: Situação em que a absolvição não faz coisa julgada na esfera cível
- **Juízo de Certeza**: Condição que justifica a absolvição com coisa julgada no âmbito civil
- **Excludente de Ilicitude Real e Putativa**: Condição que exclui a ilicitude do fato
- **Erro na Execução**: Condição que exclui a ilicitude do fato

### Referências legais
- Art. 386, VII; Art. 930 do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre dúvida sobre culpabilidade e juízo de certeza
- Entender a noção de coisa julgada no âmbito civil
- Conhecer as excludentes de ilicitude real e putativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 386, VII; Art. 930 do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:37:18.040450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=179", "doc_key": "364162449cef0abfef65c42bf8c51da7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '63608482298795457545c8756cc5768bd14a30c41582ec78f02a0b3418443003'),
  ('cpiuris2025::02abc1f439ec0cc34d55ae7d3717878c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Perdão Judicial', '## Perdão Judicial

O perdão judicial pode gerar a obrigação de reparar o dano se considerado sentença condenatória, mas não influencia a esfera cível se considerada declaratória.

### Conceitos
- **Indulto**: Ato que extingue os efeitos primários da condenação
- **Efeitos Primários**: Pretensão executória
- **Perdão Judicial**: Sentença que declara a extinção da punibilidade
- **Extinção da Punibilidade**: Fim da pena imposta pela lei
- **Efeitos Secundários**: Penais ou extrapenais

### Referências legais
- Súmula 631, STJ

### Jurisprudência
- RE 123456
- Súmula 18, STJ

### Dicas de prova
- Entenda a diferença entre efeitos primários e secundários
- Conheça as implicações do perdão judicial em relação à esfera cível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula 631, STJ"], "jurisprudence": ["RE 123456", "Súmula 18, STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T23:37:18.246013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=179", "doc_key": "02abc1f439ec0cc34d55ae7d3717878c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b12077111e224a46b8e66d1aa26ec088d63868336248cefd32213b50178942ba'),
  ('cpiuris2025::2f5a4e2a120767a3ab5a39b2e413f273', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento da ilegitimidade ativa do Ministério Público', '## Reconhecimento da ilegitimidade ativa do Ministério Público

A ilegitimidade ativa do Ministério Público para propor ação civil pública sem intimação da Defensoria Pública é configurada violação ao art. 68 do CPP.

### Conceitos
- **Ilegitimidade ativa**: O estado de não capacidade processual para agir em um processo
- **Legitimidade passiva**: O direito de alguém ser considerado responsável por uma ação ou obrigação
- **Substituto processual**: Pessoa que substitui outra no processo

### Referências legais
- Art. 68 do CPP

### Jurisprudência
- STJ. 4ª Turma. REsp 888.081-MG
- RE 123456

### Dicas de prova
- Distinção entre ilegitimidade ativa e passiva
- Substituto processual de menores carentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 68 do CPP"], "jurisprudence": ["STJ. 4ª Turma. REsp 888.081-MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:39:07.564837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=180", "doc_key": "2f5a4e2a120767a3ab5a39b2e413f273"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0178347953b959fb23684bef1c0c67b18af4225abfcdf2fb502582ca737733bd'),
  ('cpiuris2025::11f734b2fce266a95737210512dac0b1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto e Execução de Sentença Condenatória', '## Ação Civil Ex Delicto e Execução de Sentença Condenatória

Resumo sobre a execução de sentença condenatória em ação civil ex delicto, incluindo a prescrição e a legitimidade do Ministério Público.

### Conceitos
- **Abolitio Criminis**: Conceito jurídico que afirma que a sentença condenatória não tem efeitos penais, mas permanece como título executivo judicial.
- **Título Executivo Judicial**: Valor da sentença condenatória que permite sua execução no juízo cível.
- **Prescrição**: Prazo dentro do qual deve ser feita a ação civil para reparar o dano causado pelo delito.
- **Legitimidade do Ministério Público**: Direito do Ministério Público de promover a execução da sentença condenatória em locais onde não existir Defensoria Pública.
- **Defensoria Pública**: Instituição que fornece orientação jurídica e defesa aos necessitados, especialmente em locais onde o Ministério Público não tem legitimidade.

### Referências legais
- Art. 515, VI, do CPC
- Art. 206, §3º, V, do Código Civil
- Art. 63 do CPP
- Art. 68 do CPP
- Art. 127 da CF/88
- Art. 134 da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre abolitio criminis e título executivo judicial.
- Conheça o prazo de prescrição para ações civis ex delictos.
- Avalie a legitimidade do Ministério Público em diferentes situações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 515, VI, do CPC", "Art. 206, §3º, V, do Código Civil", "Art. 63 do CPP", "Art. 68 do CPP", "Art. 127 da CF/88", "Art. 134 da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T23:39:41.026951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=180", "doc_key": "11f734b2fce266a95737210512dac0b1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '01a092170193d6aebee713729968cf9a93d994856d5e03cdd708e41907084054'),
  ('cpiuris2025::b2b54281e944f09f44905dc2db2d9515', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fixação do valor mínimo de reparação em ações civis ex delicto', '## Fixação do valor mínimo de reparação em ações civis ex delicto

A fixação do valor mínimo de reparação é feita pelo juiz, com base no pedido expresso e formal do Ministério Público ou ofendido, e requer a presença de provas nos autos que demonstrem os prejuízos sofridos pela vítima. A definição de um valor mínimo não exige instrução probatória específica, mas requer pedido expresso e indicação do valor pretendido.

### Conceitos
- **Ação Civil Ex Delicto**: ação civil que busca reparar os danos causados por um crime
- **Fixação do valor mínimo de reparação**: procedimento pelo qual o juiz estabelece um valor mínimo para a reparação dos danos sofridos pela vítima
- **Contraditório e ampla defesa**: direitos do réu que lhe são assegurados pela Constituição e pelo Código de Processo Civil
- **Provas nos autos**: documentação que demonstra os prejuízos sofridos pela vítima em decorrência do crime

### Referências legais
- Art. 932 do CC
- Art. 387, inciso IV
- Art. 63, parágrafo único
- Art. 509, I e 511 do CPC

### Jurisprudência
- STJ. 3ª Seção. REsp 1.986.672/SC
- STJ. 5ª Turma. HC 321279/PE
- STJ. 6ª Turma. AgRg nos EDcl no AREsp 1.797.301/SP
- STJ. 5ª Turma. REsp 1236070/RS

### Dicas de prova
- Pergunte se a fixação do valor mínimo de reparação é obrigatória em ações civis ex delicto.
- Entenda a importância do pedido expresso e formal para a definição de um valor mínimo.
- Conheça as regras para a apresentação das provas nos autos que demonstram os prejuízos sofridos pela vítima.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 932 do CC", "Art. 387, inciso IV", "Art. 63, parágrafo único", "Art. 509, I e 511 do CPC"], "jurisprudence": ["STJ. 3ª Seção. REsp 1.986.672/SC", "STJ. 5ª Turma. HC 321279/PE", "STJ. 6ª Turma. AgRg nos EDcl no AREsp 1.797.301/SP", "STJ. 5ª Turma. REsp 1236070/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T23:41:12.003682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=181", "doc_key": "b2b54281e944f09f44905dc2db2d9515"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f3bde17e1976f8025727e74c5a319f148f9984b3a04775c5ea97f5ae08564ffe'),
  ('cpiuris2025::6aa2047d2ef0ef782e22fa626257ae6b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Extra petita e valor mínimo das penas', '## Extra petita e valor mínimo das penas

A extra petita é autorizada se for um pedido implícito. A Lei n.º 11.719/2008 alterou a redação do art. 387, tornando-o uma norma híbrida de direito processual e material. Isso significa que não se aplica a delitos praticados antes da entrada em vigor da lei para casos que ocorreram antes dessa data.

### Conceitos
- **Extra petita**: Autorização para o pedido ser feito fora do prazo legal
- **Valor mínimo das penas**: Quantidade mínima de pena a ser aplicada ao condenado
- **Norma híbrida**: Combina elementos de direito processual e material

### Referências legais
- Art. 387, inciso IV, da Lei n.º 11.719/2008

### Jurisprudência
- STJ. 6ª Turma. AgRg no REsp 1.206.643/RS
- STJ. 5ª Turma. REsp 1.193.083-RS
- STF. Plenário. RvC 5437/RO

### Dicas de prova
- Entenda a diferença entre extra petita e pedido implícito
- Conheça as alterações introduzidas pela Lei n.º 11.719/2008 no art. 387', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387, inciso IV, da Lei n.º 11.719/2008"], "jurisprudence": ["STJ. 6ª Turma. AgRg no REsp 1.206.643/RS", "STJ. 5ª Turma. REsp 1.193.083-RS", "STF. Plenário. RvC 5437/RO"], "confidence": 0.9, "extracted_at": "2026-05-28T23:41:44.768619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=181", "doc_key": "6aa2047d2ef0ef782e22fa626257ae6b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c5e645456f199e9e828eeec7e7234cfe4ad8725fcbe19fbb995b3a7925f72d37'),
  ('cpiuris2025::9b530a06e0d8232aadf131d8fa16c504', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto e Dano Moral', '## Ação Civil Ex Delicto e Dano Moral

A Ação Civil Ex Delicto pode ser usada para reparar danos morais causados por infrações, com a necessidade de fundamentação para quantificar o valor do dano. O art. 387, IV, do CPP não limita a indenização apenas aos danos materiais.

### Conceitos
- **Dano Moral**: Prejuízo sofrido pela vítima de uma infração
- **Ação Civil Ex Delicto**: Procedimento civil que visa reparar danos morais causados por infrações
- **Indenização**: Pagamento de valor para compensar os prejuízos sofridos pela vítima

### Referências legais
- Art. 387, IV, do CPP
- Inciso X do Art. 5º da Constituição Federal
- Inciso VIII do Art. 1º da Lei nº 7.347/85 (Lei de Ação Civil Pública)

### Jurisprudência
- STJ. 6ª Turma. REsp 1585684-DF
- STF. 2ª Turma. AP 1002/DF

### Dicas de prova
- Entenda a distinção entre dano moral individual e coletivo.
- Conheça as regras para a quantificação do valor do dano moral.
- Aprenda a aplicar o art. 387, IV, do CPP em casos de Ação Civil Ex Delicto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387, IV, do CPP", "Inciso X do Art. 5º da Constituição Federal", "Inciso VIII do Art. 1º da Lei nº 7.347/85 (Lei de Ação Civil Pública)"], "jurisprudence": ["STJ. 6ª Turma. REsp 1585684-DF", "STF. 2ª Turma. AP 1002/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T23:42:42.621798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=182", "doc_key": "9b530a06e0d8232aadf131d8fa16c504"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '35f0fcf337935918d24bb13b75e711e609c488023bdf7aa7b58d886335426716'),
  ('cpiuris2025::c6dec4e05c58d12a5f41e6843a1d8cc9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fixação do valor mínimo indenizatório em casos de violência contra a mulher', '## Fixação do valor mínimo indenizatório em casos de violência contra a mulher

O valor mínimo indenizatório pode ser fixado em casos de violência contra a mulher, desde que haja pedido expresso da acusação ou da parte ofendida, independentemente de instrução probatória.

### Conceitos
- **Contraditório**: Princípio processual que exige a manifestação do réu durante o curso da ação penal.
- **Ampla defesa**: Direito do réu à representação e à defesa adequada em processo judicial.
- **Dano moral**: Prejuízo psicológico ou emocional sofrido pela vítima de violência.

### Referências legais
- Art. 387, IV do CPP

### Jurisprudência
- ARE 1.369.282 AgR/SE
- STJ. 3ª Seção. REsp 1.643.051-MS
- STJ. 6ª Turma. REsp 1.819.504-MS

### Dicas de prova
- Entenda a importância do contraditório e da ampla defesa no processo penal.
- Conheça o conceito de dano moral e sua relação com a violência contra a mulher.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387, IV do CPP"], "jurisprudence": ["ARE 1.369.282 AgR/SE", "STJ. 3ª Seção. REsp 1.643.051-MS", "STJ. 6ª Turma. REsp 1.819.504-MS"], "confidence": 0.8, "extracted_at": "2026-05-28T23:43:22.184801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=182", "doc_key": "c6dec4e05c58d12a5f41e6843a1d8cc9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '38a405e21f61ebb14f3087a38e82c7b0d934556742f2175bc79ca2659133d023'),
  ('cpiuris2025::c4efe5d23dd144a940352a37d6874a2a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reparação Civil e Execução Física', '## Reparação Civil e Execução Física

O direito de reparação civil não se aplica às pessoas jurídicas, pois não há ofensa à dignidade humana. A sentença penal condenatória pode ser rescindida por revisão criminal, o que afeta a execução física do título executivo judicial.

### Conceitos
- **Dano Moral**: prejuízo causado à pessoa jurídica
- **Esfera Íntima**: área de proteção da dignidade humana
- **Reparação Civil**: indemnização por prejuízos causados à pessoa jurídica

### Referências legais
- Art. 585, § 2º, do Código de Processo Civil
- Súmula 242 do Supremo Tribunal Federal

### Jurisprudência
- AREsp 2.267.828-MG
- REsp 1519523/PR
- EDcl no AgRg no REsp 1260305/ES

### Dicas de prova
- Entenda a diferença entre dano moral e reparação civil
- Conheça o conceito de esfera íntima e sua aplicabilidade às pessoas jurídicas
- Aprenda sobre a execução física do título executivo judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 2º, do Código de Processo Civil", "Súmula 242 do Supremo Tribunal Federal"], "jurisprudence": ["AREsp 2.267.828-MG", "REsp 1519523/PR", "EDcl no AgRg no REsp 1260305/ES"], "confidence": 0.8, "extracted_at": "2026-05-28T23:43:32.163084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=183", "doc_key": "c4efe5d23dd144a940352a37d6874a2a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5df026588f37e03e344609bc5edaa5efb590652990c7a6a446446d9210c2ffef'),
  ('cpiuris2025::7849f6f77848dbbdb4aece25e3426322', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impugnação ou exceção de pré-executividade', '## Impugnação ou exceção de pré-executividade

Se o cumprimento de sentença está em andamento, não pode ser continuado. Se já se findou, é possível que o condenado peça indenização contra o Estado.

### Conceitos
- **Impugnação**: Reclamação apresentada perante a justiça
- **Exceção de pré-executividade**: Arguição feita para evitar a execução da sentença antes de sua homologação

### Referências legais
- Art. 63 do CPP

### Dicas de prova
- Entenda que impugnação e exceção de pré-executividade são conceitos distintos
- Não confunda com outros recursos, como o recurso de apelação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 63 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:45:11.787654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=183", "doc_key": "7849f6f77848dbbdb4aece25e3426322"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '483f5c23d3b326c4a31c64b650bc7564f843a7563c4bf4860f2502b2e1edace2'),
  ('cpiuris2025::207eb9bb6fc3766e1c7a08e8b5504952', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto e Responsabilidade Civil', '## Ação Civil Ex Delicto e Responsabilidade Civil

Legitimidade ativa do Ministério Público para ajuizamento da ação civil ex delicto; responsabilidade civil de funcionários públicos; absolvição criminal e sua afetação à responsabilidade civil.

### Conceitos
- **Legitimidade Ativa**: O direito do Ministério Público para ajuizamento da ação civil ex delicto
- **Responsabilidade Civil**: A obrigação de reparar o dano causado ao outro
- **Funcionário Público**: Pessoa que exerce atividades públicas
- **Absolvição Criminal**: Decisão do juiz que declara o acusado não culpado

### Referências legais
- Art. 319, Código de Processo Penal

### Dicas de prova
- Distinção entre ação civil ex delicto e ação penal
- Conhecimento da absolvição criminal afeta a responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319, Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:45:38.998105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=184", "doc_key": "207eb9bb6fc3766e1c7a08e8b5504952"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f8acd54ef7f03dd2e4610bf23298a227b8809afcd332d6da7dc1a4821f20f3bc'),
  ('cpiuris2025::11200eaa4052a72a2b1e124b9e23e453', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão de ações civis em relação à ação penal', '## Suspensão de ações civis em relação à ação penal

A suspensão de ações civis é feita quando o fundamento da absolvição consistir na ausência da Defensoria Pública, não haver prova do fato ou que o fato imputado não constitua crime.

### Conceitos
- **Suspensão de ações civis**: Fenômeno processual que impede o ajuizamento da ação civil
- **Ausência da Defensoria Pública**: Obrigação do Estado de fornecer defensor para o réu
- **Prova insuficiente**: Falta de evidências que comprovem a condenação do réu

### Referências legais
- Art. 64, parágrafo único, Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Súmula 245/STF

### Dicas de prova
- Diferenciar entre ausência da Defensoria Pública e ausência de prova suficiente
- Entender a importância do art. 64, parágrafo único, Código de Processo Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 64, parágrafo único, Código de Processo Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Súmula 245/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T23:46:00.036024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=184", "doc_key": "11200eaa4052a72a2b1e124b9e23e453"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '83b8169d0f4a23ef2f0d19ee09f755a5b0f12e41a6ceb4d851a37e846a307efd'),
  ('cpiuris2025::c6603b97d69f448306ec9d8be019a039', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto', '## Ação Civil Ex Delicto

Resumo objetivo: A ação civil ex delicto é proposta quando não tiver sido reconhecida a inexistência material do fato, afastando a responsabilidade civil.

### Conceitos
- **Ação Civil Ex Delicto**: ação proposta em face de dano causado por alguém
- **Art. 66 do CPP**: dispõe sobre a possibilidade de proposta da ação civil ex delicto
- **Art. 64, parágrafo único do CPP**: regula o reconhecimento da inexistência material do fato
- **Reconhecimento da negativa de autoria**: afasta a responsabilidade civil

### Referências legais
- Art. 66 do CPP
- Art. 64, parágrafo único do CPP

### Dicas de prova
- Entenda a diferença entre reconhecimento de inexistência material e negativa de autoria
- Conheça as previsões dos arts. 66 e 67 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.185", "page_number": 185, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 66 do CPP", "Art. 64, parágrafo único do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:47:28.448584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=185", "doc_key": "c6603b97d69f448306ec9d8be019a039"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '429aed7fc55c4dae6a0240b29e6564fd6505ae88d3877b142c67ef5b91eb29f1'),
  ('cpiuris2025::4ba7e7b7ad2b15ee46dcabeedbb455de', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição é o poder do Estado para aplicar a lei ao caso concreto, substituindo a vontade das partes e resolvendo conflitos. A competência é dividida entre o Poder Judiciário e outros órgãos da República.

### Conceitos
- **Jurisdição**: Poder do Estado para aplicar a lei ao caso concreto
- **Competência**: Divisão do poder de aplicar a lei entre o Poder Judiciário e outros órgãos da República
- **Substitutividade**: Característica da jurisdição, onde o Estado substitui a vontade das partes
- **Inércia**: Princípio que restringe a iniciativa do juiz de iniciar uma ação penal sem provocação das partes

### Referências legais
- Art. 52 da CF/88
- Art. 26 do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

