- Entenda a distinção entre jurisdição e competência
- Conheça as características da jurisdição, como substitutividade e inércia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.187", "page_number": 187, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 52 da CF/88", "Art. 26 do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:48:12.877779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=187", "doc_key": "4ba7e7b7ad2b15ee46dcabeedbb455de"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ce71c82cd6c13c83a4856f54e67b7505efb3bf805a05fd3b6c88e0d629b4c3c1'),
  ('cpiuris2025::9203166153ab1654c7cbc6c86c994229', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição tem como finalidade proteger a liberdade alheia e concretizar as normas abstratas do legislador, com caráter definitivo e imutável.

### Conceitos
- **Lide**: Conflito de interesses qualificado pela pretensão resistida
- **Atuação do direito**: Aplicar o direito ao caso concreto, restabelecendo-se a paz social violada pela infração cometida
- **Imutabilidade**: Caráter definitivo do provimento jurisdicional, salvo exceções
- **Juiz Natural**: Princípio constitucional que determina a competência do juiz de antemão, por normas previamente estabelecidas
- **Investidura**: Somente quem está legalmente investido pode exercer a jurisdição

### Referências legais
- Art. 5º, inciso LIII da CF/88
- Art. 129, I da CF/88

### Jurisprudência
- TÁVORA; ALENCAR

### Dicas de prova
- Entenda a noção de lide e sua aplicação no processo penal
- Conheça os princípios gerais da jurisdição, como o juiz natural e investidura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.188", "page_number": 188, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso LIII da CF/88", "Art. 129, I da CF/88"], "jurisprudence": ["TÁVORA; ALENCAR"], "confidence": 0.8, "extracted_at": "2026-05-28T23:48:35.185198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=188", "doc_key": "9203166153ab1654c7cbc6c86c994229"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fc385a9e1409ba500848a0dfe8e1d047b83d2116316605e44db70afee21aac26'),
  ('cpiuris2025::66239edeaf419d4ca14baeb6870d6c3e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Indelegabilidade e Competência Jurisdicional', '## Indelegabilidade e Competência Jurisdicional

A jurisdição é indelegável e não pode ser transferida a outrem, salvo em casos específicos previstos na lei. A competência jurisdicional é imutável e não pode ser delegada a outro magistrado.

### Conceitos
- **Indelegabilidade**: A jurisdição não pode ser transferida a outrem, salvo em casos específicos previstos na lei.
- **Competência Jurisdicional**: É imutável e não pode ser delegada a outro magistrado
- **Delegabilidade da Competência**: Pode ocorrer em casos específicos previstos na lei, como carta de ordem ou precatória.

### Referências legais
- Art. 5º, inciso XXXV, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Indelegabilidade e Competência Jurisdicional

### Dicas de prova
- Entenda a noção de indelegabilidade e competência jurisdicional.
- Conheça as exceções à regra geral, como carta de ordem ou precatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso XXXV, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Indelegabilidade e Competência Jurisdicional"], "confidence": 0.8, "extracted_at": "2026-05-28T23:49:51.279339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=189", "doc_key": "66239edeaf419d4ca14baeb6870d6c3e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '620a983b47fe26f5baa5b0c25397cb15fa4f7d88682fe984ad898e0d18d41c62'),
  ('cpiuris2025::dbb89256f969d4bf853188a366dcd6dd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Irrecusabilidade e Unidade da Jurisdição', '## Irrecusabilidade e Unidade da Jurisdição

A jurisdição é uma e indivisível, salvo em casos de impedimento ou suspeição do magistrado. As partes não podem recusar a atuação de um juiz, exceto nesses casos específicos.

### Conceitos
- **Irrecusabilidade**: A impossibilidade para as partes recusar a atuação de um juiz, salvo em casos de impedimento ou suspeição.
- **Unidade da Jurisdição**: A jurisdição é uma e indivisível, diferenciando-se apenas na sua aplicação e grau de especialização.
- **Impedimento**: O estado em que o juiz não pode atuar devido a uma causa específica.
- **Suspeição**: A situação em que o juiz não pode atuar devido a um motivo específico.

### Referências legais
- Art. 5º, LIV da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre impedimento e suspeição.
- Conheça a definição de unidade da jurisdição e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:50:27.448717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=189", "doc_key": "dbb89256f969d4bf853188a366dcd6dd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c0fdd1fa1d9a653d89c6ac6ad2840f868dc1324c4d325901556a84b9753232d6'),
  ('cpiuris2025::c06e243650126b0cf45520a64bbd7caa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Jurisdição', '## Competência e Jurisdição

A competência é a delimitação da jurisdição, ou seja, o espaço dentro do qual pode determinada autoridade judiciária aplicar o direito aos litígios que lhe forem apresentados. A competência deve ser partilhada entre diversos órgãos jurisdicionais.

### Conceitos
- **Competência ratione materiae**: A competência fixada em razão da natureza da infração penal praticada.
- **Competência ratione funcionae ou personae**: A competência determinada em razão das funções por elas desempenhadas.
- **Competência ratione loci**: A competência determinada em razão de critérios territoriais, objetiva identificar o juízo territorialmente competente.
- **Competência formal**: A competência fixada nos atos processuais.

### Referências legais
- Art. 69, inciso III do CPP
- Art. 102, inciso I, alínea b da CF/88

### Jurisprudência
- TÁVORA; ALENCAR
- LIMA, 2019, p. 351

### Dicas de prova
- Entenda a distinção entre competência ratione materiae e ratione funcionae.
- Conheça as espécies de competência (ratione materiae, ratione funcionae, ratione loci e formal).
- Aprenda a aplicar os critérios de competência para determinar o juízo territorialmente competente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 69, inciso III do CPP", "Art. 102, inciso I, alínea b da CF/88"], "jurisprudence": ["TÁVORA; ALENCAR", "LIMA, 2019, p. 351"], "confidence": 0.8, "extracted_at": "2026-05-28T23:51:24.532012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=190", "doc_key": "c06e243650126b0cf45520a64bbd7caa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bda1d25fedfe463fc6e7dce590b83d1bfa90a89c8b868a29775bab11c1ab2a31'),
  ('cpiuris2025::837ad5a9041938d57a4bb29c4df80cd0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Funcional no Processo', '## Competência Funcional no Processo

A competência funcional é fixada pela distribuição legal das funções dos julgadores ao longo do processo, subdividida em três espécies: por fase, por objeto e por procedimento.

### Conceitos
- **Competência Funcional**: A competência que se refere à distribuição legal das funções dos julgadores ao longo do processo.
- **Fase do Processo**: Uma parte do processo, caracterizada por um determinado objetivo ou questão a ser resolvida.
- **Órgão Jurisdicional**: A entidade responsável pela aplicação da lei e resolve de questões específicas no processo.

### Referências legais
- Art. 65 da Lei de Execuções Penais
- Art. 66 da Lei de Execuções Penais

### Dicas de prova
- Entenda a distinção entre competência funcional por fase e por objeto.
- Conheça as diferentes espécies de competência funcional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 65 da Lei de Execuções Penais", "Art. 66 da Lei de Execuções Penais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:52:00.444066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=190", "doc_key": "837ad5a9041938d57a4bb29c4df80cd0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '75a947203e0d9a105120f855c192a1ada61189c6124661cc975d9e13056dda5a'),
  ('cpiuris2025::360ac1fb2407f1888998bdb58353a1c5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Jurisdicional', '## Competência Jurisdicional

A competência jurisdicional é dividida em absoluta e relativa, com espécies como competência em razão da matéria, por prerrogativa de função e competência funcional, além de competências ratione loci, por prevenção, distribuição e conexão/continência.

### Conceitos
- **Competência Absoluta**: Predomina o interesse público
- **Competência Relativa**: Predomina o interesse das partes
- **Competência em Razão da Matéria**: Ração material
- **Competência por Prerrogativa de Função**: Ração pessoal ou funcional
- **Competência Funcional**: Competência por grau de jurisdição
- **Competência Ratione Loci**: Em razão do local da infração ou do domicílio/residência do réu
- **Competência por Prevenção**: Súmula nº 706 do STF
- **Competência por Distribuição**: Competência pela ordem em que os processos são distribuídos

### Referências legais
- Art. 109 da LBP
- Súmula nº 706 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Jurisdicional

### Dicas de prova
- Entenda a distinção entre competência absoluta e relativa
- Conheça as espécies de competência em razão da matéria, por prerrogativa de função e competência funcional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.191", "page_number": 191, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da LBP", "Súmula nº 706 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Jurisdicional"], "confidence": 0.8, "extracted_at": "2026-05-28T23:53:31.237976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=191", "doc_key": "360ac1fb2407f1888998bdb58353a1c5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ed6effacbd35e88da3d7733e34a086244abe53a21e889accdf7111094abdc992'),
  ('cpiuris2025::532785249912bfe622787971292e0870', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompetência no Processo Penal', '## Incompetência no Processo Penal

A incompetência pode ser absoluta ou relativa. A competência absoluta é reconhecida pelo juiz a qualquer momento, inclusive após o trânsito em julgado de sentença penal condonatória ou absolutória imprópria. Já a competência relativa deve ser arguida pela parte no momento processual adequado para tanto.

### Conceitos
- **Competência Absoluta**: Reconhecida pelo juiz a qualquer momento, inclusive após o trânsito em julgado de sentença penal condonatória ou absolutória imprópria
- **Competência Relativa**: Deve ser arguida pela parte no momento processual adequado para tanto
- **Exceção de Incompetência**: Veicular a incompetência absoluta e relativa, embora exista divergência doutrinária

### Referências legais
- Art. 567 do CPP
- Súmula nº 33 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre competência absoluta e relativa
- Conhecer a regra da exceção de incompetência
- Entender as consequências do reconhecimento da incompetência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 567 do CPP", "Súmula nº 33 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:53:50.115024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=192", "doc_key": "532785249912bfe622787971292e0870"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1ba4b9a15db706ddf240a6b4450092db4a2849bbcd3581b7d9c590001f91345f'),
  ('cpiuris2025::7a17119a9221fa801ee2d2222017358d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompetência do Juízo e Ratificação dos Atos Decisórios', '## Incompetência do Juízo e Ratificação dos Atos Decisórios

A incompetência do juízo anula apenas os atos decisórios, permitindo a ratificação desses atos no juízo competente.

### Conceitos
- **Incompetência**: O estado jurídico em que o juiz não tem competência para processar e julgar uma causa.
- **Atos Decisórios**: Decisões proferidas pelo juiz durante o processo.
- **Ratificação**: A ação de reconhecer a validade de um ato que deveria não ter sido produzido ou que foi produzido em falta de competência.

### Referências legais
- Art. 109, § 3º, do CPC/2015
- Súmula 242 do STF

### Jurisprudência
- HC nº 83.006/SP
- RE 123456

### Dicas de prova
- Entenda a diferença entre incompetência absoluta e relativa.
- Conheça o conceito de ratificação dos atos decisórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 3º, do CPC/2015", "Súmula 242 do STF"], "jurisprudence": ["HC nº 83.006/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T23:54:01.800263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=192", "doc_key": "7a17119a9221fa801ee2d2222017358d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9aae08d66052fd2725a0416fff86bc229524ff3bb1ebc3b20a03e5ec1ca1133a'),
  ('cpiuris2025::9473345c986813c7f6307068b7a7283f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Absoluta e Relativa', '## Competência Absoluta e Relativa

Resumo das principais características das competências absoluta e relativa, destacando a possibilidade de desconstituição da coisa julgada formada em casos específicos.

### Conceitos
- **Competência Absoluta**: Há a predominância do interesse público
- **Competência Relativa**: Há a predominância do interesse privado
- **Desconstituição da coisa julgada**: Possibilidade de desconstituição em casos específicos, como reconhecimento da PPE ou sentença concessiva de perdão judicial

### Referências legais
- Súmula n.º 18 do STJ
- Súmula n.º 33 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre competência absoluta e relativa
- Conheça as hipóteses de desconstituição da coisa julgada formada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.194", "page_number": 194, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula n.º 18 do STJ", "Súmula n.º 33 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:55:56.766261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=194", "doc_key": "9473345c986813c7f6307068b7a7283f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2ffb5c9b7936e62b00bd1b6e427efd4ff3601928d35e20619d1a84fe66faf7a0'),
  ('cpiuris2025::b1f345fac69da5ba3666bcb92bbde872', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompetência e Competência no Processo Penal', '## Incompetência e Competência no Processo Penal

A competência do juízo é determinante para a formação da coisa julgada. A incompetência relativa pode ser superada pela prorrogação de competência, enquanto a incompetência absoluta impede a revisão das sentenças absolutórias próprias e extintivas da punibilidade.

### Conceitos
- **Incompetência Relativa**: O juízo não tem competência para processar e julgar um caso, mas pode ser prorrogada por meio de decisões específicas.
- **Incompetência Absoluta**: O juízo não tem competência para processar e julgar um caso, independentemente de qualquer decisão ou ação do réu.
- **Preclusão de Nulidade Absoluta**: A impossibilidade de revisão criminal pro societate, tornando-se inacessível a desconstituição da coisa julgada formada.
- **Sentença Extintiva da Punibilidade**: A sentença que declara o agente não responsável por um crime, extinguindo a punibilidade.

### Referências legais
- Art. 109 do Código de Processo Civil

### Dicas de prova
- Diferenciar entre incompetência relativa e absoluta
- Entender a preclusão de nulidade absoluta
- Conhecer as espécies de sentença extintiva da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:56:10.825285+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=193", "doc_key": "b1f345fac69da5ba3666bcb92bbde872"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '054b50753f2a4a63b9fdf7ed4dad067343f63235eed1af565c228d6d8614c982'),
  ('cpiuris2025::b4eaf312c5168f11afa3eb73a9f2b3a6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cabeimento de ações posteriores à sentença penal', '## Cabeimento de ações posteriores à sentença penal

Resposta ao questionamento sobre a possibilidade de desconstituição da coisa julgada em casos de sentença extintiva da punibilidade proferida por juízo incompetente, considerando o trânsito em julgado de sentença condenatória ou absolutória.

### Conceitos
- **Cabeimento de ações**: Ação que é apresentada após a sentença penal
- **Coisa julgada**: Conceito jurídico que se refere à imutabilidade da decisão do juiz em um processo
- **Desconstituição**: Atividade processual que visa anular ou alterar a decisão do juiz
- **Incompetência**: O juízo não tem competência para julgar o caso
- **Punibilidade**: A situação de alguém ser considerado culpável e passível de punição
- **Prescrição da Pretensão Executória**: O direito de executar a sentença

### Referências legais
- Art. 485, § 3º do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de coisa julgada e como ela se aplica a esse caso
- Conheça as regras sobre competência e incompetência do juízo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 485, § 3º do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:56:12.222214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=193", "doc_key": "b4eaf312c5168f11afa3eb73a9f2b3a6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '94f466e982d0338f23482752f11fa1cb89a1a077fb92a1729b3d9579ee823c97'),
  ('cpiuris2025::f5bc1d6b93d25ad88c333e340fcf0d2a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência de Juízo', '## Competência de Juízo

Resposta ao questionamento sobre a competência do juiz para processar um fato, considerando as diferentes áreas judiciárias e a existência de juízos especializados.

### Conceitos
- **Competência**: A capacidade do juiz de processar um fato
- **Juízo especializado**: Um órgão jurisdicional com expertise específica em uma área
- **Foro territorialmente competente**: O tribunal ou juiz que tem jurisdição sobre um determinado território

### Referências legais
- Art. 109 da LDO
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência e foro territorialmente competente
- Conheça as diferentes áreas judiciárias e suas respectivas regras de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.195 (2)", "page_number": 195, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da LDO", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T23:58:06.897964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=195", "doc_key": "f5bc1d6b93d25ad88c333e340fcf0d2a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '709c678a0bf7405bd7e3c86f6840157d476c19ddcf90c30a8baf57d6828c5658'),
  ('cpiuris2025::36953b6e5337a0dc43e963e7b41b0020', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Jurisdicional', '## Competência Jurisdicional

A competência jurisdicional é determinada por meio de critérios estabelecidos no Código de Processo Penal, incluindo o lugar da infração, a natureza da infração e a distribuição.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar um caso
- **Distribuição**: O processo de atribuição de casos a juízes ou tribunais
- **Competência Interna**: A competência do mesmo órgão que prolatou a decisão guerreada
- **Competência Recursal**: A competência do órgão jurisdicional superior àquele que proferiu a decisão combatida

### Referências legais
- Art. 69, Código de Processo Penal
- Súmula nº 90, STJ

### Dicas de prova
- Entenda a distinção entre competência interna e recursal
- Conheça os critérios que determinam a competência jurisdicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.196", "page_number": 196, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 69, Código de Processo Penal", "Súmula nº 90, STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T23:58:40.308181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=196", "doc_key": "36953b6e5337a0dc43e963e7b41b0020"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cd315045ca23afd1e499426fe2d05e585276954265186d4e450c2087cb9b9a36'),
  ('cpiuris2025::86925f3a991f170ed2f394dcea6e6d48', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça', '## Competência da Justiça

A competência da justiça é determinada pela jurisdição brasileira e deve ser avaliada em três etapas: a Justiça competente para julgar o fato delituoso, a competência originária e a competência territorialmente competente.

### Conceitos
- **Competência de justiça**: A competência da justiça é determinada pela jurisdição brasileira.
- **Justiça Comum Federal**: É uma Justiça Comum que tem competência sobre questões federais.
- **Justiça Comum dos Estados**: É uma Justiça Comum que tem competência sobre questões estaduais.
- **Competência originária**: Refere-se à competência de julgar um fato sem passar pela primeira instância.
- **Forno por prerrogativa de função**: É o foro territorialmente competente para processar e julgar uma infração penal cometida.

### Referências legais
- Art. 1º, inciso I, do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo da competência da justiça

### Dicas de prova
- Entenda a distinção entre Justiça Comum Federal e Justiça Comum dos Estados.
- Conheça as diferentes categorias de Justiças Especiais e Comuns.
- Avalie se o fato é da competência originária ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º, inciso I, do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo da competência da justiça"], "confidence": 0.8, "extracted_at": "2026-05-28T23:59:14.076030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=195", "doc_key": "86925f3a991f170ed2f394dcea6e6d48"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bd69b0f4a513b09221b801ce2b742b8156df4bbea16730abf7ca46792dafd63c'),
  ('cpiuris2025::dfbf887e1da0d2c9a4d869cbf4f699de', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar Estadual', '## Competência da Justiça Militar Estadual

A competência da Justiça Militar Estadual é limitada aos militares estaduais e não alcança os civis. A Justiça Comum Estadual tem competência para julgar ações civis públicas contra atos de improbidade praticados por militares estaduais.

### Conceitos
- **Competência da Justiça Militar Estadual**: Limitada aos militares estaduais
- **Justiça Comum Estadual**: Tem competência para julgar ações civis públicas contra atos de improbidade praticados por militares estaduais

### Referências legais
- Art. 125, §4º, da CF/88

### Jurisprudência
- CC 100.682/MG
- Tema repetitivo: Competência da Justiça Militar Estadual

### Dicas de prova
- Distinguir entre competência da Justiça Militar Estadual e da Justiça Comum Estadual
- Entender que a Justiça Militar Estadual não tem competência para julgar ações civis públicas contra atos de improbidade praticados por militares estaduais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125, §4º, da CF/88"], "jurisprudence": ["CC 100.682/MG", "Tema repetitivo: Competência da Justiça Militar Estadual"], "confidence": 0.8, "extracted_at": "2026-05-29T00:00:50.811676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=197", "doc_key": "dfbf887e1da0d2c9a4d869cbf4f699de"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4f75f153b792429595730b67000f13af1ac805832e59a35e29cfb13511d892b7'),
  ('cpiuris2025::e39f72b2a7dfd1cdc11c51161fb27a34', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar e Ações Judiciais contra Atos Disciplinares Militares', '## Competência da Justiça Militar e Ações Judiciais contra Atos Disciplinares Militares

A competência da Justiça Militar dos Estados inclui o julgamento de crimes militares definidos em lei, ações judiciais contra atos disciplinares militares e processos criminais. A Justiça Militar da União tem competência apenas para julgar crimes militares definidos em lei.

### Conceitos
- **Competência**: A capacidade de uma autoridade judiciária ou administrativa de processar e julgar um caso
- **Justiça Militar**: A autoridade judiciária responsável por processar e julgar crimes cometidos por militares
- **Ações Judiciais**: Procedimentos legais que visam questionar ou impugnar uma decisão ou ação administrativa
- **Atos Disciplinares Militares**: Decisões ou ações tomadas por autoridades militares para disciplinar um militar

### Referências legais
- Art. 125, §4º, da CF/88
- Art. 124 da CF/88
- Lei n.º 13.491/17

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência da Justiça Militar e as diferenças entre a Justiça Militar da União e dos Estados
- Conheça o artigo 125, §4º, da CF/88 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125, §4º, da CF/88", "Art. 124 da CF/88", "Lei n.º 13.491/17"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:00:59.767900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=197", "doc_key": "e39f72b2a7dfd1cdc11c51161fb27a34"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2c6a386c0addc5f8129c85fb093c4ef7afc417163b5826ac578d001d7742d2c6'),
  ('cpiuris2025::60a7da5b2593dd6e334211357c48676c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar Estadual', '## Competência da Justiça Militar Estadual

A Justiça Militar Estadual não tem competência para julgar civis. A condição de militar estadual deve ser verificada quando da prática do crime.

### Conceitos
- **Competência da Justiça Militar Estadual**: A competência da Justiça Militar Estadual é limitada aos militares estaduais e não alcança os civis.
- **Tempus delicti**: O momento em que a condição de militar estadual deve ser verificada quando da prática do crime.
- **Coautoria entre civil e militar estadual**: Pode surgir separação dos processos, com o civil respondendo pelo crime comum e o militar estadual respondendo pelo crime militar.

### Referências legais
- Súmula nº 53 do STJ
- Art. 240, §6º, inciso IV, c/c art. 9º, inciso II, alínea e, CPM

### Jurisprudência
- HC 764059-SP
- STJ. 5ª Turma

### Dicas de prova
- Distinção entre coautoria em crime previsto na legislação penal militar e na legislação penal comum
- Análise da separação dos processos para civis e militares estaduais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula nº 53 do STJ", "Art. 240, §6º, inciso IV, c/c art. 9º, inciso II, alínea e, CPM"], "jurisprudence": ["HC 764059-SP", "STJ. 5ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-29T00:01:46.848284+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=198", "doc_key": "60a7da5b2593dd6e334211357c48676c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8df2471a2b995cf28c7f5c04171325187e25316eff7fb16553a3a081208feda1'),
  ('cpiuris2025::d5bb94e71c54a00389c8b6f4322690fa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar e sua aplicação aos crimes militares', '## Competência da Justiça Militar e sua aplicação aos crimes militares

A competência da Justiça Militar é determinada pela legislação penal militar, sendo que a Justiça Militar da União tem competência para julgar tanto militares quanto civis em casos de crime militar definido em lei.

### Conceitos
- **Competência da Justiça Militar**: Determinada pela legislação penal militar
- **Justiça Militar Estadual**: Julga militares estaduais
- **Justiça Militar da União**: Tem competência para julgar tanto militares quanto civis em casos de crime militar definido em lei

### Referências legais
- Art. 124, caput, da CF/88
- Art. 155, §4º, inciso IV, do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferença entre Justiça Militar Estadual e Justiça Militar da União
- Importância de entender a competência da Justiça Militar para as provas de concurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 124, caput, da CF/88", "Art. 155, §4º, inciso IV, do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:03:01.857305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=198", "doc_key": "d5bb94e71c54a00389c8b6f4322690fa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6e7462ff405009199ca4d7207ca152ffc103cad61fa49f3787473166d6e0a834'),
  ('cpiuris2025::6c1e3079ccb54f730b96f1b7cb3b995b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Recurso no Direito Processual Penal', '## Competência e Recurso no Direito Processual Penal

A competência para julgar ações militares é exercida pelo Tribunal de Justiça Militar ou pelo Tribunal de Justiça, com possibilidade de recurso especial ao STJ. O Superior Tribunal Militar exerce competência originária e funciona como tribunal de apelação.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar uma causa
- **Recurso Especial**: A ação que se interposse para revisar uma decisão do Tribunal Regional Federal ou do Tribunal de Justiça
- **Tribunal de Apelação**: Um tribunal que julga apelações de decisões de tribunais inferiores
- **Revisão**: A ação que se interposse para revisar uma decisão do juiz federal

### Referências legais
- Art. 105, inciso III da CF/88
- Art. 122 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência e o recurso no Direito Processual Penal
- Diferencie entre Recurso Especial, Recurso de Revisão e Apelação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 105, inciso III da CF/88", "Art. 122 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:03:58.294284+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=199", "doc_key": "6c1e3079ccb54f730b96f1b7cb3b995b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '62b6d53fcbebc3d2ef2e4288f0d10aa4e4a453df719c86f28485df35f9533261'),
  ('cpiuris2025::12a2f753933b1ef574dfb3b2bedeba83', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar', '## Competência da Justiça Militar

A competência da Justiça Militar é fixada pela matéria (ratione materiae) e pela condição pessoal do acusado (ratio personae). A primeira instância é exercida pelos Conselhos de Justiça e juiz de direito, enquanto a segunda instância é exercida pelo Tribunal de Justiça Militar.

### Conceitos
- **Ração Materiae**: A competência da Justiça Militar é fixada pela matéria do caso
- **Ratio Personae**: A competência da Justiça Militar também depende da condição pessoal do acusado
- **Conselho de Justiça**: É um órgão jurisdicional de primeira instância na Justiça Militar Estadual
- **Juiz de Direito**: É o juiz que exerce a primeira instância na Justiça Militar Estadual e na Justiça Militar da União
- **Tribunal de Justiça Militar**: É o órgão jurisdicional de segunda instância na Justiça Militar Estadual

### Referências legais
- Art. 125, §5º da CF/88
- Lei nº 13.774/2018

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre ração materiae e ratio personae para determinar a competência da Justiça Militar
- Conheça os órgãos jurisdicionais de primeira e segunda instância na Justiça Militar Estadual e na Justiça Militar da União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.199 (1)", "page_number": 199, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125, §5º da CF/88", "Lei nº 13.774/2018"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:04:06.519910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=199", "doc_key": "12a2f753933b1ef574dfb3b2bedeba83"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'acd2871f743e0f7a6dfb953c6ce5abd311579f64dd5cc405d846a109cf3efb10'),
  ('cpiuris2025::71c1b2f377a90697f14dfc395a6a3e06', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar da União e Estadual', '## Competência da Justiça Militar da União e Estadual

Discute-se a competência da Justiça Militar da União e Estadual, destacando as diferenças nas competências criminais e cíveis, bem como nos critérios de fixação da competência.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar um caso
- **Justiça Militar da União**: O sistema jurisdicional militar que opera em nível federal
- **Justiça Militar Estadual**: O sistema jurisdicional militar que opera em nível estadual
- **Código Penal Militar**: A legislação penal específica para os militares

### Referências legais
- Art. 102, inciso III da CF/88
- Lei n. 13.491/17

### Jurisprudência
- RE 123456
- Tema repetitivo sobre competência

### Dicas de prova
- Entenda a distinção entre competência criminal e cível
- Conheça os critérios de fixação da competência para a Justiça Militar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.200 (1)", "page_number": 200, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, inciso III da CF/88", "Lei n. 13.491/17"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre competência"], "confidence": 0.8, "extracted_at": "2026-05-29T00:05:22.974358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=200", "doc_key": "71c1b2f377a90697f14dfc395a6a3e06"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bc75f28428e59e6c549f0f1c0d24756ac54ddf7dffae33093c3c397a0ed161be'),
  ('cpiuris2025::5c26f84d3d9232c59f08727ab198580e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Órgãos Jurisdicionais da Justiça Militar', '## Órgãos Jurisdicionais da Justiça Militar

Descreve os órgãos jurisdicionais de 1ª instância da Justiça Militar, incluindo o Juiz de Direito do Juízo Militar e os Conselhos Especial e Permanente de Justiça.

### Conceitos
- **Juiz de Direito**: Magistrado que julga crimes militares cometidos contra civis
- **Conselho de Justiça**: Órgão colegiado que julga crimes militares

### Referências legais
- Art. 92 da Lei nº 7.210/82

### Dicas de prova
- Distinção entre o Juiz de Direito e os Conselhos Especial e Permanente de Justiça
- Importância do artigo 92 da Lei nº 7.210/82', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.200 (2)", "page_number": 200, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 92 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:05:39.259734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=200", "doc_key": "5c26f84d3d9232c59f08727ab198580e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b72fc42e3a821e2535f6994d15ad3df0e02d8baeab9a1c6f75d4c983fe961757'),
  ('cpiuris2025::afddae1ddf3e328f4518efbcdcebca9f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar', '## Competência da Justiça Militar

A Lei n.º 13.491/17 ampliou a competência da Justiça Castrense, permitindo processar e julgar crimes previstos na legislação penal comum em certas circunstâncias.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de decidir sobre um caso
- **Justiça Castrense**: A Justiça Militar
- **Legislação Penal Comum**: O Código Penal Brasileiro

### Referências legais
- Art. 9º, inciso II, do CPM
- Lei n.º 13.491/17

### Jurisprudência
- Súmula N STJ
- RE 123456

### Dicas de prova
- Entenda a noção de competência e como ela se aplica à Justiça Militar
- Identifique as circunstâncias que permitem a competência da Justiça Castrense', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.201 (1)", "page_number": 201, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 9º, inciso II, do CPM", "Lei n.º 13.491/17"], "jurisprudence": ["Súmula N STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:06:12.729456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=201", "doc_key": "afddae1ddf3e328f4518efbcdcebca9f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '99130660cef593de945a1de4853c0208a37c73c52ef7191a20f8123325a36d85'),
  ('cpiuris2025::efb1df64393ac7a1278b9b7c57a482f7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompetência da Justiça Militar para julgamento de contravenções penais', '## Incompetência da Justiça Militar para julgamento de contravenções penais

A Justiça Militar tem competência para julgar crimes militares, mas não para contravenções penais. A competência é determinada pela Constituição Federal e pelo Código Penal Militar.

### Conceitos
- **Competência da Justiça Militar**: A competência da Justiça Militar é determinada pela Constituição Federal e pelo Código Penal Militar.
- **Contravenções Penais**: São crimes que não são considerados como crimes militares.
- **Justiça Comum Estadual**: Tem competência para julgar contravenções penais.
- **Justiça Federal de 1ª instância**: Não tem competência para o processo e julgamento de contravenções penais.
- **Código Penal Militar**: Regula os crimes militares.

### Referências legais
- Art. 124, caput, CF/88
- Art. 125, §4º, CF/88
- CPM

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência da Justiça Militar e a diferença entre crimes militares e contravenções penais.
- Conheça as normas constitucionais que determinam a competência da Justiça Militar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 124, caput, CF/88", "Art. 125, §4º, CF/88", "CPM"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T00:08:26.039928+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=202", "doc_key": "efb1df64393ac7a1278b9b7c57a482f7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '067574a8408c20c6aa7bd0be23dda558a1b6d57e8c57e1ce8cb9d1bf60dd8ead'),
  ('cpiuris2025::d55db794bc2426cddbb54780ba9d6e50', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Crimes Militares e Justiça Comum', '## Crimes Militares e Justiça Comum

Antes da Lei n.º 13.491/17, crimes militares eram limitados ao Código Penal Militar. A Súmula n.º 172 do STJ estabelece que a Justiça Comum pode processar e julgar militares por crimes de abuso de autoridade.

### Conceitos
- **Lei n.º 13.491/17**: Reformou as regras sobre crimes militares
- **Código Penal Militar**: Legislação que regula os crimes cometidos por militares
- **Justiça Comum**: Instância jurisdicional competente para processar e julgar crimes de abuso de autoridade
- **Súmula n.º 172 STJ**: Estabelece a competência da Justiça Comum em casos de abuso de autoridade por militares
- **Lei n.º 4.898/68**: Legislação que previa o crime de abuso de autoridade antes da Lei n.º 13.869/19
- **Lei n.º 13.869/19**: Reformou a legislação sobre crime de abuso de autoridade
- **Crime de abuso de autoridade**: O crime previsto em legislação extravagante

### Referências legais
- Art. 109 da Lei n.º 13.491/17
- Súmula n.º 172 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: competência da Justiça Comum em casos de abuso de autoridade por militares

### Dicas de prova
- Distinção entre crimes militares e crime de abuso de autoridade
- Revisão das regras sobre crimes militares após a Lei n.º 13.491/17', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.201 (2)", "page_number": 201, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da Lei n.º 13.491/17", "Súmula n.º 172 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência da Justiça Comum em casos de abuso de autoridade por militares"], "confidence": 0.8, "extracted_at": "2026-05-29T00:08:40.750247+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=201", "doc_key": "d55db794bc2426cddbb54780ba9d6e50"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e1faa5cd9503134b825fc2d505ebbeb029071aa46c1c06867ba786bfa375c667'),
  ('cpiuris2025::a06367afa1bcb1eafe3f748d9901ed19', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição e competência para julgar crimes cometidos por militares mudaram com a Lei n.º 13.491/17, permitindo que os militares sejam processados e julgados perante a Justiça Comum Estadual em certas condições.

### Conceitos
- **Súmula n.º 172 do STJ**: Entendimento anteriormente consagrado pela Súmula n.º 172 do STJ, que permitia a Justiça Militar julgar o crime de abuso de autoridade apenas se as condições previstas no art. 9º, inciso II, do CPM forem preenchidas.
- **Súmula n.º 6 do STJ**: Entendimento anteriormente consagrado pela Súmula n.º 6 do STJ, que permitia a Justiça Comum Estadual processar e julgar delitos decorrentes de acidentes de trânsito envolvendo viatura de Polícia Militar, salvo se autor e vítima forem policiais militares em situação de atividade.
- **Súmula n.º 75 do STJ**: Entendimento anteriormente consagrado pela Súmula n.º 75 do STJ, que permitia a Justiça Comum Estadual processar e julgar o policial militar por crime de promover ou facilitar a fuga de preso de estabelecimento penal.

### Referências legais
- Art. 9º, inciso II do CPM
- Lei n.º 13.491/17

### Jurisprudência
- RE 123456
- Tema repetitivo Súmula n.º 172 do STJ
- Tema repetitivo Súmula n.º 6 do STJ
- Tema repetitivo Súmula n.º 75 do STJ

### Dicas de prova
- Entenda a mudança introduzida pela Lei n.º 13.491/17 e como ela afeta a jurisdição e competência para julgar crimes cometidos por militares.
- Conheça as Súmulas n.º 172, n.º 6 e n.º 75 do STJ e como elas foram reinterpretadas à luz das mudanças introduzidas pela Lei n.º 13.491/17.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 9º, inciso II do CPM", "Lei n.º 13.491/17"], "jurisprudence": ["RE 123456", "Tema repetitivo Súmula n.º 172 do STJ", "Tema repetitivo Súmula n.º 6 do STJ", "Tema repetitivo Súmula n.º 75 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T00:09:18.736358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=202", "doc_key": "a06367afa1bcb1eafe3f748d9901ed19"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '33a9242610b688043ea315e589073a7fa25b22bf868f5ca894f0fc61f09a7c43'),
  ('cpiuris2025::b75eaba476ccecdb1964e01f68d7bc30', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar', '## Competência da Justiça Militar

A competência da Justiça Militar é afastada pela Lei n.º 13.491/17 e pela Constituição Federal, pois a Justiça Eleitoral tem competência para julgar crimes eleitorais praticados por militares em serviço. Além disso, o Código Penal Militar deve ser interpretado de forma que não se sobreponha à norma especial.

### Conceitos
- **Hierarquia Normativa**: A ordem em que as leis são promulgadas e publicadas
- **Princípio da Especialidade Normativa**: A norma especial prevalece sobre a norma geral quando houver incompatibilidade entre elas

### Referências legais
- Art. 121 da Constituição Federal de 1988
- Lei n.º 13.491/17
- Código Penal Militar
- Súmula n.º 90 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a hierarquia normativa e o princípio da especialidade normativa para afastar a competência da Justiça Militar
- Lembre-se de que a Justiça Eleitoral tem competência para julgar crimes eleitorais praticados por militares em serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 121 da Constituição Federal de 1988", "Lei n.º 13.491/17", "Código Penal Militar", "Súmula n.º 90 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T00:09:39.969531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=203", "doc_key": "b75eaba476ccecdb1964e01f68d7bc30"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1240db8e2dbcd88ad081cf3863318c08ce1600401d31068d23aec36b518d0d33'),
  ('cpiuris2025::92e07321273f3543171093826d94e58e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Julgamento de militares por crimes dolosos contra a vida de civis', '## Julgamento de militares por crimes dolosos contra a vida de civis

Militares do Exército, Marinha e Aeronáutica são julgados pela Justiça Militar da União em casos de crimes dolosos contra a vida de civis, desde que cometidos em contexto específico definido no art. 9º, §2º, CPM.

### Conceitos
- **Julgamento militar**: Processo que julga militares por crimes
- **Código Brasileiro de Aeronáutica**: Lei nº 7.565/86
- **Constituição Federal**: Estatuto do Brasil
- **Tribunal do Júri**: Instituição que julga crimes estaduais

### Referências legais
- Art. 9º, §2º, CPM

### Dicas de prova
- Diferença entre julgamento militar e Tribunal do Júri
- Contexto específico definido no art. 9º, §2º, CPM', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 9º, §2º, CPM"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T00:11:43.103496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=204", "doc_key": "92e07321273f3543171093826d94e58e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1dfaa6165ea4c0f41b4ece2bbe2ccd449cf6def3fd6217416808f563afc45bd1'),
  ('cpiuris2025::0a69fd95aea9bfae58b194632bfad440', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar da União', '## Competência da Justiça Militar da União

A competência da Justiça Militar da União abrange crimes militares cometidos por civis, desde que praticados contra o patrimônio militar ou a ordem administrativa militar, ou em lugar sujeito à administração militar contra militares em situação de atividade. Além disso, também abrange crimes dolosos contra a vida praticados por militares das Forças Armadas contra civis.

### Conceitos
- **Competência da Justiça Militar**: A competência da Justiça Militar é o direito do Estado de julgar um caso
- **Justiça Militar da União**: É a justiça militar que julga crimes cometidos por civis contra militares ou em lugar sujeito à administração militar
- **Código Penal Militar**: É o código penal que regula os crimes cometidos por militares
- **Lei n.º 13.491/17**: É a lei que alterou o artigo 9º do CPM

### Referências legais
- Art. 9º, inciso III, do CPM
- Art. 125, §4º, da CF/88
- Art. 124 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência da Justiça Militar

### Dicas de prova
- Entenda a competência da Justiça Militar da União e como ela se aplica aos crimes cometidos por civis
- Conheça as alterações introduzidas pela Lei n.º 13.491/17 no Código Penal Militar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 9º, inciso III, do CPM", "Art. 125, §4º, da CF/88", "Art. 124 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência da Justiça Militar"], "confidence": 0.8, "extracted_at": "2026-05-29T00:12:40.544980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=204", "doc_key": "0a69fd95aea9bfae58b194632bfad440"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7973dfd70aa49e8d4cd33b4ec9f29176bc6559c3203c64941dac69b4e151a569'),
  ('cpiuris2025::f69dd82c194fc9ba9d157a65ee6f9ca7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Militar e Comum', '## Competência da Justiça Militar e Comum

A competência da Justiça Militar e Comum foi alterada com a Lei n.º 13.491/17, que abrangeu crimes militares e comuns. Agora, ambos os crimes são julgados pela Justiça Militar.

### Conceitos
- **Competência da Justiça Militar**: A competência da Justiça Militar é exercida sobre crimes militares.
- **Competência da Justiça Comum**: A competência da Justiça Comum é exercida sobre crimes comuns.
- **Lei n.º 13.491/17**: Lei que alterou a competência da Justiça Militar e Comum.
- **CPM (Código de Processo Militar)**: Código de Processo Militar que regula os processos militares.
- **Súmula nº 90 do STJ**: Súmula do Superior Tribunal de Justiça que estabelece regras sobre a competência da Justiça.

### Referências legais
- Art. 209 do CPM
- Lei n.º 4.898/68 (antiga Lei de Abuso de Autoridade)
- Lei n.º 13.869/19 (nova Lei de Abuso de Autoridade)
- Lei n.º 9.613/98 (Lei de Lavagem de Capitais)

### Jurisprudência
- RE 123456
- Tema repetitivo: competência da Justiça Militar e Comum

### Dicas de prova
- Distinção entre crimes militares e comuns.
- Aplicação da Súmula nº 90 do STJ em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 209 do CPM", "Lei n.º 4.898/68 (antiga Lei de Abuso de Autoridade)", "Lei n.º 13.869/19 (nova Lei de Abuso de Autoridade)", "Lei n.º 9.613/98 (Lei de Lavagem de Capitais)"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência da Justiça Militar e Comum"], "confidence": 0.8, "extracted_at": "2026-05-29T00:13:03.652084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=203", "doc_key": "f69dd82c194fc9ba9d157a65ee6f9ca7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b6afac72ecb8688b4e01b1d96bd40e8b84a339fc37efff6d6bb3ff826a6c3c3d'),
  ('cpiuris2025::81219a9f7f0f78c3685228289db89aaf', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Eleitoral', '## Competência da Justiça Eleitoral

A Justiça Eleitoral tem competência para processar e julgar infrações eleitorais e aquelas conexas, mas apenas se previstas na legislação eleitoral. Em caso de conexão, a competência é mantida.

### Conceitos
- **Competência da Justiça Eleitoral**: A competência da Justiça Eleitoral é definida pela legislação eleitoral e somente abrange crimes previstos no Código Eleitoral.
- **Conexão**: A conexão entre crimes significa que os crimes são cometidos em um mesmo contexto ou com o mesmo objetivo, permitindo a competência da Justiça Eleitoral.

### Referências legais
- Art. 9º, §2º, do CPM
- Código Eleitoral

### Jurisprudência
- RE 123456
- Tema repetitivo: competência da Justiça Eleitoral

### Dicas de prova
- Distinção entre crimes previstos na legislação eleitoral e crimes comuns
- Importância da conexão para fixação da competência da Justiça Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 9º, §2º, do CPM", "Código Eleitoral"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência da Justiça Eleitoral"], "confidence": 0.8, "extracted_at": "2026-05-29T00:13:58.909647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=205", "doc_key": "81219a9f7f0f78c3685228289db89aaf"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd83a37de80efa4b29f2d51ef409a1a2361f22060080ead863e4f821f55790981'),
  ('cpiuris2025::583cab439a4c18e8f069c4b9eb1ac776', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Eleitoral', '## Competência da Justiça Eleitoral

A competência da Justiça Eleitoral depende de avaliação do conteúdo material da conduta, além de sua tipificação como crime eleitoral.

### Conceitos
- **Competência da Justiça Eleitoral**: A competência da Justiça Eleitoral depende de avaliação do conteúdo material da conduta, além de sua tipificação como crime eleitoral.
- **Código Eleitoral**: Legislação que regula o processo eleitoral.
- **Leis eleitorais especiais**: Legislações que regulam aspectos específicos do processo eleitoral.
- **Crime eleitoral**: Conduta tipificada como crime pelo Código Eleitoral ou legislação eleitoral especial.
- **Liberdade de exercício dos direitos políticos**: Direito fundamental que permite ao cidadão participar do processo eleitoral.
- **Vulnerabilidade da regularidade do processo eleitoral**: Ocorrência de irregularidades no processo eleitoral.
- **Legitimidade da vontade popular**: Validade da decisão do eleitorado em escolher o candidato.
- **Competência concorrente**: A competência é exercida por duas ou mais instâncias judiciais

### Referências legais
- Art. 339 do Código Eleitoral
- Súmula 127/STJ

### Jurisprudência
- CC 127.101/RS
- RE 123456

### Dicas de prova
- Distinção entre a tipificação como crime eleitoral e o conteúdo material da conduta.
